using namespace Tyra;

// The content stamp declared by inc/bag_array.gen.hpp. Every BagArray
// mutation takes the next value and the engine reads it back through
// StaPipBag::contentVersion, so the baked VIF stream cannot replay a block
// whose source array was rewritten. It is a SEPARATE counter from
// g_bboxStamp because that one means "the bounding box moved" and
// StapipBagBBoxesCacher is its consumer - conflating the two is exactly the
// defect this closes. It lives OUTSIDE the anonymous namespace below,
// because the header declares it `extern`. docs/bag-content-version.md.
extern unsigned int g_contentStamp;

namespace runtime_detail {

inline constexpr float PI = 3.14159265358979F;

// WRITE-ON-CHANGE for a batch the frame rebuilds from scratch (the light
// beams, the vehicle headlight pools, halos and glow). Every write through a
// BagArray moves its content stamp, and a moved stamp re-stages the bag
// instead of replaying its baked VIF stream - so a batch that writes the SAME
// bytes every frame pays the re-stage every frame for nothing. This compares
// first, through the const data() (which does not stamp), and writes only a
// slot whose bytes differ. Bit comparison on purpose: equal bits in means an
// identical stream out, and a NaN can only ever cause a write.
template <class T>
bool bagWriteIfChanged(BagArray<T>& arr, size_t at, const T* src, size_t n) {
  if (n == 0) return false;
  if (arr.size() < at + n) arr.resize(at + n);
  else if (memcmp(arr.data() + at, src, n * sizeof(T)) == 0) return false;
  auto dst = arr.span(at, n);
  for (size_t i = 0; i < n; ++i) dst[i] = src[i];
  return true;
}

// Display-mode option rows (bind 5): the engine mode an option drives, and
// the option a mode shows as. Every such row carries an optModes table (codegen
// fills a short one in positionally); a table entry of -1 is the "DEFAULT"
// option - the project-default boot mode.
inline int displayOptionMode(const MenuEntryData& en, int idx) {
  if (en.optModes && idx >= 0 && idx < en.optionCount) {
    const int m = en.optModes[idx];
    return m < 0 ? g_defaultDispMode : m;
  }
  return idx;
}
inline int displayOptionIndexOf(const MenuEntryData& en, int mode) {
  for (int i = 0; i < en.optionCount; ++i)
    if (displayOptionMode(en, i) == mode) return i;
  return -1;
}

/** The texture repository asserts (crashes) on a missing file - probe first
 * so a missing PNG degrades to an untextured draw with a warning. */
inline bool assetFileExists(const std::string& cwdRel) {
  FILE* f = fopen(FileUtils::fromCwd(cwdRel).c_str(), "rb");
  if (f) fclose(f);
  return f != nullptr;
}

/** Per-object rendering cut-off (Properties > Draw distance) measured from
 * the object center - the cheapest LOD. Draw-time only: collision, sounds
 * and scripts elsewhere never consult this. 0 = unlimited. */
inline bool beyondDrawDistance(const SceneObjectData& d, const Vec4& cam) {
  if (d.drawDistance <= 0.0F) return false;
  const float dx = d.position[0] - cam.x;
  const float dy = d.position[1] - cam.y;
  const float dz = d.position[2] - cam.z;
  return dx * dx + dy * dy + dz * dz > d.drawDistance * d.drawDistance;
}

struct V3 {
  float x, y, z;
};

/** The six sines and cosines rotated() needs, so a caller that rotates
 * several vectors through the SAME angles pays the trigonometry once.
 * cosf/sinf are software routines on the EE and are not `const`-attributed
 * with errno enabled, so the compiler may not hoist them out of a loop by
 * itself - see renderVehicleWheels(), which rotated twenty vectors per car
 * through one attitude and paid for it twenty times. */
struct RotTrig {
  float cx, sx, cy, sy, cz, sz;
};

inline RotTrig rotTrigOf(const float* rotDeg) {
  RotTrig t;
  const float rx = rotDeg[0] * PI / 180.0F;
  const float ry = rotDeg[1] * PI / 180.0F;
  const float rz = rotDeg[2] * PI / 180.0F;
  t.cx = cosf(rx), t.sx = sinf(rx);
  t.cy = cosf(ry), t.sy = sinf(ry);
  t.cz = cosf(rz), t.sz = sinf(rz);
  return t;
}

/** rotated() with the trigonometry already done. The three stages run in the
 * same order on the same operands as below, so this is BIT-IDENTICAL to
 * rotated() and not merely equivalent - which is what lets a caller swap to
 * it without moving a pixel. */
inline V3 rotatedBy(const V3& v, const RotTrig& t) {
  V3 r = v;
  {
    const float y = r.y * t.cx - r.z * t.sx, z = r.y * t.sx + r.z * t.cx;
    r.y = y, r.z = z;
  }
  {
    const float x = r.x * t.cy + r.z * t.sy, z = -r.x * t.sy + r.z * t.cy;
    r.x = x, r.z = z;
  }
  {
    const float x = r.x * t.cz - r.y * t.sz, y = r.x * t.sz + r.y * t.cz;
    r.x = x, r.y = y;
  }
  return r;
}

/** Rotation order: X, then Y, then Z (same as the editor viewport). */
inline V3 rotated(const V3& v, const float* rotDeg) {
  return rotatedBy(v, rotTrigOf(rotDeg));
}

/** Inverse of rotated(): -Z, then -Y, then -X (world -> object local). */
inline V3 invRotated(const V3& v, const float* rotDeg) {
  V3 r = v;
  const float rx = rotDeg[0] * PI / 180.0F;
  const float ry = rotDeg[1] * PI / 180.0F;
  const float rz = rotDeg[2] * PI / 180.0F;
  {
    const float c = cosf(rz), s = -sinf(rz);
    const float x = r.x * c - r.y * s, y = r.x * s + r.y * c;
    r.x = x, r.y = y;
  }
  {
    const float c = cosf(ry), s = -sinf(ry);
    const float x = r.x * c + r.z * s, z = -r.x * s + r.z * c;
    r.x = x, r.z = z;
  }
  {
    const float c = cosf(rx), s = -sinf(rx);
    const float y = r.y * c - r.z * s, z = r.y * s + r.z * c;
    r.y = y, r.z = z;
  }
  return r;
}

// The box's frame: R(rotation) * Ryaw(modelYaw). The content-forward
// correction turns the MESH between scale and rotation (see the animated model
// matrix in updateAndRenderAnimObjects), so it has to turn the mesh's box too -
// without it an X-forward-authored character collided and blocked the camera
// across its own body.
inline V3 boxRotate(const V3& v, const SceneObjectData& d) {
  V3 p = v;
  if (d.modelYaw != 0.0F) {
    const float a = d.modelYaw * (PI / 180.0F);
    const float c = cosf(a), s = sinf(a);
    p = {p.x * c + p.z * s, p.y, -p.x * s + p.z * c};
  }
  return rotated(p, d.rotation);
}

inline V3 boxInvRotate(const V3& v, const SceneObjectData& d) {
  V3 p = invRotated(v, d.rotation);
  if (d.modelYaw != 0.0F) {
    const float a = -d.modelYaw * (PI / 180.0F);
    const float c = cosf(a), s = sinf(a);
    p = {p.x * c + p.z * s, p.y, -p.x * s + p.z * c};
  }
  return p;
}


/** Directional light (Project > Preferences), baked into vertex colors.
 * Returns per-channel multipliers: brightness * (ambient + diffuse*d*lightColor). */
inline V3 shadeOf(const V3& n) {
  float d = n.x * SCENE_LIGHT_X + n.y * SCENE_LIGHT_Y + n.z * SCENE_LIGHT_Z;
  if (d < 0.0F) d = 0.0F;
  const float base = SCENE_DIFFUSE * d;
  V3 s = {SCENE_BRIGHTNESS * (SCENE_AMBIENT + base * SCENE_LIGHT_COL_R),
          SCENE_BRIGHTNESS * (SCENE_AMBIENT + base * SCENE_LIGHT_COL_G),
          SCENE_BRIGHTNESS * (SCENE_AMBIENT + base * SCENE_LIGHT_COL_B)};
  if (s.x > 1.0F) s.x = 1.0F;
  if (s.y > 1.0F) s.y = 1.0F;
  if (s.z > 1.0F) s.z = 1.0F;
  return s;
}

/** Baked light probes (docs/global-illumination.md). The scene lightmap
 * covers static untextured geometry; this covers everything else - imported
 * models, textured receivers, physics bodies, spawn-pool clones and (once per
 * frame rather than once at load) animated models.
 *
 * One sample is L1 spherical harmonics: L0, the average radiance, plus L1,
 * its direction. giShade below is the clamped-cosine convolution
 *   shade(n) = L0 + (2/3) * dot(L1, n)
 * which returns exactly L for a uniform environment of radiance L, and goes
 * to zero looking away from a bright hemisphere. The host reference is
 * gibake::sampleProbes and the viewport fragment shader's giProbe() is the
 * third copy - change one, change all three. */
struct GiSample {
  float l0[3];
  float l1[3][3];  // [axis][channel]
};

/** True when the active scene has a probe grid AND the point is inside it
 * with at least one live neighbour. Weighted trilinear over the 8 surrounding
 * probes; a probe buried in solid geometry weighs nothing, so a wall's black
 * interior never bleeds into the room next to it. */
inline bool giProbeAt(float wx, float wy, float wz, GiSample& out) {
  const GiProbeGridData* g = SCENE_PROBES;
  if (!g || g->dim[0] <= 0) return false;
  const float p[3] = {wx, wy, wz};
  int i0[3];
  float f[3];
  for (int k = 0; k < 3; ++k) {
    const float step = g->step[k] > 0.000001F ? g->step[k] : 1.0F;
    float t = (p[k] - g->origin[k]) / step;
    if (t < 0.0F) t = 0.0F;
    if (t > (float)(g->dim[k] - 1)) t = (float)(g->dim[k] - 1);
    i0[k] = (int)t;
    if (i0[k] > g->dim[k] - 2) i0[k] = g->dim[k] - 2 < 0 ? 0 : g->dim[k] - 2;
    f[k] = g->dim[k] > 1 ? t - (float)i0[k] : 0.0F;
  }
  float acc[12] = {0};
  float wsum = 0.0F;
  for (int c = 0; c < 8; ++c) {
    const int dx = c & 1, dy = (c >> 1) & 1, dz = (c >> 2) & 1;
    int ix = i0[0] + dx, iy = i0[1] + dy, iz = i0[2] + dz;
    if (ix > g->dim[0] - 1) ix = g->dim[0] - 1;
    if (iy > g->dim[1] - 1) iy = g->dim[1] - 1;
    if (iz > g->dim[2] - 1) iz = g->dim[2] - 1;
    const int idx = ix + g->dim[0] * (iy + g->dim[1] * iz);
    if (!g->live[idx]) continue;
    const float w = (dx ? f[0] : 1.0F - f[0]) * (dy ? f[1] : 1.0F - f[1]) *
                    (dz ? f[2] : 1.0F - f[2]);
    if (w <= 0.0F) continue;
    wsum += w;
    const signed char* sh = g->sh + idx * 12;
    for (int k = 0; k < 12; ++k) acc[k] += w * (float)sh[k];
  }
  if (wsum <= 0.00001F) return false;
  const float dec = g->scale / (127.0F * wsum);
  for (int k = 0; k < 3; ++k) {
    out.l0[k] = acc[k] * dec;
    out.l1[0][k] = acc[3 + k] * dec;
    out.l1[1][k] = acc[6 + k] * dec;
    out.l1[2][k] = acc[9 + k] * dec;
  }
  return true;
}

inline V3 giShade(const GiSample& s, const V3& n) {
  float c[3];
  for (int k = 0; k < 3; ++k) {
    float t = s.l0[k] + (2.0F / 3.0F) * (s.l1[0][k] * n.x + s.l1[1][k] * n.y +
                                         s.l1[2][k] * n.z);
    if (t < 0.0F) t = 0.0F;
    if (t > 1.0F) t = 1.0F;
    c[k] = t;
  }
  return V3{c[0], c[1], c[2]};
}

// The three VU1 slots are Cartesian SH basis terms, each with an RGB
// coefficient. Signed normals survive until the final RGB sum is clamped.
inline void giSHLights(const GiSample& sample, const float* live, const float* albedo,
                float scale, Vec4* directions, Vec4* colors) {
  directions[0].set(1.0F, 0.0F, 0.0F, 0.0F);
  directions[1].set(0.0F, 1.0F, 0.0F, 0.0F);
  directions[2].set(0.0F, 0.0F, 1.0F, 0.0F);
  for (int axis = 0; axis < 3; ++axis)
    colors[axis].set(scale * (2.0F / 3.0F) * sample.l1[axis][0] * albedo[0],
                     scale * (2.0F / 3.0F) * sample.l1[axis][1] * albedo[1],
                     scale * (2.0F / 3.0F) * sample.l1[axis][2] * albedo[2], 0.0F);
  colors[3].set(scale * (sample.l0[0] + live[0]) * albedo[0],
                scale * (sample.l0[1] + live[1]) * albedo[1],
                scale * (sample.l0[2] + live[2]) * albedo[2], 128.0F);
}

/** Staged by the geometry builders: this surface's light comes from the probe
 * grid, so the ambient + directional term, the baked point lights and the
 * emissive pools must ALL stay out of its vertex colors - the probe already
 * contains every one of them. */
inline bool g_giProbeShade = false;

/** Dynamic lighting (docs/global-illumination.md): this object renders through
 * the LIT VU1 program, so pushVert must NOT bake any light into its color -
 * VU1 does the shading from the per-frame light bag. What it collects instead
 * is the per-vertex NORMAL that program needs, in the space the bag's light
 * matrix expects: local for a g_bakeLocal object (physics bodies keep local
 * vertices plus a world matrix, so VU1 rotates the normal too), world for
 * everything else (its matrix is identity). Getting that space wrong does not
 * crash - it lights the object as if it never turned. */
inline BagArray<Vec4>* g_litNormals = nullptr;

/** ...and this one: the surface's light comes from the scene LIGHTMAP, per
 * pixel through the additive atlas pass. Its vertex shade is black; the pass
 * puts the whole thing back. */
inline bool g_giLightmap = false;

/** ...and this one: the surface's light is already IN ITS TEXTURE
 * (docs/prelit-models.md - litbake multiplied the scene's gathered light into
 * this object's own map_Kd on the host). Its vertex colour is therefore
 * NEUTRAL: not black like the lightmap route, which has a pass coming to put
 * the light back, but plain white, because the texture is the finished
 * article. The dynamic light - the flashlight's pool, its cone, the live point
 * lights - still lands on top at run time. */
inline bool g_prelitTex = false;

/** Point lights (SceneObject type 9) of the active scene, collected once per
 * scene load. pointLightAt runs PER VERTEX while baking terrain chunks and
 * object meshes; scanning the whole SCENE_OBJECTS table there thrashes the
 * EE's 16 KB dcache on big scenes - an 1100-object scene cost ~170 ms per
 * 16x16 terrain chunk (a visible hitch on every chunk-border crossing).
 * Lights are static authored data, so the tiny list is exact. */
struct BakedPointLight {
  V3 pos;
  float color[3];
  float radius, bright;
};
inline std::vector<BakedPointLight> g_scenePointLights;

/** Dynamic point lights (type 9 + lightDynamic): NOT baked - registered with
 * the engine every frame (updateDynLights), so they can flicker, move with
 * their runtime object and be switched by the Set Light flow node. The
 * engine lights each mesh with its strongest dynamic light (one VU1 light
 * slot per mesh; the camera flashlight competes in the same pick). */
struct DynLightRt {
  int objIndex;            // index into SCENE_OBJECTS / ctx.objects
  bool on = true;          // Set Light switch (persists until changed)
  float intensity = 1.0F;  // Set Light multiplier on the authored brightness
  // This frame's effective multiplier (intensity * flicker; 0 = off/hidden),
  // written by updateDynLights - the visible light beams reuse it so the
  // corona breathes with the pool of light.
  float lastLevel = 1.0F;
  // The engine slot this light took this frame (-1 = not registered: off,
  // hidden, dark) - what a receiver names to be skipped by the slot pick.
  int slot = -1;
};
inline std::vector<DynLightRt> g_dynLights;
inline float g_dynLightTime = 0.0F;
// The starfield's own clock. It cannot borrow g_dynLightTime: that one only
// advances while the scene HAS dynamic lights, so a night sky over an unlit
// scene would freeze mid-shimmer.
inline float g_starTime = 0.0F;

inline void collectScenePointLights() {
  g_scenePointLights.clear();
  g_dynLights.clear();
  for (int i = 0; i < SCENE_OBJECT_COUNT; ++i) {
    const SceneObjectData& L = SCENE_OBJECTS[i];
    if (L.type != 9) continue;
    if (L.lightDynamic) {
      if ((int)g_dynLights.size() < (int)Tyra::RendererCore::DYN_LIGHTS_MAX) {
        DynLightRt d;
        d.objIndex = i;
        g_dynLights.push_back(d);
      }
      continue;  // never baked - the engine lights it live
    }
    BakedPointLight b;
    b.pos = {L.position[0], L.position[1], L.position[2]};
    b.color[0] = L.color[0];
    b.color[1] = L.color[1];
    b.color[2] = L.color[2];
    b.radius = L.lightRadius > 0.01F ? L.lightRadius : 0.01F;
    b.bright = L.lightBright;
    g_scenePointLights.push_back(b);
  }
}

/** Applies Set Light requests and registers this frame's dynamic point
 * lights with the engine (additive VU1 lighting, 128 = +1.0 - roughly the
 * baked lights' scale). Runs every frame before beginFrame in both loops.
 * Hidden / streamed-out light objects go dark; flicker is a two-sine wobble
 * phase-offset per light, frozen while a pausing menu owns the frame. */
inline void updateDynLights(Tyra::Engine* engine, ScriptContext& ctx) {
  auto& core = engine->renderer.core;
  core.clearDynLights();
  if (g_dynLights.empty()) return;
  if (!g_gameplayPaused) g_dynLightTime += g_frameDt;
  for (DynLightRt& L : g_dynLights) {
    if (ctx.lightRequest && ctx.lightRequest[L.objIndex] >= 0) {
      L.on = ctx.lightRequest[L.objIndex] != 0;
      ctx.lightRequest[L.objIndex] = -1;
    }
    if (ctx.lightIntensity && ctx.lightIntensity[L.objIndex] >= 0.0F) {
      L.intensity = ctx.lightIntensity[L.objIndex];
      ctx.lightIntensity[L.objIndex] = -1.0F;
    }
    L.lastLevel = 0.0F;
    L.slot = -1;
    if (!L.on || !ctx.objects || L.objIndex >= ctx.objectCount) continue;
    const RuntimeObject& ro = ctx.objects[L.objIndex];
    if (!ro.visible || !ro.active) continue;
    const SceneObjectData& d = ro.data;  // live copy - Move Object works
    float mult = L.intensity;
    if (d.lightFlicker > 0.0F) {
      const float p = (float)(L.objIndex % 7) * 1.9F;
      float w = 0.5F + 0.35F * sinf(g_dynLightTime * 11.7F + p) +
                0.15F * sinf(g_dynLightTime * 23.3F + p * 2.1F);
      if (w < 0.0F) w = 0.0F;
      if (w > 1.0F) w = 1.0F;
      mult *= 1.0F - d.lightFlicker * (1.0F - w);
    }
    L.lastLevel = mult;
    const float k = d.lightBright * mult;
    if (k <= 0.0F) continue;
    auto ch = [&](float c) {
      float v = c * 128.0F * k;
      return v > 255.0F ? 255.0F : v;
    };
    if (d.lightSpot) {
      // The cone points down the object's local -Y: unrotated, a lamp
      // shines straight down; the rotation gizmo aims it.
      const V3 sd = rotated({0.0F, -1.0F, 0.0F}, d.rotation);
      L.slot = core.addDynSpotLight(
          Tyra::Color(ch(d.color[0]), ch(d.color[1]), ch(d.color[2])),
          Tyra::Vec4(d.position[0], d.position[1], d.position[2], 1.0F),
          Tyra::Vec4(sd.x, sd.y, sd.z, 0.0F),
          d.lightRadius > 0.01F ? d.lightRadius : 0.01F, d.lightSpotAngle,
          1.6F);
    } else {
      core.addDynPointLight(
          Tyra::Color(ch(d.color[0]), ch(d.color[1]), ch(d.color[2])),
          Tyra::Vec4(d.position[0], d.position[1], d.position[2], 1.0F),
          d.lightRadius > 0.01F ? d.lightRadius : 0.01F);
    }
  }
}

/** Samples the dynamic lights (scene point lights + flashlight) at a world
 * point, 0..1 per channel - the animated models' cheap pickup: one sample
 * per model per frame added to its ambient term, instead of per-vertex VU1
 * work (the lit anim programs have no spot slot). The flashlight's cone is
 * a rough cos test at model scale; the falloff mirrors the VU1 shape. */
inline void dynLightAt(Tyra::Engine* engine, float wx, float wy, float wz,
                float out[3]) {
  out[0] = out[1] = out[2] = 0.0F;
  auto& core = engine->renderer.core;
  const Tyra::RendererCoreSpotLight* ls[Tyra::RendererCore::DYN_LIGHTS_MAX + 1];
  u32 n = 0;
  if (core.spot.enabled) ls[n++] = &core.spot;
  for (u32 i = 0; i < core.dynLightCount; i++) ls[n++] = &core.dynLights[i];
  for (u32 i = 0; i < n; i++) {
    const auto* l = ls[i];
    const float dx = wx - l->position.x;
    const float dy = wy - l->position.y;
    const float dz = wz - l->position.z;
    const float d2 = dx * dx + dy * dy + dz * dz;
    const float r2 = l->range * l->range;
    if (d2 >= r2) continue;
    float att = 1.0F - d2 / r2;
    if (!l->point) {
      const float d = sqrtf(d2);
      if (d > 1e-4F) {
        const float ca = (dx * l->direction.x + dy * l->direction.y +
                          dz * l->direction.z) /
                         d;
        if (ca < l->cosCutoff) att *= 0.15F;  // soft outside the beam
      }
    }
    out[0] += l->color.r * (1.0F / 128.0F) * att;
    out[1] += l->color.g * (1.0F / 128.0F) * att;
    out[2] += l->color.b * (1.0F / 128.0F) * att;
  }
}

/** Point lights baked additively on top of the directional term. Linear
 * distance falloff * N.L, tinted by the light color and scaled by its
 * brightness. wp = world-space vertex position. */
inline V3 pointLightAt(const V3& wp, const V3& n) {
  V3 add = {0.0F, 0.0F, 0.0F};
  for (const BakedPointLight& L : g_scenePointLights) {
    V3 d = {L.pos.x - wp.x, L.pos.y - wp.y, L.pos.z - wp.z};
    const float dist = sqrtf(d.x * d.x + d.y * d.y + d.z * d.z);
    if (dist >= L.radius) continue;
    float atten = 1.0F - dist / L.radius;
    atten *= atten;  // softer, rounder pool of light
    float ndotl = 1.0F;
    if (dist > 0.0001F) {
      ndotl = (n.x * d.x + n.y * d.y + n.z * d.z) / dist;
      if (ndotl < 0.0F) ndotl = 0.0F;
    }
    const float k = L.bright * atten * ndotl;
    add.x += k * L.color[0];
    add.y += k * L.color[1];
    add.z += k * L.color[2];
  }
  return add;
}

/** Ambient occlusion (docs/ambient-occlusion.md): analytic occluders - the
 * SCENE_AO_OCC table the editor bakes from the solid authored objects
 * (oriented boxes / spheres) - plus terrain contact darkening, evaluated per
 * vertex while geometry bakes. Multiplies the directional shade BEFORE point
 * lights add on top, so light pools stay bright. The editor viewport runs the
 * same formula per fragment (viewport.cpp fragment shader) - keep in sync. */
inline std::vector<const AoOccData*> g_aoLocal;  // pruned per object/terrain chunk

// Experimental textured AO: while g_aoAtlas is staged, pushVert emits atlas
// STs (the primitive's face UVs mapped into its SCENE_AO_ATLAS_RECTS region)
// into g_aoSts instead of multiplying the occlusion into the vertex colors -
// the lightmap pass samples it per pixel. The builders bump g_aoRegion in
// their emission order (box 6 faces, sphere 1, cylinder 3, cone 2, plane 2 -
// mirrored by aobake::bakeSceneLightAtlas on the host; keep in sync).
inline bool g_aoAtlas = false;
// ...and whether its LIGHT channel has content: the additive lightmap pass
// draws only then, and only then may pushVert leave the emissive light out of
// the vertex colors (a textured receiver keeps the per-vertex light - see
// aobake, SceneLightAtlas::lit).
inline bool g_emisAtlas = false;
inline const AoAtlasRect* g_aoAtlasRects = nullptr;
inline int g_aoRegion = 0;
inline BagArray<Vec4>* g_aoSts = nullptr;
// Imported models: AO receive/self fully off for now (see the staging in
// rebuildObjectGeometry) - per-vertex occlusion looks triangulated there.
inline bool g_aoOff = false;

/** Distance from a world point to an analytic shape's SURFACE plus the unit
 * direction toward it. Both the occlusion and the emissive-light response are
 * built on this one query (the host's aobake::occShapeAt is the twin, and the
 * viewport fragment shader mirrors it as well - change one, change all three).
 * AoOccData and EmisLightData share the shape prefix, so the template takes
 * either. */
template <class Shape>
void occShapeAt(const Shape& oc, const V3& wp, float& dist, V3& toOcc) {
  const V3 rel = {wp.x - oc.pos[0], wp.y - oc.pos[1], wp.z - oc.pos[2]};
  if (oc.sphere) {
    const float d = sqrtf(rel.x * rel.x + rel.y * rel.y + rel.z * rel.z);
    dist = d - oc.half[0];
    if (d > 0.0001F)
      toOcc = {-rel.x / d, -rel.y / d, -rel.z / d};
    else
      toOcc = {0.0F, 1.0F, 0.0F};
  } else {
    // into the box frame, clamp onto the box, back out to world
    const float lx = rel.x * oc.ax[0] + rel.y * oc.ax[1] + rel.z * oc.ax[2];
    const float ly = rel.x * oc.ay[0] + rel.y * oc.ay[1] + rel.z * oc.ay[2];
    const float lz = rel.x * oc.az[0] + rel.y * oc.az[1] + rel.z * oc.az[2];
    const float qx = lx < -oc.half[0] ? -oc.half[0] : (lx > oc.half[0] ? oc.half[0] : lx);
    const float qy = ly < -oc.half[1] ? -oc.half[1] : (ly > oc.half[1] ? oc.half[1] : ly);
    const float qz = lz < -oc.half[2] ? -oc.half[2] : (lz > oc.half[2] ? oc.half[2] : lz);
    const float dvx = lx - qx, dvy = ly - qy, dvz = lz - qz;
    dist = sqrtf(dvx * dvx + dvy * dvy + dvz * dvz);
    if (dist > 0.0001F) {
      const float wx = dvx * oc.ax[0] + dvy * oc.ay[0] + dvz * oc.az[0];
      const float wy = dvx * oc.ax[1] + dvy * oc.ay[1] + dvz * oc.az[1];
      const float wz = dvx * oc.ax[2] + dvy * oc.ay[2] + dvz * oc.az[2];
      toOcc = {-wx / dist, -wy / dist, -wz / dist};
    } else {
      toOcc = {0.0F, 1.0F, 0.0F};
    }
  }
}

/** The locality window every occlusion term closes with; occlusion past the
 * AO radius is deliberately not counted. Twin of aobake::aoRangeWindow. */
inline float aoRangeWindow(float dist, float range) {
  if (dist >= range) return 0.0F;
  float t = (range - dist) / (0.4F * range);
  if (t >= 1.0F) return 1.0F;
  if (t < 0.0F) t = 0.0F;
  return t * t * (3.0F - 2.0F * t);
}

/** The one number between the geometry and the picture: a surface resting on a
 * floor really does lose half its hemisphere, but there is no indirect light
 * here to put back, so the finished occlusion is scaled once. Twin of
 * aobake::kAoBounce - the two must not drift. */
inline constexpr float kAoBounce = 0.7F;

/** Radius of a disc with the same PROJECTED AREA as the shape, seen along
 * `toOcc`. Twin of aobake::occProjRadius. */
inline float aoProjRadius(const AoOccData& oc, const V3& toOcc) {
  if (oc.sphere) return oc.half[0];
  const float* ax[3] = {oc.ax, oc.ay, oc.az};
  float a = 0.0F;
  for (int k = 0; k < 3; ++k) {
    float c = toOcc.x * ax[k][0] + toOcc.y * ax[k][1] + toOcc.z * ax[k][2];
    if (c < 0.0F) c = -c;
    a += c * 4.0F * oc.half[(k + 1) % 3] * oc.half[(k + 2) % 3];
  }
  return sqrtf(a * (1.0F / 3.14159265F));
}

/** Occlusion contribution of one occluder at a surface point (0..1) - how much
 * of the surface's cosine-weighted hemisphere the shape covers, NOT how close
 * it is. Twin of aobake::occluderOcclusionAt and of aoOcclusion in the
 * viewport shader; the reasoning and the measurements are in aobake.cpp. */
inline float aoOccluderAt(const AoOccData& oc, const V3& wp, const V3& n) {
  float dist;
  V3 toOcc;  // direction from the point toward the occluder surface
  occShapeAt(oc, wp, dist, toOcc);
  if (dist <= 0.0F) return 1.0F;  // touching / inside
  if (dist >= SCENE_AO_RADIUS) return 0.0F;
  const float cosT = n.x * toOcc.x + n.y * toOcc.y + n.z * toOcc.z;
  float r = aoProjRadius(oc, toOcc);
  if (r > SCENE_AO_RADIUS) r = SCENE_AO_RADIUS;
  if (r <= 0.00001F) return 0.0F;

  // Two regimes, picked by the shape's angular radius. Far and small it is a
  // disc taking cos(theta) of its solid angle; near and large it is a
  // HALF-SPACE, which needs no aiming - what a plane blocks is the hemisphere
  // behind its face, (1 + n.toOcc)/2. k = sin(alpha) carries the surface
  // between them and k*k is the solid angle, and BOTH factors are needed: on k
  // alone a crate 0.6 units away hands a horizontal surface the plane's 0.5,
  // and a ring of neighbours then reads as half the sky gone on a crate top
  // with nothing above it. See aobake.cpp for the measurements.
  const float k = r / (r + dist);
  const float lit = (cosT > 0.0F) ? cosT : 0.0F;
  const float plane = (1.0F + cosT) * 0.5F;
  float occ = k * k * (lit + (plane - lit) * k);
  if (occ < 0.0F) occ = 0.0F;
  if (occ > 1.0F) occ = 1.0F;
  return occ * aoRangeWindow(dist, SCENE_AO_RADIUS);
}

/** Occlusion over the pruned local list (+ the terrain contact term for object
 * geometry) -> shade multiplier. groundTerm is off for the terrain itself -
 * the ground doesn't sit next to itself.
 *
 * Blockers combine as VISIBILITY (the product of what each leaves open), not
 * as a clamped sum: a sum saturates, which is what let a neighbouring box and
 * the ground between them black out a surface each of them only half covers.
 * Twin of aobake::aoAccumVis and of the viewport shader. */
inline float aoShadeMul(const V3& wp, const V3& n, bool groundTerm) {
  if (!SCENE_AO_ENABLED) return 1.0F;
  float vis = 1.0F;
  for (const AoOccData* oc : g_aoLocal) vis *= 1.0F - aoOccluderAt(*oc, wp, n);
  if (groundTerm) {
    float dy = wp.y - terrainHeightAt(wp.x, wp.z);
    if (dy < 0.0F) dy = 0.0F;
    if (dy < SCENE_AO_RADIUS) {
      // The SAME half-space the occluder response falls back to: the ground
      // is a plane whose toOcc points straight down, so (1 + n.toOcc)/2 is
      // (1 - n.y)/2 - which is what this term always was, under its own
      // constant. One shape, one spelling now.
      float horiz = 0.5F - 0.5F * n.y;
      if (horiz < 0.0F) horiz = 0.0F;
      vis *= 1.0F - horiz * aoRangeWindow(dy, SCENE_AO_RADIUS);
    }
  }
  float occ = kAoBounce * (1.0F - vis);
  if (occ > 1.0F) occ = 1.0F;
  return 1.0F - SCENE_AO_STRENGTH * occ;
}

/** Prunes the scene occluder table around a world-space bounding sphere.
 * The point-light dcache lesson applies: never scan the whole table per
 * vertex - collect the handful in range once per object/chunk. */
inline void aoCollectLocal(float cx, float cy, float cz, float radius, int selfIndex) {
  g_aoLocal.clear();
  if (!SCENE_AO_ENABLED) return;
  const AoOccData* tbl = SCENE_AO_OCC;
  for (int i = 0; i < SCENE_AO_OCC_COUNT; ++i) {
    const AoOccData& oc = tbl[i];
    if (oc.objIndex == selfIndex) continue;
    const float dx = oc.pos[0] - cx;
    const float dy = oc.pos[1] - cy;
    const float dz = oc.pos[2] - cz;
    const float reach =
        radius + SCENE_AO_RADIUS +
        sqrtf(oc.half[0] * oc.half[0] + oc.half[1] * oc.half[1] +
              oc.half[2] * oc.half[2]);
    if (dx * dx + dy * dy + dz * dz <= reach * reach) g_aoLocal.push_back(&oc);
  }
}

/** Emissive lights (docs/emissive-materials.md): objects whose material both
 * glows and declares a reach light the geometry around them. Baked into the
 * vertex colors exactly like the directional and point lights - the ambient
 * occlusion treatment in reverse, sharing its analytic shapes and its
 * once-per-object pruning (the dcache lesson above applies unchanged: never
 * scan the whole table per vertex). */
inline std::vector<const EmisLightData*> g_emisLocal;
// Occluders that can SHADOW those emitters - the same analytic shapes the
// ambient occlusion uses (per-object "Cast shadow"), pruned by the EMITTER
// reach rather than SCENE_AO_RADIUS, so it cannot share g_aoLocal. Collected
// whether or not the project bakes occlusion.
inline std::vector<const AoOccData*> g_emisBlock;

/** Does the segment from `origin` along unit `dir` for `maxT` units enter the
 * shape? Slab test for a box, quadratic for a sphere. Twin of
 * aobake::shapeBlocksRay and of shadowHit in the viewport shader. */
inline bool shapeBlocksRay(const AoOccData& oc, const V3& origin, const V3& dir,
                    float maxT) {
  const V3 rel = {origin.x - oc.pos[0], origin.y - oc.pos[1],
                  origin.z - oc.pos[2]};
  if (oc.sphere) {
    const float b = rel.x * dir.x + rel.y * dir.y + rel.z * dir.z;
    const float c = rel.x * rel.x + rel.y * rel.y + rel.z * rel.z -
                    oc.half[0] * oc.half[0];
    if (c < 0.0F) return true;   // origin inside
    if (b > 0.0F) return false;  // behind the ray
    const float disc = b * b - c;
    if (disc < 0.0F) return false;
    const float t = -b - sqrtf(disc);
    return t >= 0.0F && t <= maxT;
  }
  const float* ax[3] = {oc.ax, oc.ay, oc.az};
  float t0 = 0.0F, t1 = maxT;
  for (int k = 0; k < 3; ++k) {
    const float e = rel.x * ax[k][0] + rel.y * ax[k][1] + rel.z * ax[k][2];
    const float f = dir.x * ax[k][0] + dir.y * ax[k][1] + dir.z * ax[k][2];
    if (fabsf(f) < 0.000001F) {
      if (e < -oc.half[k] || e > oc.half[k]) return false;  // parallel, outside
      continue;
    }
    float ta = (-oc.half[k] - e) / f;
    float tb = (oc.half[k] - e) / f;
    if (ta > tb) {
      const float tmp = ta;
      ta = tb;
      tb = tmp;
    }
    if (ta > t0) t0 = ta;
    if (tb < t1) t1 = tb;
    if (t0 > t1) return false;
  }
  return true;
}

inline void emisCollectLocal(float cx, float cy, float cz, float radius,
                      int selfIndex) {
  g_emisLocal.clear();
  const EmisLightData* tbl = SCENE_EMIS;
  if (!tbl) return;
  for (int i = 0; i < SCENE_EMIS_COUNT; ++i) {
    const EmisLightData& em = tbl[i];
    // An emitter never lights itself - its own emissive floor already holds
    // the surface at full brightness, and a self-contribution would only
    // wash the color out.
    if (em.objIndex == selfIndex) continue;
    const float dx = em.pos[0] - cx;
    const float dy = em.pos[1] - cy;
    const float dz = em.pos[2] - cz;
    const float reach =
        radius + em.range +
        sqrtf(em.half[0] * em.half[0] + em.half[1] * em.half[1] +
              em.half[2] * em.half[2]);
    if (dx * dx + dy * dy + dz * dz <= reach * reach) g_emisLocal.push_back(&em);
  }
  // Shadow casters within reach of any surviving emitter. The receiver's own
  // occluder is excluded (the ray starts on its surface); the emitter's own is
  // skipped per emitter in emissiveLightAt (the ray ends on it).
  g_emisBlock.clear();
  const AoOccData* occ = SCENE_AO_OCC;
  if (g_emisLocal.empty() || !occ) return;
  float maxRange = 0.0F;
  for (const EmisLightData* em : g_emisLocal)
    if (em->range > maxRange) maxRange = em->range;
  for (int i = 0; i < SCENE_AO_OCC_COUNT; ++i) {
    const AoOccData& oc = occ[i];
    if (oc.objIndex == selfIndex) continue;
    const float dx = oc.pos[0] - cx;
    const float dy = oc.pos[1] - cy;
    const float dz = oc.pos[2] - cz;
    const float reach =
        radius + maxRange +
        sqrtf(oc.half[0] * oc.half[0] + oc.half[1] * oc.half[1] +
              oc.half[2] * oc.half[2]);
    if (dx * dx + dy * dy + dz * dz <= reach * reach) g_emisBlock.push_back(&oc);
  }
}

/** Light the pruned local emitters add at a surface point. Quadratic falloff
 * from the emitter SHAPE (not its center, so a long neon strip lights evenly
 * along its length) times N.L. Twin of aobake::emitterLightAt on the host and
 * of emissiveLight() in the viewport shader. */
inline V3 emissiveLightAt(const V3& wp, const V3& n) {
  V3 add = {0.0F, 0.0F, 0.0F};
  for (const EmisLightData* em : g_emisLocal) {
    float dist;
    V3 toEm;
    occShapeAt(*em, wp, dist, toEm);
    if (dist >= em->range) continue;
    // Solids between the surface and the emitter block it outright (hard
    // shadows - a wall throws a rectangle, not its silhouette). The bias keeps
    // a solid resting ON this surface from shadowing it with its contact face.
    if (!g_emisBlock.empty() && dist > 0.02F) {
      const V3 o = {wp.x + toEm.x * 0.02F, wp.y + toEm.y * 0.02F,
                    wp.z + toEm.z * 0.02F};
      const float len = dist - 0.04F;
      bool blocked = false;
      for (const AoOccData* oc : g_emisBlock) {
        if (oc->objIndex == em->objIndex) continue;  // the source itself
        if (shapeBlocksRay(*oc, o, toEm, len)) {
          blocked = true;
          break;
        }
      }
      if (blocked) continue;
    }
    if (dist < 0.0F) dist = 0.0F;  // touching / inside: full strength
    float fade = 1.0F - dist / em->range;
    fade *= fade;
    // Facing weight: half-Lambert SQUARED - these are AREA sources, so a plain
    // max(0, N.L) would seam on every box corner, and a linear wrap still hits
    // zero at a finite angle (a hard shading edge in a dark scene). Smooth
    // everywhere, zero only at N.L = -1, side-on lands at 0.25. Twin of
    // aobake::emitterLightAt and the viewport's emissiveLight - the occluder
    // term above deliberately keeps its own linear 0.35 wrap.
    float w = 0.5F + 0.5F * (n.x * toEm.x + n.y * toEm.y + n.z * toEm.z);
    if (w <= 0.0F) continue;
    w *= w;
    const float k = em->bright * fade * w;
    add.x += k * em->color[0];
    add.y += k * em->color[1];
    add.z += k * em->color[2];
  }
  return add;
}

// Material context for the primitive builders: addBox & co call pushVert
// without material args, so rebuildObjectGeometry stages the object's
// assigned material here before dispatching. Model parts pass theirs
// explicitly via the kd/textured parameters instead.
inline const float* g_primKd = nullptr;
inline bool g_primTextured = false;
// Emission (Ke) of the staged primitive material, null = matte. Model parts
// pass theirs explicitly through pushVert's keArg, like kd.
inline const float* g_primKe = nullptr;
// Texture atlasing: the staged material's UV rect ("# tyra-uvrect" in the
// baked .mtl), applied to the primitive builders' generated 0..1 UVs.
// nullptr = identity. Model parts never use it - LeanObjLoader already
// remapped their UVs at load.
inline const float* g_primUvRect = nullptr;
// Physics fast path: push LOCAL-space positions (scale baked, rotation and
// translation left to ObjectGeometry::objMat). Shading still bakes from the
// full wake pose, so the switch itself never pops a color.
inline bool g_bakeLocal = false;

// Reflective materials: while non-null, pushVert also captures the rotated
// (world-space) normal of every emitted vertex - the per-frame sphere-map ST
// computation needs them (see renderScene). Staged per part like g_primKd.
inline BagArray<Vec4>* g_envNormals = nullptr;

// Loaded materials/model parts using the "@sky" dynamic env map. While > 0,
// renderScene renders the sky dome into the engine's env-map target each
// frame (the GT3 trick - reflections follow the live sky).
inline int g_dynamicEnvUsers = 0;

// Every rebuilt vertex buffer gets a process-unique bbox version. The
// engine's frustum-bbox cache is keyed by (vertex pointer, version); layer
// streaming frees and reallocates buffers, so with per-bag counters a
// recycled heap address could arrive with the dead buffer's exact version
// and inherit its cached boxes - packages misclassify (objects smear or
// vanish) or the package index runs past the cached part count (the
// stapip_bag_packages_bbox assert). One monotonic stamp shared by every
// bag makes each (pointer, version) pair unique for the whole run.
inline u32 g_bboxStamp = 0;

// The SECOND version - about CONTENTS rather than about the bounding box - is
// declared in inc/bag_array.gen.hpp and DEFINED just below the namespace
// opening above, deliberately outside this anonymous namespace: the header
// declares it `extern`, and a definition in here would have internal linkage
// and never resolve. See docs/bag-content-version.md.

// Clip-name resolution for scripts/flow graph: ScriptContext carries a plain
// function pointer (script.hpp must stay engine-agnostic), so the game
// instance is reached through this file-static (set in buildScene).
inline TerrainGame* g_animGame = nullptr;
inline int animResolveClipThunk(int objectIndex, const char* clipName) {
  return g_animGame ? g_animGame->resolveClipIndex(objectIndex, clipName) : -1;
}

// Dynamic spawn pool size: at most this many live clones (Spawn Object flow
// node) on top of the authored scene objects. Slots are recycled on despawn.
inline constexpr int MAX_SPAWNED_OBJECTS = 32;
inline int spawnObjectThunk(int templateIndex, float x, float y, float z, float yaw) {
  return g_animGame ? g_animGame->spawnObjectAt(templateIndex, x, y, z, yaw)
                    : -1;
}
inline void despawnObjectThunk(int objectIndex) {
  if (g_animGame) g_animGame->despawnObjectAt(objectIndex);
}
// Prefabs and runtime procedural volumes reach the flow graphs the same way:
// through ScriptContext function pointers, so a generated script never needs
// to know TerrainGame exists.
inline int spawnPrefabThunk(int prefabIndex, float x, float y, float z, float yaw,
                     float scale) {
  return g_animGame ? g_animGame->spawnPrefabAt(prefabIndex, x, y, z, yaw, scale)
                    : -1;
}
inline void despawnPrefabsThunk(int prefabIndex) {
  if (g_animGame) g_animGame->despawnPrefabsNamed(prefabIndex);
}
inline void generateVolumeThunk(int volumeIndex, int seed, bool clear) {
  if (!g_animGame) return;
  if (clear)
    g_animGame->procClearVolume(volumeIndex);
  else
    g_animGame->procGenerateVolume(volumeIndex, seed);
}

// kd: material diffuse (MTL) multiplied into the object color, null = white.
// ke: material emission (MTL Ke), null/zero = matte - see the floor below.
// textured: this batch draws with a texture (a model part's map_Kd or a
// primitive material's) - switches the color to modulation scale (128 = 1.0).
inline void pushVert(BagArray<Vec4>& verts, BagArray<Color>& cols,
              BagArray<Vec4>& sts, const SceneObjectData& o, V3 p, V3 n,
              float u, float v, const float* kdArg = nullptr,
              bool texturedArg = false, unsigned char selfAo = 255,
              const float* keArg = nullptr) {
  const float* kd = kdArg ? kdArg : g_primKd;
  const float* ke = keArg ? keArg : g_primKe;
  const bool textured = texturedArg || g_primTextured;
  p.x *= o.scale[0], p.y *= o.scale[1], p.z *= o.scale[2];
  const V3 lp = p;  // local (scaled) position - what g_bakeLocal pushes
  const V3 ln = n;  // ...and the matching un-rotated normal
  p = rotated(p, o.rotation);
  n = rotated(n, o.rotation);
  const V3 wp = {p.x + o.position[0], p.y + o.position[1], p.z + o.position[2]};
  // Global illumination takes the whole shade over when it owns the surface
  // (docs/global-illumination.md): black here for a lightmapped one - the
  // additive atlas pass puts every photon back per pixel - and the probe
  // irradiance for one on the vertex path. Either way the ambient +
  // directional term is already inside the baked answer, so it must not be
  // added a second time here.
  V3 shade;
  GiSample giSample;
  bool giHere = false;
  if (g_litNormals) {
    // VU1 lights this one. Its color must carry the ALBEDO only - the light
    // arrives per frame through the bag, and doubling it here is the same
    // mistake the lightmap/probe routes are arranged to avoid.
    g_litNormals->push_back(g_bakeLocal ? Vec4(ln.x, ln.y, ln.z, 0.0F)
                                        : Vec4(n.x, n.y, n.z, 0.0F));
    shade = {1.0F, 1.0F, 1.0F};
    giHere = true;
  } else if (g_prelitTex) {
    // The texture IS the lit surface (docs/prelit-models.md). NEUTRAL, not
    // black: the lightmap route below goes black because a pass is coming to
    // put the light back, and here nothing is coming - the modulate has to
    // leave the texture exactly as it was baked.
    shade = {1.0F, 1.0F, 1.0F};
    giHere = true;
  } else if (g_giLightmap) {
    shade = {0.0F, 0.0F, 0.0F};
    giHere = true;
  } else if (g_giProbeShade && giProbeAt(wp.x, wp.y, wp.z, giSample)) {
    shade = giShade(giSample, n);
    giHere = true;
  } else {
    shade = shadeOf(n);
  }
  // Ambient occlusion multiplies the directional shade BEFORE the point
  // lights add on top (light pools stay bright inside dark corners). selfAo
  // is the model's baked raycast self-occlusion (255 = open). With the
  // textured mode staged, the occlusion arrives per pixel through the atlas
  // pass instead - only the ST for it is emitted here.
  // Scene lightmap: with an atlas region staged, BOTH the occlusion and the
  // emissive light arrive per pixel through the atlas passes - only the ST is
  // emitted here, and neither term may also land in the vertex color or it
  // would be applied twice.
  if (g_aoAtlas) {
    if (g_aoSts) {
      const AoAtlasRect& rc = g_aoAtlasRects[g_aoRegion];
      g_aoSts->push_back(Vec4(rc.u0 + u * rc.du, rc.v0 + v * rc.dv, 1.0F, 0.0F));
    }
  } else if (SCENE_AO_ENABLED && !g_aoOff && !g_litNormals) {
    // No vertex AO on a dynamically lit object either: it is contact
    // darkening measured at the spawn, and this object's whole premise is
    // that it does not stay there.
    float aoM = aoShadeMul(wp, n, true);
    if (selfAo != 255)
      aoM *= 1.0F - SCENE_AO_STRENGTH * (1.0F - selfAo * (1.0F / 255.0F));
    shade.x *= aoM, shade.y *= aoM, shade.z *= aoM;
  }
  // Baked point lights and emissive pools sit on top of the AO-multiplied
  // directional term - unless GI already answered for this surface, in which
  // case both are inside that answer.
  if (!giHere) {
    const V3 pl = pointLightAt(wp, n);
    shade.x += pl.x, shade.y += pl.y, shade.z += pl.z;
    if (!g_emisAtlas) {
      const V3 el = emissiveLightAt(wp, n);
      shade.x += el.x, shade.y += el.y, shade.z += el.z;
    }
  }
  if (shade.x > 1.0F) shade.x = 1.0F;
  if (shade.y > 1.0F) shade.y = 1.0F;
  if (shade.z > 1.0F) shade.z = 1.0F;
  if (kd) shade.x *= kd[0], shade.y *= kd[1], shade.z *= kd[2];
  // Emissive materials (MTL "Ke", docs/emissive-materials.md): a per-channel
  // FLOOR under the finished shade, applied last - so the surface ignores the
  // sun, ambient occlusion and point lights on the way DOWN and keeps its own
  // color in a pitch-black scene, while a brighter lit result still wins. The
  // object tint multiplies on top below, exactly as it does for the lit path
  // (viewport.cpp's uEmissive is the GL twin - keep them in sync).
  if (ke) {
    if (shade.x < ke[0]) shade.x = ke[0];
    if (shade.y < ke[1]) shade.y = ke[1];
    if (shade.z < ke[2]) shade.z = ke[2];
  }
  verts.push_back(g_bakeLocal ? Vec4(lp.x, lp.y, lp.z, 1.0F)
                              : Vec4(wp.x, wp.y, wp.z, 1.0F));
  // In textured mode the color modulates the texture (128 = 1.0). Kd may
  // exceed 1 (material brightness) - cap at the GS's 255 so untextured
  // colors cannot wrap.
  const float scale = textured ? 128.0F : 255.0F;
  auto c255 = [](float v) { return v > 255.0F ? 255.0F : v; };
  cols.push_back(Color(c255(o.color[0] * scale * shade.x),
                       c255(o.color[1] * scale * shade.y),
                       c255(o.color[2] * scale * shade.z), 128.0F));
  // staged-material path only (kdArg = a model part whose UVs the loader
  // already remapped)
  if (!kdArg && g_primUvRect)
    sts.push_back(Vec4(g_primUvRect[0] + u * g_primUvRect[2],
                       g_primUvRect[1] + v * g_primUvRect[3], 1.0F, 0.0F));
  else
    sts.push_back(Vec4(u, v, 1.0F, 0.0F));
  // LOCAL normal in a local-space bake: on the matrix path the object's
  // rotation is applied per frame by folding it into the env pass's camera
  // basis (renderEnvPass), so a world normal frozen at the promotion pose
  // here would pin the reflection to wherever the car happened to point.
  if (g_envNormals)
    g_envNormals->push_back(g_bakeLocal ? Vec4(ln.x, ln.y, ln.z, 0.0F)
                                        : Vec4(n.x, n.y, n.z, 0.0F));
}

inline void pushQuad(BagArray<Vec4>& verts, BagArray<Color>& cols,
              BagArray<Vec4>& sts, const SceneObjectData& o, V3 a, V3 b, V3 c,
              V3 d, V3 n) {
  pushVert(verts, cols, sts, o, a, n, 0, 0);
  pushVert(verts, cols, sts, o, b, n, 1, 0);
  pushVert(verts, cols, sts, o, c, n, 1, 1);
  pushVert(verts, cols, sts, o, a, n, 0, 0);
  pushVert(verts, cols, sts, o, c, n, 1, 1);
  pushVert(verts, cols, sts, o, d, n, 0, 1);
}

inline void addBox(BagArray<Vec4>& verts, BagArray<Color>& cols,
            BagArray<Vec4>& sts, const SceneObjectData& o) {
  // Detail = subdivisions per edge (1 = plain 6-quad box); each face is an
  // n x n grid, UVs span 0..1 per face. Mirror of the editor's unitBox.
  const int n = o.primDetail < 1 ? 1 : (o.primDetail > 16 ? 16 : o.primDetail);
  const float h = 0.5F, H = 1.0F;
  int aoFace = 0;  // atlas region per face (+X,-X,+Y,-Y,+Z,-Z)
  auto face = [&](V3 c0, V3 du, V3 dv, V3 nrm) {
    g_aoRegion = aoFace++;
    for (int i = 0; i < n; ++i)
      for (int j = 0; j < n; ++j) {
        const float s0 = (float)i / n, s1 = (float)(i + 1) / n;
        const float t0 = (float)j / n, t1 = (float)(j + 1) / n;
        auto P = [&](float s, float t) -> V3 {
          return {c0.x + du.x * s + dv.x * t, c0.y + du.y * s + dv.y * t,
                  c0.z + du.z * s + dv.z * t};
        };
        // Front/back V=0 at the top, matching primmesh and the light atlas.
        const float v0 = nrm.z != 0 ? 1.0F - t0 : t0;
        const float v1 = nrm.z != 0 ? 1.0F - t1 : t1;
        pushVert(verts, cols, sts, o, P(s0, t0), nrm, s0, v0);
        pushVert(verts, cols, sts, o, P(s1, t0), nrm, s1, v0);
        pushVert(verts, cols, sts, o, P(s1, t1), nrm, s1, v1);
        pushVert(verts, cols, sts, o, P(s0, t0), nrm, s0, v0);
        pushVert(verts, cols, sts, o, P(s1, t1), nrm, s1, v1);
        pushVert(verts, cols, sts, o, P(s0, t1), nrm, s0, v1);
      }
  };
  face({h, -h, -h}, {0, H, 0}, {0, 0, H}, {1, 0, 0});    // +X
  face({-h, -h, h}, {0, H, 0}, {0, 0, -H}, {-1, 0, 0});  // -X
  face({-h, h, -h}, {0, 0, H}, {H, 0, 0}, {0, 1, 0});    // +Y
  face({-h, -h, h}, {0, 0, -H}, {H, 0, 0}, {0, -1, 0});  // -Y
  face({-h, -h, h}, {H, 0, 0}, {0, H, 0}, {0, 0, 1});    // +Z
  face({h, -h, -h}, {-H, 0, 0}, {0, H, 0}, {0, 0, -1});  // -Z
}

inline void addSphere(BagArray<Vec4>& verts, BagArray<Color>& cols,
               BagArray<Vec4>& sts, const SceneObjectData& o) {
  // Detail = radial segments; stacks ~5:7 of that (mirror of the editor's
  // primSphereStacks in project.hpp - keep the two in sync).
  int slices = o.primDetail < 3 ? 3 : (o.primDetail > 64 ? 64 : o.primDetail);
  int stacks = slices * 5 / 7;
  if (stacks < 2) stacks = 2;
  const float r = 0.5F;
  g_aoRegion = 0;  // the whole sphere is one atlas region (unique UVs)
  for (int st = 0; st < stacks; ++st) {
    const float t0 = PI * st / stacks, t1 = PI * (st + 1) / stacks;
    const float tv0 = (float)st / stacks, tv1 = (float)(st + 1) / stacks;
    for (int sl = 0; sl < slices; ++sl) {
      const float p0 = 2.0F * PI * sl / slices, p1 = 2.0F * PI * (sl + 1) / slices;
      const float tu0 = (float)sl / slices, tu1 = (float)(sl + 1) / slices;
      const V3 v00 = {r * sinf(t0) * cosf(p0), r * cosf(t0), r * sinf(t0) * sinf(p0)};
      const V3 v01 = {r * sinf(t0) * cosf(p1), r * cosf(t0), r * sinf(t0) * sinf(p1)};
      const V3 v10 = {r * sinf(t1) * cosf(p0), r * cosf(t1), r * sinf(t1) * sinf(p0)};
      const V3 v11 = {r * sinf(t1) * cosf(p1), r * cosf(t1), r * sinf(t1) * sinf(p1)};
      // Smooth shading: normal of a unit-sphere vertex is the vertex itself.
      const V3 n00 = {v00.x * 2, v00.y * 2, v00.z * 2};
      const V3 n01 = {v01.x * 2, v01.y * 2, v01.z * 2};
      const V3 n10 = {v10.x * 2, v10.y * 2, v10.z * 2};
      const V3 n11 = {v11.x * 2, v11.y * 2, v11.z * 2};
      pushVert(verts, cols, sts, o, v00, n00, tu0, tv0);
      pushVert(verts, cols, sts, o, v10, n10, tu0, tv1);
      pushVert(verts, cols, sts, o, v11, n11, tu1, tv1);
      pushVert(verts, cols, sts, o, v00, n00, tu0, tv0);
      pushVert(verts, cols, sts, o, v11, n11, tu1, tv1);
      pushVert(verts, cols, sts, o, v01, n01, tu1, tv0);
    }
  }
}

inline void addCylinder(BagArray<Vec4>& verts, BagArray<Color>& cols,
                 BagArray<Vec4>& sts, const SceneObjectData& o) {
  const int seg = o.primDetail < 3 ? 3 : (o.primDetail > 64 ? 64 : o.primDetail);
  // Rings along the axis (mirror of primCylinderStacks in project.hpp - keep
  // the two in sync), opt-in per object. Without them every vertex-baked term
  // that varies with HEIGHT - a baked point light overhead, the contact
  // darkening at the foot, a probe gradient - is one linear ramp per segment
  // quad, and its diagonal seam paints a full-height stripe that more radial
  // detail only makes narrower. With nothing lighting the cylinder vertically
  // they are triangles no shading reads, hence the flag rather than always-on.
  int rings = 1;
  if (o.primRings) {
    rings = seg / 4;
    if (rings < 1) rings = 1;
  }
  const float r = 0.5F, h = 0.5F;
  for (int i = 0; i < seg; ++i) {
    const float a0 = 2.0F * PI * i / seg, a1 = 2.0F * PI * (i + 1) / seg;
    const float u0 = (float)i / seg, u1 = (float)(i + 1) / seg;
    const float x0 = r * cosf(a0), z0 = r * sinf(a0);
    const float x1 = r * cosf(a1), z1 = r * sinf(a1);
    const V3 n0 = {cosf(a0), 0, sinf(a0)}, n1 = {cosf(a1), 0, sinf(a1)};
    // side (smooth) - atlas region 0
    g_aoRegion = 0;
    for (int k = 0; k < rings; ++k) {
      const float tt = (float)k / rings, tb = (float)(k + 1) / rings;
      const float yt = h - 2.0F * h * tt, yb = h - 2.0F * h * tb;
      pushVert(verts, cols, sts, o, {x0, yb, z0}, n0, u0, tb);
      pushVert(verts, cols, sts, o, {x0, yt, z0}, n0, u0, tt);
      pushVert(verts, cols, sts, o, {x1, yt, z1}, n1, u1, tt);
      pushVert(verts, cols, sts, o, {x0, yb, z0}, n0, u0, tb);
      pushVert(verts, cols, sts, o, {x1, yt, z1}, n1, u1, tt);
      pushVert(verts, cols, sts, o, {x1, yb, z1}, n1, u1, tb);
    }
    // caps (planar mapping) - atlas regions 1 (+Y) and 2 (-Y)
    g_aoRegion = 1;
    pushVert(verts, cols, sts, o, {0, h, 0}, {0, 1, 0}, 0.5F, 0.5F);
    pushVert(verts, cols, sts, o, {x1, h, z1}, {0, 1, 0}, x1 + 0.5F, z1 + 0.5F);
    pushVert(verts, cols, sts, o, {x0, h, z0}, {0, 1, 0}, x0 + 0.5F, z0 + 0.5F);
    g_aoRegion = 2;
    pushVert(verts, cols, sts, o, {0, -h, 0}, {0, -1, 0}, 0.5F, 0.5F);
    pushVert(verts, cols, sts, o, {x0, -h, z0}, {0, -1, 0}, x0 + 0.5F, z0 + 0.5F);
    pushVert(verts, cols, sts, o, {x1, -h, z1}, {0, -1, 0}, x1 + 0.5F, z1 + 0.5F);
  }
}

// Debug "show areas" (DEBUG_SHOW_AREAS): an Area object has no geometry in the
// game, so the volume you drew is invisible exactly when you need to see where
// its edge runs - "why did this layer not unload", "why is that crate not
// reflecting". This draws the box's 12 edges as thin beams, i.e. the same
// wireframe the editor viewport shows. Twelve addBox calls rather than a mesh
// of its own: an edge IS a box (its length along one axis, `t` on the other
// two, parked at one of the four parallel corners), and going through addBox
// keeps the transform, lighting and vertex format identical to every other
// primitive. A wireframe and not a translucent solid on purpose - a filled
// volume hides the very objects you opened it to look at.
inline void addAreaWireframe(BagArray<Vec4>& verts, BagArray<Color>& cols,
                      BagArray<Vec4>& sts, const SceneObjectData& o) {
  const float ax = o.scale[0] < 0.0F ? -o.scale[0] : o.scale[0];
  const float ay = o.scale[1] < 0.0F ? -o.scale[1] : o.scale[1];
  const float az = o.scale[2] < 0.0F ? -o.scale[2] : o.scale[2];
  float big = ax > ay ? ax : ay;
  if (az > big) big = az;
  float t = big * 0.012F;  // beam thickness: readable at any zone size
  if (t < 0.04F) t = 0.04F;
  for (int axis = 0; axis < 3; ++axis) {
    const int u = (axis + 1) % 3, v = (axis + 2) % 3;
    for (int corner = 0; corner < 4; ++corner) {
      SceneObjectData e = o;
      e.primDetail = 1;  // a beam needs no subdivision
      float off[3] = {0.0F, 0.0F, 0.0F};
      off[u] = ((corner & 1) ? 0.5F : -0.5F) * o.scale[u];
      off[v] = ((corner & 2) ? 0.5F : -0.5F) * o.scale[v];
      const V3 w = rotated({off[0], off[1], off[2]}, o.rotation);
      e.position[0] = o.position[0] + w.x;
      e.position[1] = o.position[1] + w.y;
      e.position[2] = o.position[2] + w.z;
      e.scale[u] = t;
      e.scale[v] = t;
      addBox(verts, cols, sts, e);
    }
  }
}

// Flat unit square in the XZ plane, double-sided (visible from both faces).
inline void addPlane(BagArray<Vec4>& verts, BagArray<Color>& cols,
              BagArray<Vec4>& sts, const SceneObjectData& o) {
  const float h = 0.5F;
  // The underside sits slightly below the top face: nothing here backface-culls
  // (the GS draws both), so two coplanar quads with different baked shades
  // would z-fight into a dithered mess. Offset in local units (scales with the
  // plane), invisible from either side. Twin: primmesh::unitPlane.
  const float b = -0.01F;
  g_aoRegion = 0;  // top face - atlas region 0
  pushQuad(verts, cols, sts, o, {-h, 0, -h}, {-h, 0, h}, {h, 0, h}, {h, 0, -h}, {0, 1, 0});
  g_aoRegion = 1;  // bottom face - atlas region 1
  pushQuad(verts, cols, sts, o, {-h, b, h}, {-h, b, -h}, {h, b, -h}, {h, b, h}, {0, -1, 0});
}

// Decal: a flat unit quad in the XY plane facing +Z, textured via the assigned
// material (transparency comes from the texture's alpha - the static pipeline
// runs an alpha test that drops fully-transparent texels and alpha-blends the
// rest). Nudged +Z by DECAL_OFFSET so it sits just in front of the surface it
// is placed on instead of z-fighting it. Single-sided (front only). U runs with
// local -X (slide-projector convention) so the texture reads correctly - not
// mirrored - viewed from the +Z front; matches unitDecal + the projected decal.
inline void addDecal(BagArray<Vec4>& verts, BagArray<Color>& cols,
              BagArray<Vec4>& sts, const SceneObjectData& o) {
  const float h = 0.5F, z = 0.02F;  // DECAL_OFFSET, local units (scaled by Z)
  const V3 n = {0, 0, 1};
  pushVert(verts, cols, sts, o, {-h, -h, z}, n, 1, 0);
  pushVert(verts, cols, sts, o, {h, -h, z}, n, 0, 0);
  pushVert(verts, cols, sts, o, {h, h, z}, n, 0, 1);
  pushVert(verts, cols, sts, o, {-h, -h, z}, n, 1, 0);
  pushVert(verts, cols, sts, o, {h, h, z}, n, 0, 1);
  pushVert(verts, cols, sts, o, {-h, h, z}, n, 1, 1);
}

inline void addCone(BagArray<Vec4>& verts, BagArray<Color>& cols,
             BagArray<Vec4>& sts, const SceneObjectData& o) {
  const int seg = o.primDetail < 3 ? 3 : (o.primDetail > 64 ? 64 : o.primDetail);
  const float r = 0.5F, h = 0.5F;
  const float nl = 0.894F, ny = 0.447F;  // side normal for r=0.5, h=1
  for (int i = 0; i < seg; ++i) {
    const float a0 = 2.0F * PI * i / seg, a1 = 2.0F * PI * (i + 1) / seg;
    const float am = (a0 + a1) * 0.5F;
    const float u0 = (float)i / seg, u1 = (float)(i + 1) / seg;
    const float x0 = r * cosf(a0), z0 = r * sinf(a0);
    const float x1 = r * cosf(a1), z1 = r * sinf(a1);
    // side - atlas region 0
    g_aoRegion = 0;
    pushVert(verts, cols, sts, o, {0, h, 0}, {nl * cosf(am), ny, nl * sinf(am)},
             (u0 + u1) * 0.5F, 0);
    pushVert(verts, cols, sts, o, {x1, -h, z1}, {nl * cosf(a1), ny, nl * sinf(a1)}, u1, 1);
    pushVert(verts, cols, sts, o, {x0, -h, z0}, {nl * cosf(a0), ny, nl * sinf(a0)}, u0, 1);
    // base (planar mapping) - atlas region 1
    g_aoRegion = 1;
    pushVert(verts, cols, sts, o, {0, -h, 0}, {0, -1, 0}, 0.5F, 0.5F);
    pushVert(verts, cols, sts, o, {x0, -h, z0}, {0, -1, 0}, x0 + 0.5F, z0 + 0.5F);
    pushVert(verts, cols, sts, o, {x1, -h, z1}, {0, -1, 0}, x1 + 0.5F, z1 + 0.5F);
  }
}

/** 8x8 glyph text from the res/hud/debugfont.png strip (digits, letters and
 * a few symbols - the atlas below must match the editor's debugFontPng()).
 * Shared by the debug-profile overlays and the video-mode confirm prompt,
 * so the strip ships with every build. */
inline void drawHudText(Engine* engine, const char* s, float x, float y) {
  static Sprite glyph;
  static bool glyphReady = false;
  if (!glyphReady) {
    glyph.mode = SpriteMode::MODE_REPEAT;
    glyph.size = Vec2(8.0F, 8.0F);  // one atlas cell
    glyph.scale = 2.0F;
    auto* texture = engine->renderer.getTextureRepository().add(
        FileUtils::fromCwd("hud/debugfont.png"));
    texture->addLink(glyph.id);
    glyphReady = true;
  }
  // 32 cells of 16px per atlas row (the glyph sits in the left 8px, the
  // right 8px stay transparent so bilinear sampling never bleeds the next
  // glyph), rows 8px apart.
  static const char* atlas = "0123456789.FPSMBE/ACDGHIJKLNOQRTUVWXYZ?=-:";
  for (; *s; ++s, x += 14.0F) {
    if (*s == ' ') continue;
    const char* hit = strchr(atlas, *s);
    if (!hit) continue;
    const int idx = (int)(hit - atlas);
    glyph.offset = Vec2((float)(idx % 32) * 16.0F, (float)(idx / 32) * 8.0F);
    glyph.position = Vec2(x, y);
    engine->renderer.renderer2D.render(glyph);
  }
}

inline float hudTextWidth(const char* s) { return (float)strlen(s) * 14.0F; }

/** Runtime text drawn from a Font Manager glyph atlas (Display Text nodes).
 *
 * Fonts load on demand, except a driveable vehicle's HUD font: scene loading
 * prepares its EE copy and first VRAM upload before the player can enter.
 * Prewarming uses normal evictable residency, not a pinned allocation. */
/** Inline text icons: `{{name}}` / `{{action:jump}}` in a runtime string
 * (docs/text-icons.md). Baked text has its icons composited into the sprite at
 * build time; here the string is only known now, so the token is resolved per
 * frame and blitted from the shared icon sheet.
 *
 * Returns the icon index (-1 = not a token / unknown, draw it as literal text)
 * and, on success, how many bytes of `s` the token spans. */
inline int resolveIconToken(const char* s, int* tokenLen) {
  if (ICON_COUNT <= 0 || s[0] != '{' || s[1] != '{') return -1;
  const char* end = strstr(s + 2, "}}");
  if (!end) return -1;
  const int inner = (int)(end - (s + 2));
  if (inner <= 0 || inner > 40) return -1;
  char name[41];
  memcpy(name, s + 2, (size_t)inner);
  name[inner] = 0;
  *tokenLen = inner + 4;

  // {{action:x}}: the icon of whatever x is bound to RIGHT NOW - a preset
  // switch or the player's own rebind moves the glyph with it.
  const char* action = nullptr;
  if (strncmp(name, "action:", 7) == 0) {
    action = name + 7;
  } else {
    // Icon names win; a token that is none gets one more chance as an action
    // name ({{use}} is the shorthand for {{action:use}}).
    for (int i = 0; i < ICON_COUNT; ++i)
      if (strcmp(ICONS[i].name, name) == 0) return i;
    action = name;
  }
  for (int a = 0; a < INPUT_ACTION_COUNT; ++a) {
    if (strcmp(INPUT_ACTION_NAMES[a], action) != 0) continue;
    const int pad = g_inputBind[a].pad;
    return (pad >= 0 && pad < 16) ? ICON_FOR_PAD[pad] : -1;
  }
  return -1;
}

// Drawn box + gap of an icon inside text of `size` (mirrors iconAdvance in
// menubake.cpp - the baked twin; change one, change both).
inline float iconAdvanceFor(int icon, float size) {
  return size * ICONS[icon].scale + size * 0.12F;
}

/** The one sprite every icon blit goes through. Shared on purpose: two sprites
 * with their own Texture for the same file would put the sheet in GS VRAM
 * twice. Handed to the repository on first use, so a project that draws no icon
 * never pays for it. */
inline Sprite* iconSheetSprite(Engine* engine) {
  if (ICON_COUNT <= 0) return nullptr;
  static Sprite sheet;
  static bool ready = false;
  if (!ready) {
    sheet.mode = SpriteMode::MODE_REPEAT;  // sample a sub-rect
    auto* tex = engine->renderer.getTextureRepository().add(
        FileUtils::fromCwd(ICON_SHEET));
    tex->addLink(sheet.id);
    ready = true;
  }
  return &sheet;
}

/** Blits icon `i` into a pixel box, untinted. The interaction prompts use this:
 * their text is a baked sprite with a HOLE where the button goes, and the glyph
 * is drawn here from the LIVE binding - so a rebind at runtime is reflected
 * (docs/text-icons.md). */
inline void drawIconAt(Engine* engine, int i, float x, float y, float box) {
  if (i < 0 || i >= ICON_COUNT || box <= 0.0F) return;
  Sprite* sp = iconSheetSprite(engine);
  if (!sp) return;
  const IconRect& ir = ICONS[i];
  if (ir.h <= 0) return;
  sp->color = Color(128.0F, 128.0F, 128.0F, 128.0F);  // neutral modulate
  sp->size = Vec2((float)ir.w, (float)ir.h);
  sp->offset = Vec2((float)ir.u, (float)ir.v);
  sp->scale = box / (float)ir.h;
  // The icon sheet is ONE shared sprite (iconSheetSprite) and drawFontText
  // gives it a per-axis drawSize for squeezed text - clear it, or a widescreen
  // menu leaves every later icon drawn at that width.
  sp->drawSize = Vec2(0.0F, 0.0F);
  sp->position = Vec2(x, y);
  engine->renderer.renderer2D.render(*sp);
}

/** The icon an action is bound to right now, or -1. */
inline int liveIconForAction(int action) {
  if (action < 0 || action >= INPUT_ACTION_COUNT) return -1;
  const int pad = g_inputBind[action].pad;
  return (pad >= 0 && pad < 16) ? ICON_FOR_PAD[pad] : -1;
}

/** Width of a string in framebuffer pixels. `sx` squeezes the horizontal axis
 * (1 = square glyphs): a menu panel compensated for anamorphic widescreen is
 * narrower than the buffer says, and text measured without the same factor
 * would be laid out for a panel that is not there. */
inline float fontTextWidth(int fontIdx, const char* s, float size, float sx = 1.0F) {
  const FontData& f = FONTS[fontIdx];
  if (!f.glyphs) return 0.0F;
  const float k = (size / (float)f.baseSize) * sx;
  float w = 0.0F;
  while (*s) {
    int tokenLen = 0;
    const int icon = resolveIconToken(s, &tokenLen);
    if (icon >= 0) {
      w += iconAdvanceFor(icon, size) * sx;
      s += tokenLen;
      continue;
    }
    const int gi = (int)(unsigned char)*s - FONT_FIRST_CHAR;
    ++s;
    if (gi < 0 || gi >= FONT_CHAR_COUNT) continue;
    w += (float)f.glyphs[gi].adv * k;
  }
  return w;
}

// Shared by normal drawing and loading-time vehicle HUD preparation. Reuse
// the same sprite/link across scene revisits; never load a second atlas copy.
inline Sprite* fontGlyphSprite(Engine* engine, int fontIdx) {
  if (fontIdx < 0 || fontIdx >= FONT_COUNT) return nullptr;
  const FontData& f = FONTS[fontIdx];
  if (!f.glyphs || !f.atlas[0]) return nullptr;

  // One sprite per font, kept across frames: the texture link is by sprite id,
  // so every glyph of a font reuses the same id and the same atlas binding.
  static Sprite glyph[FONT_COUNT > 0 ? FONT_COUNT : 1];
  static bool ready[FONT_COUNT > 0 ? FONT_COUNT : 1] = {};
  if (!ready[fontIdx]) {
    glyph[fontIdx].mode = SpriteMode::MODE_REPEAT;  // sample a sub-rect
    auto* texture = engine->renderer.getTextureRepository().add(
        FileUtils::fromCwd(f.atlas));
    texture->addLink(glyph[fontIdx].id);
    ready[fontIdx] = true;
  }

  return &glyph[fontIdx];
}

/** Draws a string centred on (cx, cy). `sx` squeezes the horizontal axis the
 * same way fontTextWidth measures it - 1 everywhere except inside a menu panel
 * compensated for anamorphic widescreen, where the glyphs have to be squeezed
 * with the panel or they come out fatter than the baked rows around them. */
inline void drawFontText(Engine* engine, int fontIdx, const char* s, float cx,
                  float cy, float size, float sx = 1.0F) {
  Sprite* glyph = fontGlyphSprite(engine, fontIdx);
  if (!glyph) return;
  const FontData& f = FONTS[fontIdx];
  Sprite& sp = *glyph;
  const float k = size / (float)f.baseSize;
  const float kx = k * sx;  // the same factor with the horizontal squeeze in
  sp.scale = k;

  // Center anchor, like the baked HUD text sprites.
  const float startX = cx - fontTextWidth(fontIdx, s, size, sx) * 0.5F;
  const float top = cy - (float)f.lineH * k * 0.5F;

  // Load the shared icon sheet only when a resolved icon is actually drawn.
  // Plain speed/gear/NOS strings must not read an unrelated asset on entry.
  Sprite* iconSp = nullptr;

  // Shadow first, then the glyphs: two passes over the same cells, the dark
  // one offset by a pixel (the baked texts get theirs at bake time instead).
  for (int pass = f.shadow ? 0 : 1; pass < 2; ++pass) {
    const float ox = pass == 0 ? 1.0F : 0.0F;
    if (pass == 0)
      sp.color = Color(10.0F, 12.0F, 16.0F, 100.0F);
    else
      sp.color = Color((float)f.r, (float)f.g, (float)f.b, 128.0F);
    // Icons carry their own colors (the DualShock palette for the face
    // buttons), so they draw untinted - and only on the glyph pass: a dark
    // offset copy under a colored icon just leaks a fringe around it.

    float pen = startX;
    const char* c = s;
    while (*c) {
      int tokenLen = 0;
      const int icon = resolveIconToken(c, &tokenLen);
      if (icon >= 0) {
        // The box is the icon's HEIGHT, so it never takes the squeeze; only
        // the advance and the drawn width do.
        const float box = iconAdvanceFor(icon, size) - size * 0.12F;
        const float adv = iconAdvanceFor(icon, size) * sx;
        const IconRect& ir = ICONS[icon];
        if (ir.h > 0 && pass == 1 && !iconSp)
          iconSp = iconSheetSprite(engine);
        if (ir.h > 0 && pass == 1 && iconSp) {
          iconSp->color = Color(128.0F, 128.0F, 128.0F, 128.0F);
          iconSp->size = Vec2((float)ir.w, (float)ir.h);
          iconSp->offset = Vec2((float)ir.u, (float)ir.v);
          iconSp->scale = box / (float)ir.h;
          iconSp->drawSize =
              Vec2((float)ir.w * (box / (float)ir.h) * sx, box);
          // Sit on the line box like a capital does, not on the baseline.
          iconSp->position =
              Vec2(pen + size * 0.06F * sx + ox,
                   top + ((float)f.lineH * k - box) * 0.5F + ox);
          engine->renderer.renderer2D.render(*iconSp);
        }
        pen += adv;
        c += tokenLen;
        continue;
      }
      const int gi = (int)(unsigned char)*c - FONT_FIRST_CHAR;
      ++c;
      if (gi < 0 || gi >= FONT_CHAR_COUNT) continue;
      const FontGlyph& g = f.glyphs[gi];
      if (g.w > 0 && g.h > 0) {
        sp.size = Vec2((float)g.w, (float)g.h);
        sp.offset = Vec2((float)g.u, (float)g.v);
        sp.drawSize = Vec2((float)g.w * kx, (float)g.h * k);
        sp.position = Vec2(pen + (float)g.xoff * kx + ox,
                           top + (float)g.yoff * k + ox);
        engine->renderer.renderer2D.render(sp);
      }
      pen += (float)g.adv * kx;
    }
  }
}

// Debug frame profiler (Project > Preferences > Build > Show frame profiler).
// renderScene brackets its three heavy phases with EE COP0-timer reads and
// adds the elapsed ticks here; drawDebugHud averages them over ~1s and prints
// avg ms. The reads live behind `if (DEBUG_SHOW_PROFILER)` (a constexpr), so a
// build with the profiler off contains none of this. This is the same
// COP0/HUD phase-timing harness used to diagnose the usable-highlight cost,
// wired in as a shippable debug option. (COP0 Count runs at 294.912 MHz =
// half the 590 MHz EE clock; /294912 converts ticks to milliseconds.)
inline u32 g_profScene = 0, g_profHighlight = 0, g_profParticles = 0;
inline u32 profTicks() {
  u32 v;
  asm volatile("mfc0 %0, $9" : "=r"(v));
  return v;
}

#if TYRA_FRAME_PROFILE
// ---------------------------------------------------------------------------
// The FRAMETIME line: the frame-timing rig's output half (the counters live in
// the engine, inc/debug/frame_profile.hpp; the protocol is docs/profiling.md).
//
// ONCE A SECOND, never once a frame. TyraDebug::writeInLogFile does a full
// ofstream open + append + flush PER LINE (vendor/tyra/engine/src/debug/
// debug.cpp), over host: on real hardware - a per-frame line would be
// measuring the logger. One snprintf, one TYRA_LOG, the same 1 Hz cadence
// RendererCoreBlss::logFeatureSpread already uses.
//
// The whole block charges its own cost to FrameProfile::tExcluded, which
// endFrame() subtracts from tFrameWork - otherwise one frame in fifty is a
// 20 ms outlier made entirely of measurement apparatus.
// ---------------------------------------------------------------------------
namespace ftrig {

inline constexpr int kWindow = 50;    // frames per FRAMETIME line
inline constexpr int kRaw = 512;      // buffered per-frame samples (paired stats)
inline constexpr float kTicksPerMs = 294912.0F;
inline constexpr u32 kBudget20ms = 5898240U;  // 20 ms of COP0 Count = the PAL budget

inline u32 work[kWindow], drain[kWindow];
// The update half of `pre`, lap by lap (FTUPD): the FPP loop's UPD_LAP marks,
// summed over the window. Bare COUNT reads, so level 2 stays transparent.
inline u64 updLap[10] = {};
inline u64 physOnly = 0; inline u32 physAwake = 0;
// Per-vehicle update, stage by stage (FTVEH), summed over every vehicle.
inline u64 vehLap[7] = {};
// The occlusion buffer, lap by lap (FTOCC): clear, corner projection + hull,
// span raster, erosion, and the per-candidate tests; plus call counts.
inline u64 occLap[7] = {};
inline u32 occBuilds = 0, occTests = 0, occRecomputes = 0, occBoxes = 0;
// The rest of the frame (FrameProfile::tPre / tStall / tPeriod).
inline u32 pre[kWindow], stall[kWindow], period[kWindow];
inline u64 sBeg = 0, sEnd = 0, sCmp = 0, sCmpEe = 0;
// The split of the two big EE terms. The first hardware A/B read the
// composite's EE half off ONE counter and got "~3.9 ms of scene submission"
// by SUBTRACTION, which is not a measurement; these make both attributable.
inline u64 sPrx = 0, sAcc = 0, sRep = 0, sFea = 0, sNet = 0, sPkt = 0;
inline int n = 0;
inline u32 frame = 0;  // frames since boot - the alignment key between runs A and B
inline u32 raw[kRaw];
inline int rawN = 0;
inline u32 rawFirst = 0;
// One-frame delay line. drawDebugHud runs BEFORE endFrame, so the BLSS
// counters it can see are THIS frame's while tFrameWork/tDrain are still last
// frame's. Holding the BLSS values back by one frame makes every record
// coherent instead of skewed.
inline u32 pBeg = 0, pEnd = 0, pCmp = 0, pCmpEe = 0;
inline u32 pPrx = 0, pAcc = 0, pRep = 0, pFea = 0, pNet = 0, pPkt = 0;
inline bool pValid = false;

// The static pipeline's routing counters (docs/vu1-clipping.md). Set at init
// so tick() can drain them without threading a pipeline pointer through
// drawDebugHud. StaPipTelemetry is opt-in and costs COP0 reads, so it is
// enabled only inside this #if - a normal debug build still carries none.
inline Tyra::StaPipCore* core = nullptr;
inline u32 tCull = 0, tClip = 0, tGuard = 0, tOut = 0;
inline u32 tTriCull = 0, tTriClip = 0, tTriGuard = 0;
inline u32 tFlush = 0, tVuWait = 0;
// Triangle-strip routing (docs/model-pipeline.md, "Triangle strips").
// `strip` counts the cull-routed packages submitted AS a strip, `sexp` the
// stripped packages the clipper forced back into a triangle list, and `verts`
// every vertex handed to a VU1 buffer. That last one is the number the EE's
// per-package bill scales with - quote it, not the triangle count, when
// comparing two builds of one view.
inline u32 tStrip = 0, tStripExp = 0;
inline u64 tVerts = 0;
#if TYRA_STAPIP_PACKET_PROFILE
inline Tyra::StaPipPacketCounters tPacket[Tyra::StaPipProducerCount];

inline void addPacketCounters(Tyra::StaPipPacketCounters& dst,
                       const Tyra::StaPipPacketCounters& src) {
  for (int i = 0; i < 8; ++i) dst.dmaTags[i] += src.dmaTags[i];
  dst.chainQwords += src.chainQwords;
  dst.refPayloadQwords += src.refPayloadQwords;
  dst.inlinePayloadQwords += src.inlinePayloadQwords;
  dst.refsAligned128 += src.refsAligned128;
  dst.refsUnaligned128 += src.refsUnaligned128;
  dst.vifWords += src.vifWords;
  dst.vifNops += src.vifNops;
  dst.vifStcycl += src.vifStcycl;
  dst.vifStrow += src.vifStrow;
  dst.vifStcol += src.vifStcol;
  dst.vifUnpack += src.vifUnpack;
  dst.vifFlush += src.vifFlush;
  dst.vifFlushe += src.vifFlushe;
  dst.vifFlusha += src.vifFlusha;
  dst.vifMscal += src.vifMscal;
  dst.vifMscalf += src.vifMscalf;
  dst.vifMscnt += src.vifMscnt;
  dst.gifTags += src.gifTags;
  dst.adWrites += src.adWrites;
  dst.gsPayloadQwords += src.gsPayloadQwords;
  dst.xgkicks += src.xgkicks;
  dst.gsStateReuses += src.gsStateReuses;
  dst.malformedChains += src.malformedChains;
}
#endif

// u64, because a u32 SUM OVERFLOWS. 50 frames x 300 ms is 4.4e9 ticks against
// a 4.29e9 ceiling, so on a scene slow enough to be worth profiling the mean
// wrapped and printed BELOW the median - which is how a 500 ms frame first
// reported itself as 37 ms. Per-frame values (median, p95) were always fine;
// only the accumulators were wrong.
inline float ms(u64 ticks, int count) {
  return (float)ticks / (kTicksPerMs * (float)count);
}

inline void sortU32(u32* a, int cnt) {
  for (int i = 1; i < cnt; i++) {
    const u32 v = a[i];
    int j = i - 1;
    while (j >= 0 && a[j] > v) {
      a[j + 1] = a[j];
      j--;
    }
    a[j + 1] = v;
  }
}

// Dumps the buffered per-frame work ticks so runs A and B can be compared as
// PAIRED samples (frame k of A against frame k of B - the fixture's camera is
// frame-indexed, so those are the same view). Same I/O cost as one summary
// line, 512x the data; 64 values a line keeps each line under 600 bytes.
inline void dumpRaw() {
  char line[600];
  for (int base = 0; base < rawN; base += 64) {
    int at = snprintf(line, sizeof(line), "FTRAW %lu",
                      (unsigned long)(rawFirst + (u32)base));
    const int end = base + 64 < rawN ? base + 64 : rawN;
    for (int i = base; i < end; i++)
      at += snprintf(line + at, sizeof(line) - at, " %lx",
                     (unsigned long)raw[i]);
    TYRA_LOG(line);
  }
  rawN = 0;
}

inline void tick(const Vec4& camPos, const Vec4& camAt) {
  namespace FP = Tyra::FrameProfile;
  const int i = n;
  work[i] = FP::tFrameWork;
  drain[i] = FP::tDrain;
  pre[i] = FP::tPre;
  stall[i] = FP::tStall;
  period[i] = FP::tPeriod;
  if (pValid) {
    sBeg += pBeg;
    sEnd += pEnd;
    sCmp += pCmp;
    sCmpEe += pCmpEe;
    sPrx += pPrx;
    sAcc += pAcc;
    sRep += pRep;
    sFea += pFea;
    sNet += pNet;
    sPkt += pPkt;
  }
  pBeg = FP::tBlssBegin;
  pEnd = FP::tBlssEnd;
  pCmp = FP::tBlssComposite;
  pCmpEe = FP::tBlssCompositeEe;
  pPrx = FP::tBlssProxy;
  pAcc = FP::tBlssAccum;
  pRep = FP::tBlssReproj;
  pFea = FP::tBlssFeat;
  pNet = FP::tBlssNet;
  pPkt = FP::tBlssPacket;
  pValid = true;
  // Drained EVERY frame, not once a window: takeTelemetry() clears as it
  // reads, so skipping frames would silently drop their packages.
  if (core != nullptr) {
    const Tyra::StaPipTelemetry t = core->takeTelemetry();
    tCull += t.packagesCull;
    tClip += t.packagesClip;
    tGuard += t.packagesGuardBand;
    tOut += t.packagesOutside;
    tTriCull += t.trianglesCull;
    tTriClip += t.trianglesClip;
    tTriGuard += t.trianglesGuardBand;
    tFlush += t.packetFlushes;
    tVuWait += t.vu1WaitTicks;
    tStrip += t.packagesStrip;
    tStripExp += t.packagesStripExpanded;
    tVerts += t.verticesSubmitted;
#if TYRA_STAPIP_PACKET_PROFILE
    for (int p = 0; p < Tyra::StaPipProducerCount; ++p)
      addPacketCounters(tPacket[p], t.packet[p]);
#endif
  }
  if (rawN < kRaw) raw[rawN++] = FP::tFrameWork;
  if (rawN == 1) rawFirst = frame;
  frame++;
  if (++n < kWindow) return;
  n = 0;

  u32 sorted[kWindow];
  u64 sumW = 0, sumD = 0, sumPre = 0, sumStall = 0, sumPer = 0;
  int over = 0, miss = 0;
  for (int k = 0; k < kWindow; k++) {
    sorted[k] = work[k];
    sumW += work[k];
    sumD += drain[k];
    sumPre += pre[k];
    sumStall += stall[k];
    sumPer += period[k];
    if (work[k] > kBudget20ms) over++;
    // A MISSED field: the frame took two (or more). Judged at 25 ms rather
    // than 20 so a frame that made its field with some flip jitter still
    // counts as made - the periods are quantised to 20/40/60, not continuous.
    if (period[k] > kBudget20ms + kBudget20ms / 4) miss++;
  }
  sortU32(sorted, kWindow);

  // Heading, not orbit angle: it is defined for any fixture camera, and it is
  // the independent confirmation that frame f of run A really was looking
  // where frame f of run B was. `f` is the exact key; `cam` is the check.
  const float cam = atan2f(camAt.x - camPos.x, camAt.z - camPos.z);
  const float mean = ms(sumW, kWindow);
  const float dr = ms(sumD, kWindow);

  char line[512];
  snprintf(line, sizeof(line),
           "FRAMETIME n=%d f=%lu work=%.2f/%.2f/%.2f submit=%.2f drain=%.2f "
           "blss=%.2f/%.2f/%.2f comp=%.2f/%.2f over20=%d cam=%.4f "
           "pre=%.2f stall=%.2f period=%.2f miss=%d",
           kWindow, (unsigned long)(frame - kWindow), (double)mean,
           (double)ms(sorted[kWindow / 2], 1),
           (double)ms(sorted[(kWindow * 95) / 100], 1), (double)(mean - dr),
           (double)dr, (double)ms(sBeg, kWindow), (double)ms(sEnd, kWindow),
           (double)ms(sCmp, kWindow), (double)ms(sCmpEe, kWindow),
           (double)ms(sCmp - sCmpEe, kWindow), over, (double)cam,
           (double)ms(sumPre, kWindow), (double)ms(sumStall, kWindow),
           (double)ms(sumPer, kWindow), miss);
  TYRA_LOG(line);
  snprintf(line, sizeof(line), "FTUPD f=%lu in=%.3f player=%.3f scripts=%.3f stream=%.3f phys=%.3f veh=%.3f portal=%.3f part=%.3f sound=%.3f rest=%.3f",
           (unsigned long)(frame - kWindow), (double)ms(updLap[0], kWindow), (double)ms(updLap[1], kWindow), (double)ms(updLap[2], kWindow), (double)ms(updLap[3], kWindow), (double)ms(updLap[4], kWindow), (double)ms(updLap[5], kWindow), (double)ms(updLap[6], kWindow), (double)ms(updLap[7], kWindow), (double)ms(updLap[8], kWindow), (double)ms(updLap[9], kWindow));
  TYRA_LOG(line);
  for (int k = 0; k < 10; ++k) updLap[k] = 0;
  snprintf(line, sizeof(line), "FTPHYS f=%lu physics=%.3f awake=%.2f",
           (unsigned long)(frame - kWindow), (double)ms(physOnly, kWindow),
           (double)physAwake / kWindow);
  TYRA_LOG(line);
  physOnly = 0; physAwake = 0;
  snprintf(line, sizeof(line),
           "FTVEH f=%lu input=%.3f gather=%.3f rig=%.3f walls=%.3f bodies=%.3f "
           "smoke=%.3f sound=%.3f",
           (unsigned long)(frame - kWindow), (double)ms(vehLap[0], kWindow),
           (double)ms(vehLap[1], kWindow), (double)ms(vehLap[2], kWindow),
           (double)ms(vehLap[3], kWindow), (double)ms(vehLap[4], kWindow),
           (double)ms(vehLap[5], kWindow), (double)ms(vehLap[6], kWindow));
  TYRA_LOG(line);
  for (int k = 0; k < 7; ++k) vehLap[k] = 0;
  snprintf(line, sizeof(line),
           "FTOCC f=%lu clear=%.3f hull=%.3f raster=%.3f erode=%.3f test=%.3f "
           "builds=%.1f tests=%.1f recompute=%.1f boxes=%.1f proj=%.3f objfrustum=%.3f",
           (unsigned long)(frame - kWindow), (double)ms(occLap[0], kWindow),
           (double)ms(occLap[1], kWindow), (double)ms(occLap[2], kWindow),
           (double)ms(occLap[3], kWindow), (double)ms(occLap[4], kWindow),
           (double)occBuilds / kWindow, (double)occTests / kWindow,
           (double)occRecomputes / kWindow, (double)occBoxes / kWindow,
           (double)ms(occLap[5], kWindow), (double)ms(occLap[6], kWindow));
  TYRA_LOG(line);
  for (int k = 0; k < 7; ++k) occLap[k] = 0;
  occBuilds = occTests = occRecomputes = occBoxes = 0;
  // The attribution line. `proxy` is charged inside StaPipCore (scene
  // SUBMISSION, not the composite); the other four split the composite's EE
  // half at its four phases, so reproj+feat+net+pkt reconstructs comp's EE
  // figure above to within the counters' own overhead.
  //
  // `proxy=total/accum` splits the proxy feed itself: `accum` is
  // RendererCoreBlss::addBag, the read-modify-write per (proxy, TILE), and
  // `total - accum` is the projection half - eight corners through the MVP,
  // the near clip, the bbox reduce, once per VU1 package. They are the two
  // halves the same millisecond can be taken off in completely different ways,
  // and this feature has already paid once for splitting a term by
  // subtraction instead of measuring it.
  // THREE decimals, not two, and the reason is that this line has outlived the
  // sizes it was written for. When it was added the terms it splits ran 2-4 ms
  // and 0.01 was noise; the cuts since have taken reproj to 0.28 and feat to
  // 0.19, where a real 0.05 ms saving is five units of the last digit and a
  // 0.02 one is two. A term measured to 0.01 ms cannot resolve a cut worth
  // 0.03, and rounding is not something more paired windows can average away.
  snprintf(line, sizeof(line),
           "FTSPLIT f=%lu proxy=%.3f/%.3f reproj=%.3f feat=%.3f net=%.3f "
           "pkt=%.3f",
           (unsigned long)(frame - kWindow), (double)ms(sPrx, kWindow),
           (double)ms(sAcc, kWindow),
           (double)ms(sRep, kWindow), (double)ms(sFea, kWindow),
           (double)ms(sNet, kWindow), (double)ms(sPkt, kWindow));
  TYRA_LOG(line);
  // The clipper routing line (docs/vu1-clipping.md). Packages and triangles
  // per route over the window, plus the GUARD subset of cull - the packages
  // that leave the screen but stay inside the guard band, which used to be
  // clipped and are now culled whole. `clip` going down while `guard` goes up
  // by the same amount is what a guard-band routing change looks like; the
  // two totals must stay equal between two arms of an A/B, or the arms are
  // not looking at the same scene. Counts, not milliseconds - `work` above is
  // the milliseconds, and this line says WHY it moved.
  if (core != nullptr) {
    snprintf(line, sizeof(line),
             "FTCLIP f=%lu cull=%lu/%lu clip=%lu/%lu guard=%lu/%lu out=%lu "
             "flush=%lu strip=%lu sexp=%lu verts=%lu vuwait=%.2f",
             (unsigned long)(frame - kWindow), (unsigned long)tCull,
             (unsigned long)tTriCull, (unsigned long)tClip,
             (unsigned long)tTriClip, (unsigned long)tGuard,
             (unsigned long)tTriGuard, (unsigned long)tOut,
             (unsigned long)tFlush, (unsigned long)tStrip,
             (unsigned long)tStripExp,
             (unsigned long)(tVerts / (u64)kWindow),
             (double)ms(tVuWait, kWindow));
    TYRA_LOG(line);
    tCull = tClip = tGuard = tOut = 0;
    tTriCull = tTriClip = tTriGuard = 0;
    tFlush = tVuWait = 0;
    tStrip = tStripExp = 0;
    tVerts = 0;
#if TYRA_STAPIP_PACKET_PROFILE
    static const char* const producerNames[Tyra::StaPipProducerCount] = {
        "mixed", "sky", "terrain", "static", "roads", "procedural",
        "objects", "effects"};
    for (int p = 0; p < Tyra::StaPipProducerCount; ++p) {
      Tyra::StaPipPacketCounters& q = tPacket[p];
      if (q.chainQwords == 0 && q.xgkicks == 0) continue;
      const u32 refs = q.dmaTags[0] + q.dmaTags[3] + q.dmaTags[4];
      snprintf(
          line, sizeof(line),
          "FTPKT f=%lu p=%s kick=%lu gif=%lu ad=%lu gqw=%lu reuse=%lu tag=%lu "
          "ref=%lu cnt=%lu end=%lu rq=%lu iq=%lu a128=%lu/%lu "
          "vifw=%lu nop=%lu unpack=%lu cyc=%lu row=%lu col=%lu "
          "flush=%lu/%lu/%lu msc=%lu/%lu/%lu bad=%lu",
          (unsigned long)(frame - kWindow), producerNames[p],
          (unsigned long)q.xgkicks, (unsigned long)q.gifTags,
          (unsigned long)q.adWrites, (unsigned long)q.gsPayloadQwords,
          (unsigned long)q.gsStateReuses,
          (unsigned long)(q.dmaTags[0] + q.dmaTags[1] + q.dmaTags[2] +
                          q.dmaTags[3] + q.dmaTags[4] + q.dmaTags[5] +
                          q.dmaTags[6] + q.dmaTags[7]),
          (unsigned long)refs, (unsigned long)q.dmaTags[1],
          (unsigned long)q.dmaTags[7], (unsigned long)q.refPayloadQwords,
          (unsigned long)q.inlinePayloadQwords,
          (unsigned long)q.refsAligned128,
          (unsigned long)q.refsUnaligned128, (unsigned long)q.vifWords,
          (unsigned long)q.vifNops, (unsigned long)q.vifUnpack,
          (unsigned long)q.vifStcycl, (unsigned long)q.vifStrow,
          (unsigned long)q.vifStcol, (unsigned long)q.vifFlush,
          (unsigned long)q.vifFlushe, (unsigned long)q.vifFlusha,
          (unsigned long)q.vifMscal, (unsigned long)q.vifMscalf,
          (unsigned long)q.vifMscnt, (unsigned long)q.malformedChains);
      TYRA_LOG(line);
      q = Tyra::StaPipPacketCounters{};
    }
#endif
  }
  sBeg = sEnd = sCmp = sCmpEe = 0;
  sPrx = sAcc = sRep = sFea = sNet = sPkt = 0;
  if (rawN >= kRaw) dumpRaw();
}

#if TYRA_FRAME_PROFILE_CALIB
// The calibration gate. K full-screen textured alpha-blended sprites a frame,
// each with its own draw_finish + wait; the slope of the sweep is what one
// full-screen GS pass costs on THIS machine. PCSX2 runs a software rasteriser
// and is not fill-rate accurate, and BLSS trades GS fill for GS fill - a slope
// near zero means no emulator number about this feature's GS cost is
// admissible. Real hardware should read ~0.2-0.4 ms per pass at 512x448.
inline constexpr int kCalibK[5] = {0, 2, 4, 8, 16};
inline u32 calSum[5] = {0, 0, 0, 0, 0};
inline int calN[5] = {0, 0, 0, 0, 0};
inline int calFrame = 0;
// THE RESOLUTION THE SWEEP RAN AT. The probe sizes its sprite from the current
// framebuffer, so `slope` is ms per full-screen pass AT THIS RASTER and means
// nothing without it - the 0.5872 this rig published was measured on a PAL 576i
// fixture (512x512) and then read against 512x448 coverages for a year, which
// is 14.3 % more pixels than the constant describes. Printed on the line, next
// to a per-megapixel figure that does not depend on the mode at all.
inline int calW = 0, calH = 0;

inline void calibrate(Engine* engine) {
  const int slot = (calFrame / 10) % 5;  // 10 frames per K, then rotate
  calFrame++;
  auto& core = engine->renderer.core;
  const u32 t = Tyra::FrameProfile::gsFillProbe(&core.gs, &core.sync,
                                                core.getPath1(),
                                                kCalibK[slot], &calW, &calH);
  calSum[slot] += t;
  calN[slot]++;
  if (calFrame % 250) return;
  char line[200];
  int at = snprintf(line, sizeof(line), "GSFILL");
  for (int i = 0; i < 5; i++)
    at += snprintf(line + at, sizeof(line) - at, " k%d=%.3f", kCalibK[i],
                   calN[i] ? (double)ms(calSum[i], calN[i]) : 0.0);
  // Least-squares slope of ms against K, i.e. ms per full-screen pass.
  float sx = 0.0F, sy = 0.0F, sxx = 0.0F, sxy = 0.0F;
  for (int i = 0; i < 5; i++) {
    const float x = (float)kCalibK[i];
    const float y = calN[i] ? ms(calSum[i], calN[i]) : 0.0F;
    sx += x;
    sy += y;
    sxx += x * x;
    sxy += x * y;
  }
  const float den = 5.0F * sxx - sx * sx;
  const float slope = den != 0.0F ? (5.0F * sxy - sx * sy) / den : 0.0F;
  // raster= is what `slope` is per; perMpx= is the same measurement with the
  // mode divided out, so two consoles - or two display modes on one console -
  // can be compared without anybody having to remember which fixture booted in
  // which resolution.
  const float mpx = (float)calW * (float)calH * 1e-6F;
  snprintf(line + at, sizeof(line) - at, " raster=%dx%d slope=%.4f perMpx=%.4f",
           calW, calH, (double)slope, mpx > 0.0F ? (double)(slope / mpx) : 0.0);
  TYRA_LOG(line);
}
#endif  // TYRA_FRAME_PROFILE_CALIB

}  // namespace ftrig
#endif  // TYRA_FRAME_PROFILE

/** Debug-profile HUD (Project > Preferences > Build): FPS, RAM
 * (used/total EE MB) and the per-phase EE-time profiler in the top-left
 * corner. Compiles to nothing in a release build (the DEBUG_SHOW_* constants
 * in terrain_config.hpp fold the calls away). The camera is passed in for the
 * frame-timing rig's `cam` field - it is the only thing here that needs it,
 * and it is unused when TYRA_FRAME_PROFILE is 0. */
inline void drawDebugHud(Engine* engine, const Vec4& camPos, const Vec4& camAt) {
#if TYRA_FRAME_PROFILE
  {
    // Everything in here is apparatus, so it comes straight back out of
    // tFrameWork (see FrameProfile::tExcluded).
    const u32 fpE0 = Tyra::FrameProfile::ticks();
#if TYRA_FRAME_PROFILE_CALIB
    ftrig::calibrate(engine);
#endif
    ftrig::tick(camPos, camAt);
    Tyra::FrameProfile::tExcluded += Tyra::FrameProfile::ticks() - fpE0;
  }
#else
  (void)camPos;
  (void)camAt;
#endif
  if (!DEBUG_SHOW_FPS && !DEBUG_SHOW_MEM && !DEBUG_SHOW_PROFILER) return;
  static int memRefresh = 0;
  static float memFreeMB = 0.0F;
  char line[40];
  float y = 16.0F;
  if (DEBUG_SHOW_FPS) {
    // RENDERED frames per second, averaged over the engine's stated 0.5 s
    // window (Info::getFps - it reads COP0 Count, not the video mode's
    // scanline timer). Frame extrapolation presents a synthesised frame after
    // endFrame() returns, so the game then shows about twice the rate it
    // renders: SHOWN is that second number, and it appears only when the two
    // genuinely differ. docs/profiling.md, "The three frame rate counters".
    // The CAP is printed beside the rate because without it the same game
    // reads 25 in PAL 576i and 30-40 in 1080i and looks like a counting bug -
    // it is not. Those modes refresh at 50 and 60 Hz, and a frame that misses
    // its field halves to 25 or 30 respectively; getRefreshRate() is the
    // engine's own answer (DTV modes 60, Pal576i 50, the rest follow the video
    // mode). Reported as "coś tu chyba źle liczy".
    const float cap = engine->renderer.core.getSettings().getRefreshRate();
    if (engine->info.isPresentingExtraFrames())
      snprintf(line, sizeof(line), "FPS %.1f SHOWN %.1f/%.0f",
               (double)engine->info.getFps(),
               (double)engine->info.getPresentedFps(), (double)cap);
    else
      snprintf(line, sizeof(line), "FPS %.1f/%.0f",
               (double)engine->info.getFps(), (double)cap);
    drawHudText(engine, line, 16.0F, y);
    y += 20.0F;
  }
  if (DEBUG_SHOW_MEM) {
    // getAvailableRAM() reads the allocator's books (engine info.cpp) - it
    // used to malloc-probe the heap, a 30-75 ms hitch every time this ran.
    // The ~2 second refresh stays so the digits are readable. Shown as
    // used/total: the EE has 32 MB, so MEM 6.1/32 MB = 6.1 MB in use.
    if (memRefresh-- <= 0) {
      memFreeMB = engine->info.getAvailableRAM();
      memRefresh = everyFrames(2.0F);
    }
    snprintf(line, sizeof(line), "MEM %.1f/32 MB", 32.0F - memFreeMB);
    drawHudText(engine, line, 16.0F, y);
    y += 20.0F;
    // GS VRAM, beside it and deliberately so. MEM is the EE's 32 MB of main
    // memory and does NOT move when the display mode changes - the
    // framebuffers and the z buffer live in the GS' separate 4 MB, and that
    // is the pool a taller mode eats. Reported as "I change the display mode
    // and the memory reading never moves", which was the HUD answering a
    // question it was never asked. Free rather than used: the texture heap is
    // what a mode change takes from, and free space is what the next texture
    // upload actually has (docs/gs-vram.md) - but it is printed as USED over
    // the GS' 4 MB so it reads the same way round as MEM above it. Note the
    // HUD glyph atlas is digits, '.' and UPPERCASE only: a lowercase word
    // here silently draws nothing (the first cut of this line ended in
    // "free" and rendered as blank).
    snprintf(line, sizeof(line), "VRAM %.2f/4 MB",
             4.0F - (double)engine->renderer.core.gs.vram.getFreeSpaceInMB());
    drawHudText(engine, line, 16.0F, y);
    y += 20.0F;
  }
  if (DEBUG_SHOW_PROFILER) {
    // Whole-frame time = wall clock between successive HUD calls (this runs
    // once per frame); the phase sums come from renderScene. Averaged over a
    // ~1s window so the numbers hold still enough to read.
    static u32 lastTick = 0, frames = 0, frameAcc = 0;
    static u32 sScene = 0, sHl = 0, sPart = 0;
    static char l1[40] = "PROFILER...", l2[40] = "";
    const u32 now = profTicks();
    if (lastTick) frameAcc += now - lastTick;
    lastTick = now;
    sScene += g_profScene;
    sHl += g_profHighlight;
    sPart += g_profParticles;
    g_profScene = g_profHighlight = g_profParticles = 0;
    if (++frames >= 50) {
      const float k = 1.0F / (294912.0F * (float)frames);  // ticks -> avg ms
      snprintf(l1, sizeof(l1), "FRAME %.2f SCENE %.2f", frameAcc * k,
               sScene * k);
      snprintf(l2, sizeof(l2), "HL %.2f PART %.2f", sHl * k, sPart * k);
      frames = frameAcc = sScene = sHl = sPart = 0;
    }
    drawHudText(engine, l1, 16.0F, y);
    y += 20.0F;
    drawHudText(engine, l2, 16.0F, y);
  }
}

// Runtime scan-mode switch with keep-or-revert confirmation (the Set
// Display Mode flow node). A mode the player's TV can't display would
// strand them on a black screen, so with a confirm window armed the game
// automatically reverts to the previous mode unless X is pressed in time -
// the same safety net PC display settings use.
struct VideoConfirm {
  bool active = false;
  Tyra::DisplayMode prevMode = Tyra::DisplayMode::Interlaced;
  float secondsLeft = 0.0F;
};
inline VideoConfirm g_videoConfirm;

/** Applies the Set Display Mode / Set Widescreen flow-node requests and
 * ticks the confirm countdown. Must run between frames (before
 * beginFrame): a scan-mode switch rebuilds the VRAM layout. Returns true
 * the frame a scan-mode switch happens - the caller closes any open game
 * menu then, so the player judges the new picture unobstructed and the
 * confirm prompt's X press is not also a menu select. */
inline bool applyVideoRequests(Engine* engine, ScriptContext& ctx) {
  auto& core = engine->renderer.core;
  bool switched = false;
  if (ctx.widescreen >= 0) {
    core.setDisplayOutput(core.getSettings().getDisplayMode(),
                          ctx.widescreen != 0);
    ctx.widescreen = -1;
  }
  if (ctx.requestDisplayMode >= 0) {
    const auto mode = (Tyra::DisplayMode)ctx.requestDisplayMode;
    const auto prev = core.getSettings().getDisplayMode();
    if (mode != prev) {
      core.setDisplayOutput(mode, core.getSettings().getWidescreen());
      // The vertical refresh may change (PAL 50 <-> DTV 60) - reseed the
      // frame clock so gameplay speed stays wall-clock normalized.
      g_frameRate = engine->renderer.core.getSettings().getRefreshRate();
      switched = true;
      if (ctx.displayConfirmSec > 0.0F) {
        g_videoConfirm.active = true;
        g_videoConfirm.prevMode = prev;
        g_videoConfirm.secondsLeft = ctx.displayConfirmSec;
      } else {
        g_videoConfirm.active = false;  // blind switch - no prompt armed
      }
    }
    ctx.requestDisplayMode = -1;
    ctx.displayConfirmSec = 0.0F;
  }
  if (!g_videoConfirm.active) return switched;
  if (!switched && engine->pad.getClicked().Cross) {
    g_videoConfirm.active = false;  // player kept the new mode
    return switched;
  }
  g_videoConfirm.secondsLeft -= g_frameDt;
  if (g_videoConfirm.secondsLeft <= 0.0F) {
    core.setDisplayOutput(g_videoConfirm.prevMode,
                          core.getSettings().getWidescreen());
    g_frameRate = engine->renderer.core.getSettings().getRefreshRate();
    g_videoConfirm.active = false;
  }
  return switched;
}

/** The keep-or-revert prompt, drawn in the 2D phase (with the other HUD). */
inline void drawVideoConfirm(Engine* engine) {
  if (!g_videoConfirm.active) return;
  const float w = engine->renderer.core.getSettings().getWidth();
  const float h = engine->renderer.core.getSettings().getHeight();
  const char* ask = "KEEP VIDEO MODE? X = YES";
  drawHudText(engine, ask, (w - hudTextWidth(ask)) * 0.5F, h * 0.5F - 22.0F);
  char line[24];
  snprintf(line, sizeof(line), "BACK IN %d",
           (int)g_videoConfirm.secondsLeft + 1);
  drawHudText(engine, line, (w - hudTextWidth(line)) * 0.5F, h * 0.5F + 2.0F);
}

// --- Loading screens (loading_data.gen.hpp) --------------------------------
// Presents one frame of the loading screen a scene resolves to (background +
// images + baked texts + progress bars) at load progress `fraction` (0..1).
// Called from loadScene while it drains assets/terrain AND from the loop's
// scene-switch hold; the whole point of pumping frames mid-load is that the
// bar advances for real. Sprites and texture links are built once, lazily
// (loadScene(0) at boot can run before init() finishes its own sprite setup),
// then reused - the colored-rect quads share one white 8x8 sprite re-rendered
// per rectangle, exactly like sequences::renderOverlay's black quad.
struct LoadingScreenState {
  bool ready = false;
  bool builtinReady = false;
  Tyra::Sprite builtin;                // hud/loading.png fallback
  Tyra::Sprite white;                  // tinted into every bar quad
  std::vector<Tyra::Sprite> images;    // LS_IMAGE_TOTAL, one per LS_IMAGES
  std::vector<Tyra::Sprite> texts;     // LS_TEXT_TOTAL, one per LS_TEXTS
  std::vector<Tyra::Sprite> segs;      // LS_BAR_TOTAL, linked only for seg bars
  std::vector<Tyra::Sprite> splashes;  // SPLASH_COUNT, one per SPLASHES
};
inline LoadingScreenState g_loading;

inline void loadingEnsureReady(Engine* engine) {
  if (g_loading.ready) return;
  g_loading.ready = true;
  auto& repo = engine->renderer.getTextureRepository();
  g_loading.white.mode = SpriteMode::MODE_STRETCH;
  repo.add(FileUtils::fromCwd("hud/loading-white.png"))->addLink(g_loading.white.id);
  g_loading.images.resize(LS_IMAGE_TOTAL > 0 ? LS_IMAGE_TOTAL : 0);
  for (int i = 0; i < LS_IMAGE_TOTAL; ++i) {
    g_loading.images[i].mode = SpriteMode::MODE_STRETCH;
    repo.add(FileUtils::fromCwd(LS_IMAGES[i].path))->addLink(g_loading.images[i].id);
  }
  g_loading.texts.resize(LS_TEXT_TOTAL > 0 ? LS_TEXT_TOTAL : 0);
  for (int i = 0; i < LS_TEXT_TOTAL; ++i) {
    g_loading.texts[i].mode = SpriteMode::MODE_STRETCH;
    repo.add(FileUtils::fromCwd(LS_TEXTS[i].path))->addLink(g_loading.texts[i].id);
  }
  g_loading.segs.resize(LS_BAR_TOTAL > 0 ? LS_BAR_TOTAL : 0);
  for (int i = 0; i < LS_BAR_TOTAL; ++i) {
    if (LS_BARS[i].segPath[0] == '\0') continue;
    g_loading.segs[i].mode = SpriteMode::MODE_STRETCH;
    repo.add(FileUtils::fromCwd(LS_BARS[i].segPath))->addLink(g_loading.segs[i].id);
  }
  g_loading.splashes.resize(SPLASH_COUNT > 0 ? SPLASH_COUNT : 0);
  for (int i = 0; i < SPLASH_COUNT; ++i) {
    g_loading.splashes[i].mode = SpriteMode::MODE_STRETCH;
    repo.add(FileUtils::fromCwd(SPLASHES[i].path))->addLink(g_loading.splashes[i].id);
  }
}

namespace loadingscreen {
// One boot splash frame: the image (i) on its background color. Vsync-paced by
// the caller (the loop's boot sequence), held for SPLASHES[i].seconds.
inline void renderSplash(Engine* engine, int i) {
  if (i < 0 || i >= SPLASH_COUNT) return;
  loadingEnsureReady(engine);
  const SplashData& s = SPLASHES[i];
  const auto& scr = engine->renderer.core.getSettings();
  const float W = scr.getWidth(), H = scr.getHeight();
  engine->renderer.setClearScreenColor(Color(s.bg[0], s.bg[1], s.bg[2]));
  engine->renderer.beginFrame();
  Sprite& sp = g_loading.splashes[i];
  sp.size = Vec2(s.w, s.h);
  sp.position = Vec2(s.x * W - s.w * 0.5F, s.y * H - s.h * 0.5F);
  engine->renderer.renderer2D.render(sp);
  engine->renderer.endFrame();
}

inline void renderFrame(Engine* engine, int sceneIdx, float fraction) {
  if (fraction < 0.0F) fraction = 0.0F;
  if (fraction > 1.0F) fraction = 1.0F;

  int screen = -1;
  if (LS_COUNT > 0) {
    if (sceneIdx >= 0 && sceneIdx < SCENE_COUNT)
      screen = SCENE_LOADING_SCREEN[sceneIdx];
    else
      screen = LS_DEFAULT;
    if (screen < 0 || screen >= LS_COUNT) screen = LS_DEFAULT;
  }

  const auto& scr = engine->renderer.core.getSettings();
  const float W = scr.getWidth();
  const float H = scr.getHeight();

  // No authored screen resolves here: the classic built-in (hud/loading.png
  // centered on black), pixel-identical to the pre-editor loading screen.
  if (screen < 0 || screen >= LS_COUNT) {
    if (!g_loading.builtinReady) {
      g_loading.builtin.mode = SpriteMode::MODE_STRETCH;
      g_loading.builtin.size = Vec2(256.0F, 64.0F);
      g_loading.builtin.position = Vec2((W - 256.0F) * 0.5F, (H - 64.0F) * 0.5F);
      engine->renderer.getTextureRepository()
          .add(FileUtils::fromCwd("hud/loading.png"))
          ->addLink(g_loading.builtin.id);
      g_loading.builtinReady = true;
    }
    engine->renderer.setClearScreenColor(Color(0.0F, 0.0F, 0.0F));
    engine->renderer.beginFrame();
    engine->renderer.renderer2D.render(g_loading.builtin);
    engine->renderer.endFrame();
    return;
  }

  loadingEnsureReady(engine);
  const LoadingScreenData& s = LS_SCREENS[screen];
  engine->renderer.setClearScreenColor(Color(s.bg[0], s.bg[1], s.bg[2]));
  engine->renderer.beginFrame();

  // A tinted white quad (GS modulation, tint already in 0..128 range).
  auto quad = [&](float x, float y, float w, float h, const float* c) {
    if (w < 1.0F || h < 1.0F) return;
    g_loading.white.size = Vec2(w, h);
    g_loading.white.position = Vec2(x, y);
    g_loading.white.color = Color(c[0], c[1], c[2], 128.0F);
    engine->renderer.renderer2D.render(g_loading.white);
  };

  for (int i = 0; i < s.imgCount; ++i) {
    const LoadingImageData& im = LS_IMAGES[s.imgFirst + i];
    Sprite& sp = g_loading.images[s.imgFirst + i];
    sp.size = Vec2(im.w, im.h);
    sp.position = Vec2(im.x * W - im.w * 0.5F, im.y * H - im.h * 0.5F);
    engine->renderer.renderer2D.render(sp);
  }
  for (int i = 0; i < s.txtCount; ++i) {
    const LoadingTextData& t = LS_TEXTS[s.txtFirst + i];
    Sprite& sp = g_loading.texts[s.txtFirst + i];
    sp.size = Vec2((float)t.w, (float)t.h);
    sp.position = Vec2(t.x * W - t.w * 0.5F, t.y * H - t.h * 0.5F);
    engine->renderer.renderer2D.render(sp);
  }
  for (int i = 0; i < s.barCount; ++i) {
    const LoadingBarData& b = LS_BARS[s.barFirst + i];
    const float bx = b.x * W - b.w * 0.5F;  // top-left of the bar
    const float by = b.y * H - b.h * 0.5F;
    if (b.kind == 0) {
      // Continuous: track under a left-anchored fill scaled by progress.
      quad(bx, by, b.w, b.h, b.bg);
      quad(bx, by, b.w * fraction, b.h, b.fill);
    } else {
      const int segs = b.segments < 1 ? 1 : b.segments;
      const int lit = (int)(fraction * segs + 0.001F);
      const float segW = (b.w - b.spacing * (segs - 1)) / segs;
      for (int k = 0; k < segs; ++k) {
        const float sx = bx + k * (segW + b.spacing);
        const float* c = (k < lit) ? b.fill : b.bg;
        if (b.segPath[0] != '\0') {
          Sprite& sp = g_loading.segs[s.barFirst + i];  // reused per segment
          sp.size = Vec2(segW, b.h);
          sp.position = Vec2(sx, by);
          sp.color = Color(c[0], c[1], c[2], 128.0F);
          engine->renderer.renderer2D.render(sp);
        } else {
          quad(sx, by, segW, b.h, c);
        }
      }
    }
  }
  engine->renderer.endFrame();
}
}  // namespace loadingscreen

// Where the torch is HELD, relative to the eye. A first-person flashlight
// normally sits exactly in the eye, and a light on the view axis lights
// precisely the surfaces it hides: its shadows fall behind their casters and
// only a rim ever reaches the screen (docs/flashlight.md, "Off the eye").
// Moving it right and down gives the beam a hand.
//
// The offset is taken in the BEAM's own frame, never the world's: right is
// the beam crossed with world up, and "down" is the beam's own up negated, so
// the light never slides ALONG the beam - which would change its reach and
// could drop it past a caster, where a shadow volume points back at the eye.
// Looking straight up or down leaves "right" undefined; there the offset
// direction has stopped meaning anything, so the eye is returned unchanged.
inline Vec4 flashHeldOrigin(const Vec4& eye, float dx, float dy, float dz,
                            float offRight, float offDown) {
  if (offRight == 0.0F && offDown == 0.0F) return eye;
  const float hl = sqrtf(dx * dx + dz * dz);
  if (hl < 0.001F) return eye;
  const float rx = -dz / hl, rz = dx / hl;          // right, unit, horizontal
  const float ux = -dx * dy / hl, uy = hl, uz = -dz * dy / hl;  // beam up
  return Vec4(eye.x + rx * offRight - ux * offDown,
              eye.y - uy * offDown,
              eye.z + rz * offRight - uz * offDown, 1.0F);
}

}
using namespace runtime_detail;

inline int editorBootScene();

// An editor Play launch may choose a scene without changing the project's
// saved startup scene. The runner writes a one-shot marker beside the ELF.
inline int editorBootScene() {
  static int scene = -1;
  if (scene >= 0) return scene;
  scene = START_SCENE;
  const std::string path = Tyra::FileUtils::fromCwd("launch.scene");
  FILE* f = fopen(path.c_str(), "rb");
  if (f) {
    int requested = -1;
    if (fscanf(f, "%d", &requested) == 1 && requested >= 0 &&
        requested < SCENE_COUNT) scene = requested;
    fclose(f);
    remove(path.c_str());
  }
  return scene;
}

// Minimum gap kept between the camera eye and any surface overhead. Must
// stay larger than the near clip distance (0.15, see clipMargin in init())
// or looking up at a ceiling the head touches would open a see-through hole.
inline constexpr float EYE_CLEARANCE = 0.2F;

// Last volume/pan sent to each emitter channel. audsrv RPCs are synchronous
// and share one client lock with the music stream, so updateSoundEmitters only
// issues an RPC when the quantized value changes. `sndChBus` is which reverb
// bus the cached pair was written for: an emitter moves to the incoming room's
// bus (a different SPU2 core, so a different CHANNEL) and the cache has to
// know it is describing a channel nobody is listening to any more.
inline int sndChVol[8] = {-1, -1, -1, -1, -1, -1, -1, -1};
inline int sndChPan[8] = {-999, -999, -999, -999, -999, -999, -999, -999};
inline int sndChBus[8] = {-1, -1, -1, -1, -1, -1, -1, -1};

// Which emitter currently owns each of the eight channels (a runtime object
// index, -1 = free). The slots used to be a hash of the object index
// (16 + (i & 7)), so the NINTH audible emitter silently muted one of the
// first eight and which one it was came down to scene order - an emitter at
// the player's feet could lose to one eight indices away and half a level
// off. They are handed to the LOUDEST emitters instead; see pickSoundSlots.
inline int sndSlotOwner[8] = {-1, -1, -1, -1, -1, -1, -1, -1};

// How much louder a challenger has to be before it takes a slot off the
// emitter holding it. Re-ranking on the raw value makes two emitters of
// near-equal volume trade the slot every frame, and because a change of owner
// retriggers, that is audible as stuttering. The volumes are already
// quantized to steps of 5 (see updateSoundEmitters), so this is two steps: far
// below what a listener can place, far above the jitter of walking.
inline const int kSndStealMargin = 10;

// One emitter's claim on a channel this frame: the runtime object, the
// volume/pan the loop worked out for it, and the author's priority.
struct SoundWant {
  int obj;
  int vol;
  int pan;
  int prio;
};

// Is `a` a better claim on a channel than `b`? Priority first - that is what
// the author set it for - and the volume only decides between equals. The
// margin applies to the volume alone: a higher priority takes a channel
// immediately, while two ambiences a step apart must not trade one every
// frame (see kSndStealMargin).
inline bool sndBeats(const SoundWant& a, const SoundWant& b, int margin) {
  if (a.prio != b.prio) return a.prio > b.prio;
  return a.vol > b.vol + margin;
}
// Kept between frames so the per-frame pass allocates nothing.
inline std::vector<SoundWant> sndWants;

inline bool sndHoldsSlot(int obj) {
  for (int s = 0; s < 8; ++s)
    if (sndSlotOwner[s] == obj) return true;
  return false;
}

inline const SoundWant* sndWantOf(const std::vector<SoundWant>& wants, int obj) {
  for (int k = 0; k < (int)wants.size(); ++k)
    if (wants[k].obj == obj) return &wants[k];
  return 0;  // wants nothing this frame
}

// Hands the eight emitter channels to the loudest emitters that want one.
// Three steps, each of them O(8 x emitters) of plain arithmetic:
//   1. a holder that has gone quiet (out of range, hidden, deactivated)
//      releases its channel;
//   2. free channels go to the loudest emitters holding none;
//   3. the loudest emitter still without one takes the quietest holder's
//      channel, but only if it beats it by kSndStealMargin.
// Step 3 is what makes the assignment stable: without the margin, two
// emitters a step apart swap every frame and retrigger each other to bits.
// A channel that changes hands has its volume/pan cache invalidated here, at
// the assignment - the same thing a bus switch does, and for the same reason.
inline void pickSoundSlots(const std::vector<SoundWant>& wants) {
  for (int s = 0; s < 8; ++s)
    if (sndSlotOwner[s] >= 0 && !sndWantOf(wants, sndSlotOwner[s]))
      sndSlotOwner[s] = -1;

  for (int s = 0; s < 8; ++s) {
    if (sndSlotOwner[s] >= 0) continue;
    const SoundWant* best = 0;
    for (int k = 0; k < (int)wants.size(); ++k) {
      if (sndHoldsSlot(wants[k].obj)) continue;
      if (!best || sndBeats(wants[k], *best, 0)) best = &wants[k];
    }
    if (!best) break;  // nobody is waiting
    sndSlotOwner[s] = best->obj;
    sndChVol[s] = -1;
    sndChPan[s] = -999;
  }

  // Bounded by the channel count: every pass moves exactly one emitter in and
  // one out, so eight is already more than can ever be useful.
  for (int pass = 0; pass < 8; ++pass) {
    const SoundWant* cand = 0;
    for (int k = 0; k < (int)wants.size(); ++k) {
      if (sndHoldsSlot(wants[k].obj)) continue;
      if (!cand || sndBeats(wants[k], *cand, 0)) cand = &wants[k];
    }
    if (!cand) break;
    int worst = -1;
    const SoundWant* worstWant = 0;
    for (int s = 0; s < 8; ++s) {
      const SoundWant* w = sndWantOf(wants, sndSlotOwner[s]);
      if (!w) continue;
      if (!worstWant || sndBeats(*worstWant, *w, 0)) { worstWant = w; worst = s; }
    }
    if (worst < 0 || !sndBeats(*cand, *worstWant, kSndStealMargin)) break;
    sndSlotOwner[worst] = cand->obj;
    sndChVol[worst] = -1;
    sndChPan[worst] = -999;
  }
}

// Reverb zone state (docs/reverb.md). The SPU2 has TWO reverb units, one per
// core, and the audsrv fork puts ADPCM channels 0-23 on core 1 and 24-47 on
// core 0 - so a bus is reachable only by the voices playing on its core. That
// is what makes a room CROSS-FADE possible, and it shapes everything here:
//
// - a room owns a bus. `reverbBus` is the one the room the listener is in
//   currently runs on, and `REVERB_BUS_BASE` turns it into the channel offset
//   every new sound is played at.
// - a change of PRESET hands the room to the OTHER bus, loads it there while
//   that bus is silent (switching the algorithm zeroes up to 96 KB of SPU2
//   work area and doing it under a live tail is audible), and then the two
//   depths ramp past each other.
// - a change of AMOUNT alone does not swap anything - two zones sharing a
//   preset just ramp on the one bus, exactly as before.
// - sounds already playing stay on the outgoing bus and finish in the room
//   they started in. That is not a compromise: it is what a real room does to
//   a sound you carry out of it.
// - depths are quantized and only pushed when they really move. These are IOP
//   RPCs like the emitter volumes above, and a per-frame RPC costs frames.
//
// The per-voice send mask deliberately lives in AudioReverb alone (both this
// file and the generated flow graphs write it), so there is no copy here.
inline int reverbBus = 0;                 // 0 = BusA (core 1), 1 = BusB
inline int reverbPresetCur[2] = {0, 0};   // preset loaded on each bus
inline float reverbAmt[2] = {0.0F, 0.0F}; // 0..1, the ramped wet level of each
inline int reverbDepthSent[2] = {-1, -1};

// --- Particle emitters ------------------------------------------------
// 2002-style particles: fixed pools sized at scene load, one cheap LCG,
// no trig and no allocations in the per-frame path. The EE simulates and
// writes one center + one qword of 2x2 basis weights + one color per
// particle; the VU1 billboard program (engine StaPipBillboardBag) expands
// each center into a camera-facing quad in clip space, so the quad
// building cost never touches the EE. An emitter with a material carrying
// a map_Kd draws its quads with that texture (the color then modulates
// it; corner UVs are fixed on VU1).
// The editor viewport mirrors this simulation (viewport.cpp,
// simulateEmitter) - keep the per-kind formulas in sync.
inline float prand(unsigned int& s) {  // 0..1
  s = s * 1664525u + 1013904223u;
  return (float)(s >> 8) * (1.0F / 16777216.0F);
}

// Menu progress easing, shared by the open transition and the caret. ease 0
// linear, 1 ease-out (the default a sheet gets), 2 ease-in-out.
inline float menuEase(float t, int ease) {
  if (t <= 0.0F) return 0.0F;
  if (t >= 1.0F) return 1.0F;
  if (ease == 0) return t;
  if (ease == 2) return t < 0.5F ? 2.0F * t * t : 1.0F - 2.0F * (1.0F - t) * (1.0F - t);
  const float inv = 1.0F - t;
  return 1.0F - inv * inv;
}

// ---- Animated HUD (docs/hud-animation.md) ---------------------------------
// The looped motion is a pure function of the clock, so a paused game and a
// resumed one draw the same frame and nothing accumulates. KEEP IN SYNC with
// hudanim::evaluate in the editor (src/hudanim.hpp) - the viewport overlay
// previews exactly this.
struct HudMotion {
  float dx = 0.0F, dy = 0.0F, scale = 1.0F, alpha = 1.0F;
  bool visible = true;
};

inline float hudNoise(int step, int channel) {
  const float v = sinf((float)step * 12.9898F + (float)channel * 78.233F) * 43758.5453F;
  return (v - floorf(v)) * 2.0F - 1.0F;
}

inline HudMotion hudAnimEval(int kind, float period, float amount, float t) {
  HudMotion m;
  if (kind <= 0 || kind >= 8) return m;
  if (period < 0.01F) period = 0.01F;
  const float ph = t / period * 6.2831853F;
  switch (kind) {
    case 1: m.alpha = 1.0F - amount * 0.5F * (1.0F - cosf(ph)); break;  // pulse
    case 2: m.dy = -sinf(ph) * amount; break;                            // bob
    case 3: m.dx = sinf(ph) * amount; break;                             // sway
    case 4: m.scale = 1.0F + amount * 0.5F * (1.0F - cosf(ph)); break;   // breathe
    case 5: {                                                            // blink
      const float cyc = t / period;
      m.visible = (cyc - floorf(cyc)) < amount;
      break;
    }
    case 6:                                                              // wobble
      m.dx = cosf(ph) * amount;
      m.dy = sinf(ph) * amount;
      break;
    case 7: {                                                            // shake
      const int step = (int)(t / period);
      m.dx = hudNoise(step, 0) * amount;
      m.dy = hudNoise(step, 1) * amount;
      break;
    }
    default: break;
  }
  if (m.alpha < 0.0F) m.alpha = 0.0F;
  if (m.alpha > 1.0F) m.alpha = 1.0F;
  if (m.scale < 0.05F) m.scale = 0.05F;
  return m;
}

// The show/hide transition at progress p (0 hidden .. 1 shown), folded into
// the frame's offset/scale/alpha. Eased out, so an arrival lands softly and a
// departure (the same curve run backwards) starts quickly. Runtime-only: the
// editor does not preview it.
inline void hudTransEval(int kind, float p, float& dx, float& dy, float& scale,
                         float& alpha) {
  if (kind <= 0 || p >= 1.0F) return;
  const float e = 1.0F - (1.0F - p) * (1.0F - p);
  const float d = (1.0F - e) * 40.0F;
  switch (kind) {
    case 1: alpha *= e; break;                       // fade
    case 2: dx -= d; alpha *= e; break;              // from the left
    case 3: dx += d; alpha *= e; break;              // from the right
    case 4: dy -= d; alpha *= e; break;              // from above
    case 5: dy += d; alpha *= e; break;              // from below
    case 6: scale *= 0.3F + 0.7F * e; alpha *= e; break;  // pop
    default: break;
  }
}

// A one-shot effect at progress p (0..1 over its duration). `bright` is a
// multiplier on the sprite's colour - the GS modulates at 128 = 1.0 and
// clamps at 255, so a flash can go to 2x.
inline void hudFxEval(int kind, float p, float& dx, float& dy, float& scale,
                      float& bright) {
  const float r = 1.0F - p;
  switch (kind) {
    case 1: bright *= 1.0F + 0.9F * r; break;                       // flash
    case 2: scale *= 1.0F + 0.35F * sinf(p * 3.1415927F); break;     // bounce
    case 3: {                                                        // shake
      const int step = (int)(p * 60.0F);
      dx += hudNoise(step, 2) * 6.0F * r;
      dy += hudNoise(step, 3) * 6.0F * r;
      break;
    }
    default: break;
  }
}

// Poses one element for the frame: its authored box (centre + size, in screen
// pixels) through the loop, the transition and any running effect. Returns
// false when nothing should be drawn (fully hidden, or a Blink's off phase).
inline bool hudPose(float clock, int animKind, float animPeriod, float animAmount,
                    int transKind, float trans, int fx, float fxP, float cx,
                    float cy, float w, float h, float& outX, float& outY,
                    float& outW, float& outH, float& outAlpha, float& outBright) {
  if (trans <= 0.0F) return false;
  const HudMotion m = hudAnimEval(animKind, animPeriod, animAmount, clock);
  if (!m.visible) return false;
  float dx = m.dx, dy = m.dy, scale = m.scale, alpha = m.alpha, bright = 1.0F;
  hudTransEval(transKind, trans, dx, dy, scale, alpha);
  if (fx > 0) hudFxEval(fx, fxP, dx, dy, scale, bright);
  if (alpha <= 0.002F) return false;
  outW = w * scale;
  outH = h * scale;
  outX = cx + dx - outW * 0.5F;
  outY = cy + dy - outH * 0.5F;
  outAlpha = alpha;
  outBright = bright;
  return true;
}

inline Color hudTint(float r, float g, float b, float bright, float alpha) {
  auto ch = [](float v) { return v > 255.0F ? 255.0F : v < 0.0F ? 0.0F : v; };
  return Color(ch(r * bright), ch(g * bright), ch(b * bright), ch(128.0F * alpha));
}

// An ORIENTED box the flashlight's beam can land on - see projCollectBoxes,
// which fills these, and projWallHit, which intersects them. Declared up here
// because updateAndRenderLightPools is the consumer and it comes first.
struct ProjBox {
  float o[3];                 // centre, world
  float ax[3], ay[3], az[3];  // rotated unit axes
  float h[3];                 // half extents along them
  int obj;                    // index into runtimeObjects
  int type;                   // SceneObjectData::type
};
inline std::vector<ProjBox> g_projBoxes;

// Does this spot light carve its own occlusion? The per-light override wins
// and 0 falls through to the project switch (docs/shadows.md, "Spot-light
// shadow volumes"). Compiles away to `false` in a project that asked for
// neither, which is what keeps SPOT_SHADOW_VOLUMES_USED honest.
inline bool spotVolumesOn(const SceneObjectData& d) {
  return d.lightShadowVolumes == 2 ||
         (d.lightShadowVolumes == 0 && SPOT_SHADOW_VOLUMES);
}

// Does this box stand between two points? The ordinary slab test in the box's
// own frame, over the SEGMENT rather than a ray. Used to keep the EYE out of a
// spot light's shadow volume - see pickVolCasters.
inline bool boxBlocksSegment(const ProjBox& pb, const Vec4& from,
                             const Vec4& to) {
  const float sx = to.x - from.x, sy = to.y - from.y, sz = to.z - from.z;
  const float ox = from.x - pb.o[0], oy = from.y - pb.o[1],
              oz = from.z - pb.o[2];
  float t0 = 0.0F, t1 = 1.0F;
  for (int ai = 0; ai < 3; ++ai) {
    const float* ax = ai == 0 ? pb.ax : (ai == 1 ? pb.ay : pb.az);
    const float p = ox * ax[0] + oy * ax[1] + oz * ax[2];
    const float q = sx * ax[0] + sy * ax[1] + sz * ax[2];
    const float h = pb.h[ai];
    if (q > -1e-5F && q < 1e-5F) {
      if (p < -h || p > h) return false;
      continue;
    }
    float lo = (-h - p) / q, hi = (h - p) / q;
    if (lo > hi) {
      const float tmp = lo;
      lo = hi, hi = tmp;
    }
    if (lo > t0) t0 = lo;
    if (hi < t1) t1 = hi;
    if (t0 > t1) return false;
  }
  return true;
}

// WHICH SPOT LIGHT CARVES THIS FRAME (docs/shadows.md, "Only one spot casts
// per frame"). The count band is a single GS buffer and a counting bracket is
// per light per frame, so a scene holding six shadow-casting lamps must not
// cost six times one lamp: the nearest lit one holds the slot and the rest
// light their cones plainly. g_spotVolWant is the challenger that has to
// out-stay the hysteresis before it may take the slot over - without it two
// lamps at nearly equal distance trade it every frame and the scene's shadows
// blink.
inline int g_spotVolObj = -1;
inline int g_spotVolWant = -1;
inline int g_spotVolWantFrames = 0;

// The shadow volumes are cut from BOXES, and one AABB around a sparse model
// lies about its shape: a lamp post's box (pole plus arm) is a slab of
// mostly air, and its "shadow" blotted out whole walls. So a model's volume
// is cut from up to three TIGHT sub-boxes instead: split the triangles at
// the median of the box's longest axis, twice, then greedily merge leaves
// back wherever the split bought nothing - a solid crate merges back to one
// box, an L-shape stays a pole and an arm. Each sub-box is convex, which is
// the one thing the 1-bit destination-alpha trick genuinely requires (the
// GS cannot COUNT like a stencil, so a non-convex volume's set/clear order
// lies; a true mesh volume is off the table for exactly that reason).
struct ShadowSubBox {
  float mn[3], mx[3];
};
// Lazily built per MODEL asset (local space, shared by every instance),
// keyed by gameModels index; cleared whenever the model table changes size.
inline std::vector<std::vector<ShadowSubBox>> g_shadowSubBoxes;

inline void buildShadowSubBoxes(
    const std::vector<const std::vector<float>*>& parts,
    std::vector<ShadowSubBox>& out) {
  struct Tri {
    float cen[3];
    float mn[3], mx[3];
  };
  std::vector<Tri> tris;
  for (const std::vector<float>* pv : parts) {
    const std::vector<float>& v = *pv;
    const size_t n = v.size() / 8;
    for (size_t i = 0; i + 3 <= n; i += 3) {
      Tri t;
      for (int a = 0; a < 3; ++a) {
        const float p0 = v[(i + 0) * 8 + a];
        const float p1 = v[(i + 1) * 8 + a];
        const float p2 = v[(i + 2) * 8 + a];
        t.cen[a] = (p0 + p1 + p2) / 3.0F;
        t.mn[a] = p0 < p1 ? (p0 < p2 ? p0 : p2) : (p1 < p2 ? p1 : p2);
        t.mx[a] = p0 > p1 ? (p0 > p2 ? p0 : p2) : (p1 > p2 ? p1 : p2);
      }
      tris.push_back(t);
    }
  }
  auto boxOf = [&](const std::vector<int>& idx, ShadowSubBox& b) {
    b.mn[0] = b.mn[1] = b.mn[2] = 1e30F;
    b.mx[0] = b.mx[1] = b.mx[2] = -1e30F;
    for (int i : idx)
      for (int a = 0; a < 3; ++a) {
        if (tris[i].mn[a] < b.mn[a]) b.mn[a] = tris[i].mn[a];
        if (tris[i].mx[a] > b.mx[a]) b.mx[a] = tris[i].mx[a];
      }
  };
  // A padded volume, so flat boxes still compare meaningfully.
  auto volOf = [](const ShadowSubBox& b) {
    return (b.mx[0] - b.mn[0] + 0.05F) * (b.mx[1] - b.mn[1] + 0.05F) *
           (b.mx[2] - b.mn[2] + 0.05F);
  };
  out.clear();
  if (tris.empty()) return;
  std::vector<int> all(tris.size());
  for (size_t i = 0; i < tris.size(); ++i) all[i] = (int)i;
  // Median split on the longest axis, applied twice -> up to four leaves.
  // Iterative on purpose (no std::function in the game TU).
  auto halve = [&](const std::vector<int>& idx, std::vector<int>& lo,
                   std::vector<int>& hi) {
    ShadowSubBox b;
    boxOf(idx, b);
    int ax = 0;
    float best = b.mx[0] - b.mn[0];
    for (int a = 1; a < 3; ++a)
      if (b.mx[a] - b.mn[a] > best) best = b.mx[a] - b.mn[a], ax = a;
    std::vector<int> srt = idx;
    std::sort(srt.begin(), srt.end(), [&](int l, int r) {
      return tris[l].cen[ax] < tris[r].cen[ax];
    });
    lo.assign(srt.begin(), srt.begin() + srt.size() / 2);
    hi.assign(srt.begin() + srt.size() / 2, srt.end());
  };
  std::vector<std::vector<int>> leaves;
  if (all.size() < 8) {
    leaves.push_back(all);
  } else {
    std::vector<int> lo, hi;
    halve(all, lo, hi);
    std::vector<std::vector<int>> level = {lo, hi};
    for (std::vector<int>& half : level) {
      if (half.size() < 8) {
        leaves.push_back(half);
        continue;
      }
      std::vector<int> l2, h2;
      halve(half, l2, h2);
      leaves.push_back(l2);
      leaves.push_back(h2);
    }
  }
  std::vector<ShadowSubBox> boxes;
  for (std::vector<int>& lf : leaves) {
    if (lf.empty()) continue;
    ShadowSubBox b;
    boxOf(lf, b);
    boxes.push_back(b);
  }
  // Greedy merge: whenever a union costs little more than its parts, the
  // split bought nothing - a solid model collapses back to one box.
  auto tryMerge = [&](float slack) {
    for (bool again = true; again;) {
      again = false;
      for (size_t i = 0; i < boxes.size() && !again; ++i)
        for (size_t j = i + 1; j < boxes.size() && !again; ++j) {
          ShadowSubBox u;
          for (int a = 0; a < 3; ++a) {
            u.mn[a] = boxes[i].mn[a] < boxes[j].mn[a] ? boxes[i].mn[a]
                                                      : boxes[j].mn[a];
            u.mx[a] = boxes[i].mx[a] > boxes[j].mx[a] ? boxes[i].mx[a]
                                                      : boxes[j].mx[a];
          }
          if (volOf(u) <= (volOf(boxes[i]) + volOf(boxes[j])) * slack) {
            boxes[i] = u;
            boxes.erase(boxes.begin() + j);
            again = true;
          }
        }
    }
  };
  tryMerge(1.4F);
  // Cap at three: force-merge the cheapest pairs beyond that.
  while (boxes.size() > 3) {
    size_t bi = 0, bj = 1;
    float bestCost = 1e30F;
    for (size_t i = 0; i < boxes.size(); ++i)
      for (size_t j = i + 1; j < boxes.size(); ++j) {
        ShadowSubBox u;
        for (int a = 0; a < 3; ++a) {
          u.mn[a] = boxes[i].mn[a] < boxes[j].mn[a] ? boxes[i].mn[a]
                                                    : boxes[j].mn[a];
          u.mx[a] = boxes[i].mx[a] > boxes[j].mx[a] ? boxes[i].mx[a]
                                                    : boxes[j].mx[a];
        }
        const float c = volOf(u);
        if (c < bestCost) bestCost = c, bi = i, bj = j;
      }
    ShadowSubBox u;
    for (int a = 0; a < 3; ++a) {
      u.mn[a] = boxes[bi].mn[a] < boxes[bj].mn[a] ? boxes[bi].mn[a]
                                                  : boxes[bj].mn[a];
      u.mx[a] = boxes[bi].mx[a] > boxes[bj].mx[a] ? boxes[bi].mx[a]
                                                  : boxes[bj].mx[a];
    }
    boxes[bi] = u;
    boxes.erase(boxes.begin() + bj);
  }
  out = boxes;
}

// True MESH-SHAPED volumes (docs/flashlight.md "The shadow"): with the
// count target up, a model caster no longer casts from boxes - its real
// triangles are classified against the torch, the silhouette edges are
// extruded to the light's range, and the counting mask makes the resulting
// (thoroughly concave, self-overlapping) volume exact per pixel. The
// adjacency is built once per MODEL asset, in local space, shared by every
// instance - the g_shadowSubBoxes arrangement.
struct ShadowMesh {
  std::vector<float> pos;  // welded positions, xyz per vertex
  std::vector<int> tri;    // three welded ids per triangle, winding kept
  std::vector<int> edge;   // a, b, t0, t1 per edge; t1 = -1 = open edge
};
inline std::vector<ShadowMesh> g_shadowMeshes;
inline std::vector<char> g_shadowMeshTried;
// Past this budget the per-frame classification stops being cheap on the EE
// - so the build bakes a decimated SHADOW PROXY under it into the .tmdl
// (GameModel::shadowVerts, meshlod::generateShadowProxy) and the caster
// extrudes that; only a model the decimator could not bring under budget
// keeps its sub-boxes (through the same counting bracket). The number is
// spliced from the editor's meshlod::kShadowProxyMaxTris, so the bake and
// this check can never disagree.
inline constexpr int kShadowMeshMaxTris = 1200;

// `stride` = floats per corner: 8 for the drawn parts (x y z nx ny nz u v),
// 3 for the baked shadow proxy (positions only).
inline void buildShadowMesh(
    const std::vector<const std::vector<float>*>& parts, ShadowMesh& out,
    size_t stride = 8) {
  size_t triCount = 0;
  for (const std::vector<float>* pv : parts)
    triCount += pv->size() / stride / 3;
  if (triCount == 0 || triCount > (size_t)kShadowMeshMaxTris) return;
  // Corner positions, in triangle order. The model pipeline duplicates a
  // shared position VERBATIM per corner (one source position, many
  // corners), so welding by exact equality is the honest key - no epsilon
  // to mistune, and -0.0 folding into 0.0 is a merge, not a loss.
  std::vector<float> corner;
  corner.reserve(triCount * 9);
  for (const std::vector<float>* pv : parts) {
    const std::vector<float>& v = *pv;
    const size_t n = v.size() / stride / 3 * 3;
    for (size_t i = 0; i < n; ++i) {
      corner.push_back(v[i * stride + 0]);
      corner.push_back(v[i * stride + 1]);
      corner.push_back(v[i * stride + 2]);
    }
  }
  const int nc = (int)(corner.size() / 3);
  auto posLess = [&](int l, int r) {
    if (corner[l * 3] != corner[r * 3]) return corner[l * 3] < corner[r * 3];
    if (corner[l * 3 + 1] != corner[r * 3 + 1])
      return corner[l * 3 + 1] < corner[r * 3 + 1];
    return corner[l * 3 + 2] < corner[r * 3 + 2];
  };
  auto posEq = [&](int l, int r) {
    return corner[l * 3] == corner[r * 3] &&
           corner[l * 3 + 1] == corner[r * 3 + 1] &&
           corner[l * 3 + 2] == corner[r * 3 + 2];
  };
  std::vector<int> order(nc);
  for (int i = 0; i < nc; ++i) order[i] = i;
  std::sort(order.begin(), order.end(), posLess);
  std::vector<int> weldOf(nc, 0);
  int prev = -1;
  for (int oi : order) {
    if (prev < 0 || !posEq(prev, oi)) {
      out.pos.push_back(corner[oi * 3 + 0]);
      out.pos.push_back(corner[oi * 3 + 1]);
      out.pos.push_back(corner[oi * 3 + 2]);
      prev = oi;
    }
    weldOf[oi] = (int)(out.pos.size() / 3) - 1;
  }
  out.tri.reserve(nc);
  for (int c = 0; c + 3 <= nc; c += 3) {
    const int a = weldOf[c], b = weldOf[c + 1], d = weldOf[c + 2];
    if (a == b || b == d || a == d) continue;  // degenerate
    out.tri.push_back(a);
    out.tri.push_back(b);
    out.tri.push_back(d);
  }
  // Edges: (min,max) welded pair -> up to two owner triangles. A single
  // owner is an OPEN edge - these models are not watertight, and an open
  // edge silhouettes whenever its one face is lit, or the volume around an
  // open lit region would not close. A third owner (non-manifold) is
  // ignored: two owners already decide the silhouette question.
  const int nt = (int)(out.tri.size() / 3);
  std::vector<std::pair<unsigned, int>> ev;
  ev.reserve(nt * 3);
  for (int t = 0; t < nt; ++t)
    for (int e = 0; e < 3; ++e) {
      int a = out.tri[t * 3 + e], b = out.tri[t * 3 + (e + 1) % 3];
      if (a > b) {
        const int tmp = a;
        a = b, b = tmp;
      }
      ev.push_back({(unsigned)a * 65536u + (unsigned)b, t});
    }
  std::sort(ev.begin(), ev.end());
  for (size_t i = 0; i < ev.size();) {
    size_t j = i;
    while (j < ev.size() && ev[j].first == ev[i].first) ++j;
    out.edge.push_back((int)(ev[i].first / 65536u));
    out.edge.push_back((int)(ev[i].first % 65536u));
    out.edge.push_back(ev[i].second);
    out.edge.push_back(j - i > 1 ? ev[i + 1].second : -1);
    i = j;
  }
}

// One caster's silhouette-extruded volume, world space, split by camera
// facing for the counting bracket. vL is the VIRTUAL torch: the real one
// sits exactly in the eye, and a light in the eye hides every shadow
// exactly behind its own caster - so the volumes extrude from a point
// pushed a short way down the beam (a hand-held light's parallax), which
// makes every shadow diverge a little and show around its caster, the way
// the silhouette mode's wider-FOV projector does.
inline void emitMeshShadowVolume(const ShadowMesh& m,
                                 const SceneObjectData& cdd,
                                 const ProjBox& basis, const Vec4& vL,
                                 const Vec4& cam, float range, bool farCaps,
                                 BagArray<Vec4>& outFront,
                                 BagArray<Vec4>& outBack) {
  const int nv = (int)(m.pos.size() / 3);
  const int nt = (int)(m.tri.size() / 3);
  static std::vector<float> nw;  // near points (pushed), world
  static std::vector<float> fw;  // far projections, world
  static std::vector<char> lit;
  nw.resize(nv * 3);
  fw.resize(nv * 3);
  lit.assign(nt, 0);
  for (int i = 0; i < nv; ++i) {
    const float sx = m.pos[i * 3 + 0] * cdd.scale[0];
    const float sy = m.pos[i * 3 + 1] * cdd.scale[1];
    const float sz = m.pos[i * 3 + 2] * cdd.scale[2];
    const float wx = cdd.position[0] + basis.ax[0] * sx + basis.ay[0] * sy +
                     basis.az[0] * sz;
    const float wy = cdd.position[1] + basis.ax[1] * sx + basis.ay[1] * sy +
                     basis.az[1] * sz;
    const float wz = cdd.position[2] + basis.ax[2] * sx + basis.ay[2] * sy +
                     basis.az[2] * sz;
    float dx2 = wx - vL.x, dy2 = wy - vL.y, dz2 = wz - vL.z;
    const float dl = sqrtf(dx2 * dx2 + dy2 * dy2 + dz2 * dz2);
    const float inv = dl > 0.05F ? 1.0F / dl : 20.0F;
    dx2 *= inv, dy2 *= inv, dz2 *= inv;
    // The near cap is pushed a hair DOWN the ray: it breaks the depth tie
    // against the caster's own surface without moving the pixel it projects
    // to from the light - from the eye the parallax IS the fringe.
    nw[i * 3 + 0] = wx + dx2 * 0.05F;
    nw[i * 3 + 1] = wy + dy2 * 0.05F;
    nw[i * 3 + 2] = wz + dz2 * 0.05F;
    fw[i * 3 + 0] = vL.x + dx2 * range;
    fw[i * 3 + 1] = vL.y + dy2 * range;
    fw[i * 3 + 2] = vL.z + dz2 * range;
  }
  // Orientation is GEOMETRIC, not winding-trusted: a cap's outward side is
  // toward the light (near) or away from it (far), a side quad's is away
  // from an interior sample. Only the lit/unlit split reads the winding
  // normal - and a globally flipped mesh then builds the volume from its
  // BACK faces, whose silhouette is the same, so it degrades gracefully.
  auto emitTri = [&](const float* a, const float* b, const float* c,
                     const float* refPt, bool refIsInterior) {
    const float ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2];
    const float vx = c[0] - a[0], vy = c[1] - a[1], vz = c[2] - a[2];
    float nx = uy * vz - uz * vy, ny = uz * vx - ux * vz,
          nz = ux * vy - uy * vx;
    const float cx = (a[0] + b[0] + c[0]) / 3.0F,
                cy = (a[1] + b[1] + c[1]) / 3.0F,
                cz = (a[2] + b[2] + c[2]) / 3.0F;
    float s = nx * (refPt[0] - cx) + ny * (refPt[1] - cy) +
              nz * (refPt[2] - cz);
    if (refIsInterior) s = -s;
    if (s < 0.0F) nx = -nx, ny = -ny, nz = -nz;
    const bool front =
        nx * (cam.x - cx) + ny * (cam.y - cy) + nz * (cam.z - cz) > 0.0F;
    BagArray<Vec4>& dst = front ? outFront : outBack;
    if (dst.size() > 3996) return;  // fill-rate backstop
    dst.push_back(Vec4(a[0], a[1], a[2], 1.0F));
    dst.push_back(Vec4(b[0], b[1], b[2], 1.0F));
    dst.push_back(Vec4(c[0], c[1], c[2], 1.0F));
  };
  const float vlp[3] = {vL.x, vL.y, vL.z};
  for (int t = 0; t < nt; ++t) {
    const float* a = &nw[m.tri[t * 3 + 0] * 3];
    const float* b = &nw[m.tri[t * 3 + 1] * 3];
    const float* c = &nw[m.tri[t * 3 + 2] * 3];
    const float ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2];
    const float vx = c[0] - a[0], vy = c[1] - a[1], vz = c[2] - a[2];
    const float nx = uy * vz - uz * vy, ny = uz * vx - ux * vz,
                nz = ux * vy - uy * vx;
    const float cx = (a[0] + b[0] + c[0]) / 3.0F,
                cy = (a[1] + b[1] + c[1]) / 3.0F,
                cz = (a[2] + b[2] + c[2]) / 3.0F;
    lit[t] = nx * (vL.x - cx) + ny * (vL.y - cy) + nz * (vL.z - cz) > 0.0F;
    if (lit[t]) continue;
    // Near cap - the face turned AWAY from the light, so the volume starts
    // beyond the caster and never swallows it (emitBoxShadowVolume carries
    // the full reasoning). It matters twice over here: a DECIMATED hull
    // stands proud of every surface the real mesh recesses, so a lit-side
    // cap put the panel lines of a barrel into their own shadow.
    // And its far projection only when
    // asked: a far cap only ever SUBTRACTS at pixels whose surface lies
    // beyond the light's range, where the reach falloff has already taken
    // the light to zero, so the counting path skips the fill entirely.
    emitTri(a, b, c, vlp, false);
    if (farCaps)
      emitTri(&fw[m.tri[t * 3 + 0] * 3], &fw[m.tri[t * 3 + 1] * 3],
              &fw[m.tri[t * 3 + 2] * 3], vlp, true);
  }
  const int ne = (int)(m.edge.size() / 4);
  for (int e = 0; e < ne; ++e) {
    const int t0 = m.edge[e * 4 + 2], t1 = m.edge[e * 4 + 3];
    int owner = -1;
    if (t1 < 0) {
      if (lit[t0]) owner = t0;
    } else if (lit[t0] != lit[t1]) {
      owner = lit[t0] ? t0 : t1;
    }
    if (owner < 0) continue;
    const int a = m.edge[e * 4 + 0], b = m.edge[e * 4 + 1];
    const float* na = &nw[a * 3];
    const float* nb = &nw[b * 3];
    const float* fa = &fw[a * 3];
    const float* fb = &fw[b * 3];
    // Interior reference: the edge midpoint nudged toward the lit owner's
    // centroid, then pushed one unit down the ray - just inside the wall
    // this quad is about to become.
    const float ocx = (nw[m.tri[owner * 3] * 3 + 0] +
                       nw[m.tri[owner * 3 + 1] * 3 + 0] +
                       nw[m.tri[owner * 3 + 2] * 3 + 0]) /
                      3.0F;
    const float ocy = (nw[m.tri[owner * 3] * 3 + 1] +
                       nw[m.tri[owner * 3 + 1] * 3 + 1] +
                       nw[m.tri[owner * 3 + 2] * 3 + 1]) /
                      3.0F;
    const float ocz = (nw[m.tri[owner * 3] * 3 + 2] +
                       nw[m.tri[owner * 3 + 1] * 3 + 2] +
                       nw[m.tri[owner * 3 + 2] * 3 + 2]) /
                      3.0F;
    float mx = (na[0] + nb[0]) * 0.5F, my = (na[1] + nb[1]) * 0.5F,
          mz = (na[2] + nb[2]) * 0.5F;
    mx += (ocx - mx) * 0.25F;
    my += (ocy - my) * 0.25F;
    mz += (ocz - mz) * 0.25F;
    float rx2 = mx - vL.x, ry2 = my - vL.y, rz2 = mz - vL.z;
    const float rl = sqrtf(rx2 * rx2 + ry2 * ry2 + rz2 * rz2);
    const float ri = rl > 0.05F ? 1.0F / rl : 20.0F;
    const float in[3] = {mx + rx2 * ri, my + ry2 * ri, mz + rz2 * ri};
    emitTri(na, nb, fb, in, true);
    emitTri(na, fb, fa, in, true);
  }
}

// One convex BOX's shadow volume (a primitive caster, or one tight sub-box
// of a heavy model), extruded from `origin`, split by camera facing. Shared
// by the counting path (origin = the virtual torch, all pieces appended
// into one bracket) and the 1-bit fallback (origin = the eye, one convex
// piece per bracket).
inline void emitBoxShadowVolume(const ProjBox& pb, const Vec4& origin,
                                const Vec4& cam, float range, bool farCaps,
                                BagArray<Vec4>& outFront,
                                BagArray<Vec4>& outBack) {
  // Box corners (bit code x|y<<1|z<<2), pushed a hair AWAY from the light:
  // the push only breaks the depth TIE against the next surface a cap might
  // touch.
  Vec4 nearP[8], farP[8];
  for (int ci = 0; ci < 8; ++ci) {
    const float sx = (ci & 1) ? 1.0F : -1.0F;
    const float sy = (ci & 2) ? 1.0F : -1.0F;
    const float sz = (ci & 4) ? 1.0F : -1.0F;
    const float wx = pb.o[0] + pb.ax[0] * pb.h[0] * sx +
                     pb.ay[0] * pb.h[1] * sy + pb.az[0] * pb.h[2] * sz;
    const float wy = pb.o[1] + pb.ax[1] * pb.h[0] * sx +
                     pb.ay[1] * pb.h[1] * sy + pb.az[1] * pb.h[2] * sz;
    const float wz = pb.o[2] + pb.ax[2] * pb.h[0] * sx +
                     pb.ay[2] * pb.h[1] * sy + pb.az[2] * pb.h[2] * sz;
    float ddx2 = wx - origin.x, ddy2 = wy - origin.y, ddz2 = wz - origin.z;
    const float dl2 = sqrtf(ddx2 * ddx2 + ddy2 * ddy2 + ddz2 * ddz2);
    const float inv = dl2 > 0.05F ? 1.0F / dl2 : 20.0F;
    ddx2 *= inv, ddy2 *= inv, ddz2 *= inv;
    nearP[ci] = Vec4(wx + ddx2 * 0.05F, wy + ddy2 * 0.05F, wz + ddz2 * 0.05F,
                     1.0F);
    farP[ci] = Vec4(origin.x + ddx2 * range, origin.y + ddy2 * range,
                    origin.z + ddz2 * range, 1.0F);
  }
  float volC[3] = {0.0F, 0.0F, 0.0F};
  for (int ci = 0; ci < 8; ++ci) {
    volC[0] += (nearP[ci].x + farP[ci].x) / 16.0F;
    volC[1] += (nearP[ci].y + farP[ci].y) / 16.0F;
    volC[2] += (nearP[ci].z + farP[ci].z) / 16.0F;
  }
  auto pushTri = [&](const Vec4& a3, const Vec4& b3, const Vec4& c3) {
    const float ux2 = b3.x - a3.x, uy2 = b3.y - a3.y, uz2 = b3.z - a3.z;
    const float vx2 = c3.x - a3.x, vy2 = c3.y - a3.y, vz2 = c3.z - a3.z;
    float nx2 = uy2 * vz2 - uz2 * vy2, ny2 = uz2 * vx2 - ux2 * vz2,
          nz2 = ux2 * vy2 - uy2 * vx2;
    const float cx3 = (a3.x + b3.x + c3.x) / 3.0F,
                cy3 = (a3.y + b3.y + c3.y) / 3.0F,
                cz3 = (a3.z + b3.z + c3.z) / 3.0F;
    // Winding is whatever the tables gave; orient the normal OUTWARD via
    // the volume centroid (sound - a box volume is convex), then classify
    // against the camera. The GS has no face culling.
    if (nx2 * (cx3 - volC[0]) + ny2 * (cy3 - volC[1]) +
            nz2 * (cz3 - volC[2]) <
        0.0F)
      nx2 = -nx2, ny2 = -ny2, nz2 = -nz2;
    const bool front =
        nx2 * (cam.x - cx3) + ny2 * (cam.y - cy3) + nz2 * (cam.z - cz3) >
        0.0F;
    BagArray<Vec4>& dst = front ? outFront : outBack;
    if (dst.size() > 3996) return;
    dst.push_back(a3);
    dst.push_back(b3);
    dst.push_back(c3);
  };
  // 6 faces: corner indices + outward axis; lit = faces the light.
  static const int kFace[6][4] = {{0, 2, 6, 4}, {1, 3, 7, 5}, {0, 1, 5, 4},
                                  {2, 3, 7, 6}, {0, 1, 3, 2}, {4, 5, 7, 6}};
  static const int kFaceAxis[6] = {0, 0, 1, 1, 2, 2};
  static const float kFaceSign[6] = {-1, 1, -1, 1, -1, 1};
  bool lit[6];
  for (int f = 0; f < 6; ++f) {
    const int a4 = kFaceAxis[f];
    const float* ax2 = a4 == 0 ? pb.ax : (a4 == 1 ? pb.ay : pb.az);
    float fc[3];
    for (int c4 = 0; c4 < 3; ++c4)
      fc[c4] = pb.o[c4] + ax2[c4] * pb.h[a4] * kFaceSign[f];
    lit[f] = (fc[0] - origin.x) * ax2[0] * kFaceSign[f] +
                 (fc[1] - origin.y) * ax2[1] * kFaceSign[f] +
                 (fc[2] - origin.z) * ax2[2] * kFaceSign[f] <
             0.0F;
    // THE CAP GOES ON THE DARK SIDE, and everything about how a shadow
    // LOOKS here follows from that one word. Capped on the LIT faces the
    // volume contains the box - and with it the caster's whole mesh, which
    // the box only stands in for. Counting is exact, so every one of those
    // pixels resolved as shadow: the prop the torch was pointed at came
    // back black in patches and the BOX's own footprint sat on the ground
    // around it as a hard-edged rectangle, which reads as a shadow and is
    // not one (a 2092-triangle barrel is over kShadowMeshMaxTris, so its
    // volume IS this box). The 0.05 push only ever broke a depth tie.
    // Capping on the UNLIT faces starts the volume at the caster's far side
    // instead; the silhouette ring is shared by both halves, so the shape
    // the shadow makes on screen does not move.
    if (!lit[f]) {
      const int* q4 = kFace[f];
      // near cap (the occluder's dark side) and - for the 1-bit fallback,
      // whose set/clear needs the closed volume - its far projection; the
      // counting path skips far caps (they only subtract beyond the reach)
      pushTri(nearP[q4[0]], nearP[q4[1]], nearP[q4[2]]);
      pushTri(nearP[q4[0]], nearP[q4[2]], nearP[q4[3]]);
      if (farCaps) {
        pushTri(farP[q4[0]], farP[q4[1]], farP[q4[2]]);
        pushTri(farP[q4[0]], farP[q4[2]], farP[q4[3]]);
      }
    }
  }
  // Silhouette edges (adjacent faces disagree about the light): the
  // extruded side quads that close the volume.
  static const int kEdge[12][4] = {
      {0, 1, 2, 4}, {2, 3, 3, 4}, {4, 5, 2, 5}, {6, 7, 3, 5},
      {0, 2, 0, 4}, {1, 3, 1, 4}, {4, 6, 0, 5}, {5, 7, 1, 5},
      {0, 4, 0, 2}, {1, 5, 1, 2}, {2, 6, 0, 3}, {3, 7, 1, 3}};
  for (int e = 0; e < 12; ++e) {
    if (lit[kEdge[e][2]] == lit[kEdge[e][3]]) continue;
    const int p0 = kEdge[e][0], p1 = kEdge[e][1];
    pushTri(nearP[p0], nearP[p1], farP[p1]);
    pushTri(nearP[p0], farP[p1], farP[p0]);
  }
}

// A PRIMITIVE caster's silhouette mesh. A model has a shared local-space
// asset (gameModels) the volume code reads its triangles from; a primitive
// has none - addBox/addSphere/addCylinder/addCone emit its triangles straight
// into WORLD space per object, shaded, through pushVert - which is why the
// primitives were the one caster that kept extruding a bounding box after the
// models stopped. So the same builders run here once per (type, detail,
// rings) on an identity object, giving the unit mesh in local space that
// emitMeshShadowVolume then places with the caster's own basis and scale,
// exactly as it does a model. The detail steps down until the mesh fits the
// triangle budget (a detail-64 sphere is 5760 triangles), so a curved
// primitive casts its curve at whatever resolution the EE can afford rather
// than its box. Planes and decals stay out: a one-sided sheet has no unlit
// side to cap on, so its volume would never close.
struct PrimShadowKey {
  int type, detail, rings;
};
inline std::vector<std::pair<PrimShadowKey, ShadowMesh>> g_primShadowMeshes;
inline const ShadowMesh* primShadowMesh(const SceneObjectData& cdd) {
  if (cdd.type < 0 || cdd.type > 3) return nullptr;
  const PrimShadowKey key{cdd.type, cdd.primDetail, cdd.primRings ? 1 : 0};
  for (const auto& e : g_primShadowMeshes)
    if (e.first.type == key.type && e.first.detail == key.detail &&
        e.first.rings == key.rings)
      return e.second.tri.empty() ? nullptr : &e.second;
  g_primShadowMeshes.push_back({key, ShadowMesh()});
  ShadowMesh& sm = g_primShadowMeshes.back().second;
  // pushVert feeds several side channels of the scene build; none is live
  // at render time, but a stale pointer would be a silent write into a
  // freed vector, so they are parked for the duration.
  BagArray<Vec4>* litSave = g_litNormals;
  BagArray<Vec4>* envSave = g_envNormals;
  BagArray<Vec4>* aoStsSave = g_aoSts;
  const bool aoAtlasSave = g_aoAtlas;
  g_litNormals = nullptr, g_envNormals = nullptr, g_aoSts = nullptr;
  g_aoAtlas = false;
  SceneObjectData unit = cdd;
  unit.position[0] = unit.position[1] = unit.position[2] = 0.0F;
  unit.rotation[0] = unit.rotation[1] = unit.rotation[2] = 0.0F;
  unit.scale[0] = unit.scale[1] = unit.scale[2] = 1.0F;
  for (int detail = cdd.primDetail < 1 ? 1 : cdd.primDetail; detail >= 1;
       detail = detail > 3 ? detail * 3 / 4 : detail - 1) {
    unit.primDetail = detail;
    BagArray<Vec4> verts;
    BagArray<Color> cols;
    BagArray<Vec4> sts;
    switch (cdd.type) {
      case 0: addBox(verts, cols, sts, unit); break;
      case 1: addSphere(verts, cols, sts, unit); break;
      case 2: addCylinder(verts, cols, sts, unit); break;
      default: addCone(verts, cols, sts, unit); break;
    }
    // buildShadowMesh reads flat xyz at a stride; repack the Vec4s
    std::vector<float> flat;
    flat.reserve(verts.size() * 3);
    for (const Vec4& v : verts) {
      flat.push_back(v.x);
      flat.push_back(v.y);
      flat.push_back(v.z);
    }
    std::vector<const std::vector<float>*> pv;
    pv.push_back(&flat);
    buildShadowMesh(pv, sm, 3);
    if (!sm.tri.empty()) break;
    // the curved builders clamp their detail at 3 - below that nothing
    // changes, so stop rather than rebuild the same mesh
    if (cdd.type != 0 && detail <= 3) break;
  }
  g_litNormals = litSave, g_envNormals = envSave, g_aoSts = aoStsSave;
  g_aoAtlas = aoAtlasSave;
  return sm.tri.empty() ? nullptr : &sm;
}

// A caster's volume: the silhouette mesh when the budget allows (a model's
// real triangles or its baked proxy, a primitive's unit mesh), its tight
// sub-boxes otherwise. Appends into outFront/outBack. Shared by the
// counting pre-pass. (A template over the model table because GameModel is
// a class-nested type this file-scope helper cannot name; `auto` never has
// to.)
template <typename ModelVec>
static void emitCasterVolume(const ProjBox& castPb, const ModelVec& gameModels,
                             const SceneObjectData& cdd, const Vec4& origin,
                             const Vec4& cam, float range, bool farCaps,
                             BagArray<Vec4>& outFront,
                             BagArray<Vec4>& outBack) {
  const ShadowMesh* mesh = primShadowMesh(cdd);
  if (cdd.type == 5 && cdd.model >= 0 &&
      cdd.model < (int)gameModels.size()) {
    if (g_shadowMeshes.size() != gameModels.size()) {
      g_shadowMeshes.assign(gameModels.size(), ShadowMesh());
      g_shadowMeshTried.assign(gameModels.size(), 0);
    }
    ShadowMesh& sm = g_shadowMeshes[cdd.model];
    if (!g_shadowMeshTried[cdd.model]) {
      g_shadowMeshTried[cdd.model] = 1;
      std::vector<const std::vector<float>*> pv;
      for (const auto& gp : gameModels[cdd.model].parts)
        pv.push_back(&gp.verts);
      buildShadowMesh(pv, sm);
      // Over budget: the build's decimated proxy, when it baked one. The
      // real mesh is tried first so a model that fits never casts from an
      // approximation.
      if (sm.tri.empty() && !gameModels[cdd.model].shadowVerts.empty()) {
        pv.clear();
        pv.push_back(&gameModels[cdd.model].shadowVerts);
        buildShadowMesh(pv, sm, 3);
      }
    }
    if (!sm.tri.empty()) mesh = &sm;
  }
  if (mesh) {
    emitMeshShadowVolume(*mesh, cdd, castPb, origin, cam, range, farCaps,
                         outFront, outBack);
    return;
  }
  ProjBox subBox[3];
  int subN = 0;
  if (cdd.type == 5 && cdd.model >= 0 && cdd.model < (int)gameModels.size()) {
    if (g_shadowSubBoxes.size() != gameModels.size())
      g_shadowSubBoxes.assign(gameModels.size(), std::vector<ShadowSubBox>());
    std::vector<ShadowSubBox>& sbs = g_shadowSubBoxes[cdd.model];
    if (sbs.empty()) {
      std::vector<const std::vector<float>*> pv;
      for (const auto& gp : gameModels[cdd.model].parts)
        pv.push_back(&gp.verts);
      buildShadowSubBoxes(pv, sbs);
    }
    for (const ShadowSubBox& box : sbs) {
      if (subN >= 3) break;
      ProjBox r = castPb;  // the basis and the object ride along
      float lc2[3], hh2[3];
      for (int a = 0; a < 3; ++a) {
        lc2[a] = 0.5F * (box.mn[a] + box.mx[a]) * cdd.scale[a];
        hh2[a] = 0.5F * (box.mx[a] - box.mn[a]) * cdd.scale[a];
        if (hh2[a] < 0.0F) hh2[a] = -hh2[a];
      }
      r.o[0] = cdd.position[0] + castPb.ax[0] * lc2[0] +
               castPb.ay[0] * lc2[1] + castPb.az[0] * lc2[2];
      r.o[1] = cdd.position[1] + castPb.ax[1] * lc2[0] +
               castPb.ay[1] * lc2[1] + castPb.az[1] * lc2[2];
      r.o[2] = cdd.position[2] + castPb.ax[2] * lc2[0] +
               castPb.ay[2] * lc2[1] + castPb.az[2] * lc2[2];
      r.h[0] = hh2[0], r.h[1] = hh2[1], r.h[2] = hh2[2];
      subBox[subN++] = r;
    }
  }
  if (subN == 0) subBox[subN++] = castPb;
  for (int si = 0; si < subN; ++si)
    emitBoxShadowVolume(subBox[si], origin, cam, range, farCaps, outFront,
                        outBack);
}

// THE RECEIVER PATCH'S SHAPE, shared by the setup that allocates it and the
// per-frame fill (renderProjShadows) - one definition, because the count the
// bag is created with and the count the fill writes must be the same number.
//
// 4x4 cells. As a triangle LIST that is 6 vertices a cell, 96 in all. As a
// TRIANGLE STRIP (docs/model-pipeline.md) each ROW of cells is one strip of
// 2 * (cells + 1) vertices, the rows are joined by the usual two-vertex
// degenerate seam, and the tail is padded to the multiple of 3 the VU1 vertex
// loops step by: 46 vertices, padded to 48. Half the list, for the same
// quads, the same STs and the same pixels - a patch is a grid, which is the
// shape a strip is best at. "The same quads" is a property the fill has to
// WORK for, not one it gets: see the diagonal note in renderProjShadows.
inline constexpr int kProjPatchCells = 4;
inline constexpr int kProjPatchListVerts = kProjPatchCells * kProjPatchCells * 6;
inline constexpr int kProjPatchStripVerts =
    ((2 * (kProjPatchCells + 1) * kProjPatchCells +
      2 * (kProjPatchCells - 1)) + 2) / 3 * 3;
// The A/B knob, on the same terms as TYRA_STRIP_WHEELS: 0 restores the list.
#ifndef TYRA_STRIP_PROJ_PATCH
#define TYRA_STRIP_PROJ_PATCH 1
#endif

// THE CHEAP CASTER BAG. 87% of the projected-shadow bracket is the caster's
// OWN model bags re-submitted from the light (the garage-day inventory: 60 of
// 69 packages, 4 440 of 4 632 vertices, and every one of them a car body).
// They are submitted exactly as the object loop submits them - textured, with
// per-vertex colours - which is the TEXTURE+COLOUR VU1 class at 75 vertices a
// package. The shadow map does not want either attribute:
// RendererCoreShadowMap is 64x64 and says so itself - no colour fidelity,
// only the alpha coverage matters, because the receiver draws black modulated
// by the silhouette's alpha.
//
// Drop both and the same geometry goes through the COLOUR class with a SINGLE
// colour, which is 150 vertices a package - exactly double. getMaxVertCount is
// (dbuffer - 9) / (colorElementsPerVertex + reglistCount) rounded down to a
// multiple of 3; the double buffer is (944 - 22) / 2 = 461, and cull_c is
// built with elementsPerVertex 2, reglistCount 2:
//   textured + per-vertex  452 / (3 + 3) -> 75    (what this pass submits now)
//   untextured + per-vertex 452 / (2 + 2) -> 111
//   untextured + SINGLE     452 / (1 + 2) -> 150
// No geometry changes, no second vertex array, no bake and no format change:
// the silhouette bag shares the part's own vertices and is re-aimed at them
// every submit (a LOD tier moves that pointer).
//
// WHY IT DEFAULTS TO 0. The colour half is exact - pushVert writes alpha 128
// for every model vertex, so per-vertex colour carries nothing the coverage
// reads, and a single 128 writes the same alpha. The TEXTURE half is not: the
// GS modulates alpha as well as RGB, so a caster whose texture has alpha -
// foliage, a chain-link fence, any alpha-tested cutout - gets its holes from
// the texture and would cast a solid blob without it. That is a per-model
// property this pass cannot see (Texture exposes no alpha predicate), so the
// knob is off until a project's casters are known to be opaque. In the
// vehicle playground both casters are vehicles (the only two shadowMode 3
// objects in the district) and their bodies are opaque palette bakes.
#ifndef TYRA_CHEAP_PROJ_CASTER
#define TYRA_CHEAP_PROJ_CASTER 0
#endif
// The one colour every cheap silhouette casts in. Alpha 128 is the whole
// point - it is what pushVert writes for every model vertex, so the coverage
// the shadow map receives is bit-for-bit what the per-vertex array produced.
// The RGB is never read: the receiver draws BLACK modulated by this alpha.
inline const Tyra::Color kProjSilhouetteColor(128.0F, 128.0F, 128.0F, 128.0F);

// Per frame, end of renderScene: for the nearest casters, render the
// object's EXISTING bags into a shadow-map slot from a "light camera"
// looking along the sun direction (one raster-redirect bracket per caster,
// one end() drain total), then drop each slot's receiver patch onto the
// terrain with per-vertex UVs computed through the captured light
// view-proj. Real silhouette shape - follows animation and movement.
/** Receiver surfaces for the projected shadows.
 *
 * The patch used to be built on the TERRAIN alone. That is fine outdoors and
 * useless indoors: a level made of geometry - a corridor, a hospital floor, a
 * platform, anything survival-horror shaped - has its real floor metres above the
 * heightfield, so the patch was laid down UNDER it and the shadow simply never
 * appeared. This answers the question that actually matters: what is the
 * highest solid surface at (x, z) at or below yMax, terrain included.
 *
 * Extents are the same box the WALKER stands on (collidePlayer's box mode:
 * a model's real mesh AABB, a primitive's unit scale box, rotation ignored),
 * so the shadow lands exactly where the feet do rather than on a second,
 * disagreeing idea of the floor.
 *
 * Candidates are collected ONCE per shadow and never per patch vertex - the
 * point-light dcache lesson. A patch is 25 unique points; scanning the object
 * table at each of them is how a big scene loses a millisecond per shadow. */
struct ProjRecv {
  float minX, maxX, minZ, maxZ, top;
};
inline std::vector<ProjRecv> g_projRecv;

// How a shadow-map slot changes hands (see "which four casters hold the
// slots" below). The margin and the ten frames are the spot-light count
// band's own numbers - two features answering "who gets the one resource"
// should not disagree about how patient they are - and the fade step is a
// third of a second at PAL, long enough to read as a dissolve and short
// enough that a real hand-over is not a wait.
inline constexpr int kProjHandoverFrames = 10;
inline constexpr float kProjFadeStep = 0.06F;
// ...and how long a holder that draws NOTHING keeps its slot. Half a second:
// long enough that a single bad frame (a caster mid-rebuild) is not a
// hand-over, short enough that a permanently unlit caster is not a leak.
inline constexpr int kProjBarrenFrames = 30;

// Spring arm (third person only): how far the camera may sit down the boom
// before it would end up inside geometry or under the terrain. Casts the boom
// from the pivot (the avatar's head) toward the desired eye and returns the
// first blocked distance, so the caller can pull the camera to the collision
// point instead of letting it punch through walls.
//
// Budget-driven shape - this runs every frame, so:
//  - AABB only, even for mesh-collision objects. Camera collision needs no
//    triangle precision (stopping a few cm early is invisible), and a slab
//    test is a few compares with no sqrt, vs walking a collider's triangles.
//  - The boom is short (PLAYER_CAM_DIST), so a 6-compare broad phase (boom
//    segment AABB vs object AABB) rejects nearly every object before any
//    division happens; only real candidates reach the slab test.
//  - Objects marked collision "none" and the markers/visual-only types are
//    skipped - including the avatar itself (type 6), which must never block
//    its own camera.
//  - The terrain march is a fixed 8 steps + 4 bisections over the distance
//    that SURVIVED the object pass (constant cost, and shorter once an object
//    already pulled the camera in).
inline constexpr float CAM_RADIUS = 0.3F;    // eye clearance kept off surfaces; must
                                      // exceed the 0.15 near clip
inline constexpr float CAM_MIN_DIST = 0.6F;

// Cylindrical captures are authored upright with a common horizontal scale.
// Legacy replacement meshes remain unrestricted by this additional contract.
inline bool billboardTransformValid(const SceneObjectData& d) {
  return !d.impostorBillboard || (fabsf(d.rotation[0]) < .001F &&
      fabsf(d.rotation[2]) < .001F && d.scale[0] > 0 && d.scale[1] > 0 &&
      fabsf(d.scale[0]-d.scale[2]) < .0001F);
}
inline int billboardView(const SceneObjectData& d, const Vec4& camera) {
  const float yaw = atan2f(camera.x-d.position[0], camera.z-d.position[2]);
  const float local = yaw - d.rotation[1]*PI/180.0F;
  const int v = (int)floorf(local*(d.impostorViews/(2.0F*PI))+.5F);
  return (v%d.impostorViews+d.impostorViews)%d.impostorViews;
}
inline SceneObjectData billboardTransform(const SceneObjectData& d, const Vec4& camera) {
  SceneObjectData facing = d;
  facing.rotation[1] = atan2f(camera.x-d.position[0], camera.z-d.position[2])*180.0F/PI;
  return facing;
}

// --- object physics ---------------------------------------------------------
// Every data.physics object is a rigid body (see "rigid bodies" below for the
// solver). Near-rest bodies fall asleep (restFrames) and cost one branch per
// frame until something wakes them, so a settled scene pays nothing.
inline constexpr float PHYS_REST_SPEED2 = 0.00025F;  // (units/frame)^2 = "not moving"
// A mover this fast into a SLEEPING body wakes it (~2.5 u/s at 50 fps; rest
// is ~0.8 u/s); slower contacts keep treating the sleeper as immovable, so
// settled stacks stay cheap and stable.
inline constexpr float PHYS_WAKE_SPEED2 = 0.0025F;
inline constexpr float PHYS_MAX_SPEED = 3.0F;        // units/frame velocity clamp
inline constexpr float PHYS_PUSH = 0.55F;

// Per-frame batch pass: catch changed members, rebuild whatever changed,
// then submit. This is the correctness net for the runtime-only mutation
// channels (Live Link edits, Raycast/custom-node latches fed into object
// actions, global scripts) that build-time eligibility cannot rule out:
// - a DIRTIED member (position/color/... actually mutated) is DEMOTED to
//   the solo path for the rest of the scene - a per-frame-animated member
//   would otherwise re-bake its whole batch every frame, which is slower
//   than the pre-batching status quo. The batch rebuilds once without it
//   and the solo path picks it up this same frame (its dirty stays set).
// - a visibility/residency flip vs the shown snapshot (hide/show can skip
//   the dirty flag) only rebuilds the batch in place - the member may well
//   reappear, and hides are events, not per-frame animation.
// Conservative software occlusion. 48x42 is deliberately tiny: its job is to
// reject whole bags before the expensive pipeline, not reproduce the GS. A
// one-cell erosion and expanded target rectangles make uncertainty visible
// rather than deleting geometry.
namespace runtime_detail {
inline constexpr int OCC_W=48, OCC_H=42;
inline float g_occDepth[OCC_W*OCC_H];
inline unsigned char g_occCover[OCC_W*OCC_H], g_occEroded[OCC_W*OCC_H];
inline M4x4 g_occVp;
inline float g_occSx=1.0F,g_occSy=1.0F;
inline int g_occTested=0,g_occHidden=0,g_occProxies=0;
inline bool occProject(const V3& p,float& x,float& y,float& w){
  const Vec4 c=g_occVp*Vec4(p.x,p.y,p.z,1.0F); w=c.w;
  if(w<=0.15F)return false;
  x=(0.5F+c.x/w*g_occSx*0.5F)*OCC_W;
  y=(0.5F+c.y/w*g_occSy*0.5F)*OCC_H;
  return true;
}
inline float occEdge(float ax,float ay,float bx,float by,float px,float py){
  return (bx-ax)*(py-ay)-(by-ay)*(px-ax);
}
struct OccPt{float x,y;};
inline bool occBox(const V3* v){
  OccPt p[8]; float farW=0.0F;
  float px0=1e30F,px1=-1e30F,py0=1e30F,py1=-1e30F;
#if TYRA_FRAME_PROFILE
  struct OccProjLap{u32 t0;~OccProjLap(){ftrig::occLap[5]+=Tyra::FrameProfile::ticks()-t0;}} occProjLap{Tyra::FrameProfile::ticks()};
#endif
  for(int i=0;i<8;++i){float w;if(!occProject(v[i],p[i].x,p[i].y,w))return false;
    if(w>farW)farW=w;
    px0=std::min(px0,p[i].x);px1=std::max(px1,p[i].x);
    py0=std::min(py0,p[i].y);py1=std::max(py1,p[i].y);}
  // The same rejects the rectangle below applies, taken BEFORE the sort and
  // the hull: a box off the buffer, or too thin to survive the erosion, can
  // never write a useful cell.
  if(px1<0.0F||py1<0.0F||px0>(float)OCC_W||py0>(float)OCC_H)return false;
  if(std::min(px1,(float)(OCC_W-1))-std::max(px0,0.0F)<1.0F||
     std::min(py1,(float)(OCC_H-1))-std::max(py0,0.0F)<1.0F)return false;
  // Eight points, so insertion sort is cheaper and smaller than pulling a
  // general sorter into the generated ELF.
  for(int i=1;i<8;++i){OccPt q=p[i];int j=i;
    while(j>0&&(p[j-1].x>q.x||(p[j-1].x==q.x&&p[j-1].y>q.y))){p[j]=p[j-1];--j;}p[j]=q;}
  OccPt h[16];int n=0;
  auto cross=[](const OccPt&a,const OccPt&b,const OccPt&c){
    return (b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);};
  for(int i=0;i<8;++i){while(n>=2&&cross(h[n-2],h[n-1],p[i])<=0.0F)--n;h[n++]=p[i];}
  const int lower=n;
  for(int i=6;i>=0;--i){while(n>lower&&cross(h[n-2],h[n-1],p[i])<=0.0F)--n;h[n++]=p[i];}
  if(n<4)return false;
  --n; // last point repeats the first
  float fx0=h[0].x,fx1=h[0].x,fy0=h[0].y,fy1=h[0].y;
  for(int i=1;i<n;++i){fx0=std::min(fx0,h[i].x);fx1=std::max(fx1,h[i].x);
    fy0=std::min(fy0,h[i].y);fy1=std::max(fy1,h[i].y);}
  int x0=(int)floorf(fx0),x1=(int)ceilf(fx1),y0=(int)floorf(fy0),y1=(int)ceilf(fy1);
  if(x0<0)x0=0;
  if(y0<0)y0=0;
  if(x1>=OCC_W)x1=OCC_W-1;
  if(y1>=OCC_H)y1=OCC_H-1;
  // Erosion below cannot leave a useful cell for a thinner projection.
  if(x1-x0<2||y1-y0<2)return false;
#if TYRA_FRAME_PROFILE
  const u32 occR0=Tyra::FrameProfile::ticks();
  struct OccRasterLap{u32 t0;~OccRasterLap(){ftrig::occLap[2]+=Tyra::FrameProfile::ticks()-t0;}} occRasterLap{occR0};
#endif
  // One span per row: the hull is convex, so the cells whose centre is inside
  // it on row Y form one run, bounded by where the row's centre line meets the
  // hull. Each edge that spans the line yields one x; a cell is inside exactly
  // when its centre lies between the smallest and largest of them - the same
  // cells the per-cell all-edges test accepted, edge-on included, at a cost
  // that follows the rows instead of rows x columns x edges (that was 1.0 ms
  // of a physical-PS2 frame for ten proxies).
  for(int Y=y0;Y<=y1;++Y){
    const float py=Y+0.5F;float sx0=1e30F,sx1=-1e30F;
    for(int e=0;e<n;++e){const OccPt&a=h[e],&b=h[(e+1)%n];
      if((a.y>py)==(b.y>py)){
        if(a.y==py){sx0=std::min(sx0,a.x);sx1=std::max(sx1,a.x);}
        continue;}
      const float t=(py-a.y)/(b.y-a.y);const float x=a.x+(b.x-a.x)*t;
      sx0=std::min(sx0,x);sx1=std::max(sx1,x);}
    if(sx0>sx1)continue;
    int X0=(int)ceilf(sx0-0.5F),X1=(int)floorf(sx1-0.5F);
    if(X0<x0)X0=x0;
    if(X1>x1)X1=x1;
    for(int X=X0;X<=X1;++X){const int i=Y*OCC_W+X;g_occCover[i]=1;
      if(farW<g_occDepth[i])g_occDepth[i]=farW;}
  }
  return true;
}
}
using namespace runtime_detail;

// ---------------------------------------------------------------------------
// Runtime procedural volumes and prefab instances
// (docs/procedural-runtime.md, docs/prefabs.md)
// ---------------------------------------------------------------------------
// Both end in ProcChunk: world-space vertex bags the GAME built, drawn like a
// static batch. The merge is not an optimization here, it is the feature - a
// static submit costs ~1 ms of fixed EE time whatever it holds, so "500 cubes"
// has to become a handful of bags before it can exist at all.

// Which face of a unit cube a vertex normal points along, or -1. Blocks Fill
// hands every instance a 6-bit mask of the faces a neighbour does NOT cover;
// this is how a merged mesh honours it. Any axis-aligned source face works -
// nothing about it is cube-specific - and a mesh with no axis-aligned faces
// simply never matches and is merged whole.
// terrainHeightAtScene takes the scene index; the generated evaluator wants a
// plain height function it can call from anywhere, so this is the adapter.
inline float procTerrainY(float x, float z) {
  return terrainHeightAtScene(g_activeScene, x, z);
}

// Does MODEL_SOURCES[m] name this asset? The generated evaluator stores asset
// SLOTS and resolves them by source path once per generation - the model table
// is keyed on (source, .mtl override) and a procedural asset never carries an
// override, so the first source match is the right one.
inline bool modelSourceMatches(int m, const char* srcPath) {
  return m >= 0 && m < MODEL_COUNT && !strcmp(MODEL_SOURCES[m], srcPath);
}

// --- block ambient occlusion ------------------------------------------------
// The block lattice is the one piece of runtime geometry that can occlude
// ITSELF, and the only one that already knows how: Blocks Fill publishes a
// collision field saying which cells are solid, so the corner darkening a
// voxel world lives on costs a handful of bit tests per block at generation
// time and nothing per frame. Everything else generated at runtime is lit
// from the probe grid and the baked occluder table
// (docs/ambient-occlusion.md), and neither of those can see geometry that did
// not exist when the scene was baked.
//
// Face index is faceOfNormal's, which is also the bit order of Blocks Fill's
// visible-face mask: 0 = +X, 1 = -X, 2 = +Y, 3 = -Y, 4 = +Z, 5 = -Z. Both
// read the ASSET's local axes, so a block asset placed with a rotation
// mismatches the lattice here exactly as it already does for face culling.
//   kProcFaceAxis/kProcFaceDir - the axis the face looks along, and which way
//   kProcFaceU/kProcFaceV      - its two in-plane axes, in the order the
//                                corner index counts them:
//                                corner = (v > 0) * 2 + (u > 0).
inline const int kProcFaceAxis[6] = {0, 0, 1, 1, 2, 2};
inline const int kProcFaceDir[6] = {1, -1, 1, -1, 1, -1};
inline const int kProcFaceU[6] = {2, 2, 0, 0, 0, 0};
inline const int kProcFaceV[6] = {1, 1, 2, 2, 1, 1};

/** One cell of the 3x3x3 neighbourhood word procBlockVertexAo builds. */
inline bool procNbSolid(unsigned int nb, int dx, int dy, int dz) {
  return ((nb >> ((dz + 1) * 9 + (dy + 1) * 3 + (dx + 1))) & 1u) != 0u;
}

/** Which of a face's four corner levels a vertex sits on. A block asset is
 * authored as a unit cube, so its two in-plane local coordinates land on
 * +-0.5 and this picks a corner exactly; interpolating rather than snapping
 * is what keeps a SUBDIVIDED block asset smooth instead of banded. */
inline unsigned char procBlockAoAt(const unsigned char* ao, int face,
                                   const float* v) {
  float fu = v[kProcFaceU[face]] + 0.5F;
  float fv = v[kProcFaceV[face]] + 0.5F;
  if (fu < 0.0F) fu = 0.0F;
  else if (fu > 1.0F) fu = 1.0F;
  if (fv < 0.0F) fv = 0.0F;
  else if (fv > 1.0F) fv = 1.0F;
  const unsigned char* q = ao + face * 4;
  const float lo = (float)q[0] + ((float)q[1] - (float)q[0]) * fu;
  const float hi = (float)q[2] + ((float)q[3] - (float)q[2]) * fu;
  return (unsigned char)(lo + (hi - lo) * fv + 0.5F);
}

inline int faceOfNormal(float nx, float ny, float nz) {
  const float t = 0.85F;
  if (nx > t) return 0;
  if (nx < -t) return 1;
  if (ny > t) return 2;
  if (ny < -t) return 3;
  if (nz > t) return 4;
  if (nz < -t) return 5;
  return -1;
}

// Can a texel of this texture blend with what is already in the
// framebuffer? Judged once per texture from the pixels the game uploads:
// any alpha under 0x7F (the loader maps a PNG tRNS 255 to 127 and a 32-bit
// alpha 255 to 128) counts, cutouts included - their bilinear edges blend.
inline bool textureMayBlend(const Tyra::Texture* t) {
  if (t == nullptr || t->core == nullptr || t->core->data == nullptr)
    return false;  // render targets: their bags' own alpha says it
  static std::map<u32, bool> cache;
  auto it = cache.find(t->id);
  if (it != cache.end()) return it->second;
  const Tyra::TextureData* c = t->core;
  bool blend = false;
  const u32 n = (u32)c->width * (u32)c->height;
  if (c->components == TEXTURE_COMPONENTS_RGBA) {
    if (c->bpp == Tyra::bpp32) {
      for (u32 i = 0; i < n && !blend; ++i) blend = c->data[i * 4 + 3] < 0x7F;
    } else if ((c->bpp == Tyra::bpp8 || c->bpp == Tyra::bpp4) &&
               t->clut != nullptr && t->clut->data != nullptr) {
      bool used[256] = {};
      if (c->bpp == Tyra::bpp8) {
        for (u32 i = 0; i < n; ++i) used[c->data[i]] = true;
      } else {
        for (u32 i = 0; i < (n + 1) / 2; ++i) {
          used[c->data[i] & 0x0F] = true;
          used[c->data[i] >> 4] = true;
        }
      }
      const u32 entries = c->bpp == Tyra::bpp8 ? 256 : 16;
      for (u32 l = 0; l < entries && !blend; ++l) {
        if (!used[l]) continue;
        // The 8-bit CLUT is stored in the GS's CSM1 order (png_loader's
        // "rotate clut"): entries 8-15 and 16-23 of every 32 swap places.
        u32 at = l;
        if (entries == 256) {
          if ((l & 0x18) == 0x08) at = l + 8;
          else if ((l & 0x18) == 0x10) at = l - 8;
        }
        blend = t->clut->data[at * 4 + 3] < 0x7F;
      }
    }
  }
  cache[t->id] = blend;
  return blend;
}

// Height of the baked road triangle under a decal sample. This deliberately
// reads the already-generated chunks instead of evaluating the authoring
// spline again: junction fans, lateral terrain tessellation and strip/list A/B
// builds then all answer from the exact surface the GS receives. The AABB
// reject makes the common off-road query 68 cheap comparisons; only the one or
// two chunks under the sample pay triangle tests.
// Acceptance gate for the road-height grid below (docs/roads.md). Default 0:
// the check costs far more than the work it checks, so it never ships and
// never goes into a measurement. Set it to 1, rebuild the game and drive the
// map - every query is then answered twice, once through the grid and once by
// the exhaustive walk the grid replaced, and the two must agree exactly. The
// running tally is logged as ROADINDEXVERIFY, and a disagreement names the
// point that produced it.
#ifndef TYRA_ROAD_INDEX_VERIFY
#define TYRA_ROAD_INDEX_VERIFY 0
#endif

#if TYRA_ROAD_INDEX_VERIFY
// The pre-2026-09-22 implementation, kept verbatim as the oracle. Deliberately
// NOT refactored to share code with the fast path: independent code catches
// more, and a shared helper would only prove the helper agrees with itself.

#endif

// Road height under a world point, and the frame's most expensive function
// until 2026-09-22. It is sampled 17 times per blob shadow, per light pool and
// per glow patch - each of those builds a 4x4 receiver lattice - and it used to
// walk EVERY triangle of every road chunk whose box contains the point. On the
// Motor District (physical PS2) that was about 2 100 triangles per query: one
// parked car paid 0.91 ms for its shadow alone at an ordinary road pose, and a
// junction where several chunks overlap costs far more. Bisected on hardware,
// roughly half of that was walking the vertices and half the barycentric test.
//
// A chunk box is not selective enough - road chunks overlap and one chunk is
// ~400 vertices - so the triangles are bucketed into a uniform XZ grid once,
// after the roads are built. A query then tests the handful in one cell.


// --- rigid bodies ------------------------------------------------------------
// The body is a real rigid body now (docs/physics.md): a centre of mass, an
// orientation quaternion, linear AND angular velocity and an inertia tensor
// from the solid convex hull the build baked for its mesh (PHYS_HULLS). A
// frame predicts the pose, collects CONTACT POINTS against that prediction -
// hull corners in the terrain, in static boxes and in collision meshes, box
// corners in the hull, hull against hull - and resolves them all together
// with sequential impulses: restitution, Coulomb friction, and a split
// impulse for the penetration so pushing out never adds bounce. A stool
// stands on its four feet and tips over its edge; a railing falls flat along
// its length; a ball rolls because friction at its contact turns it.
//
// Budget: every body carries at most PHYS_MAX_HULL_VERTS corners, and each
// source of contact is reduced to the four points that span it, so the
// solver never sees more than a few contacts per touching pair however
// detailed the mesh was. Sleeping bodies still cost one branch; a sleeping
// body only turns into a (static) contact partner when an awake one comes
// within its bounding sphere.
namespace runtime_detail {

static_assert(PHYS_MAX_HULL_VERTS <= 24 && PHYS_MAX_HULL_PLANES <= 44,
              "PhysBody::lv / lp are sized for physhull::kMaxVerts / kMaxPlanes");

struct RbV {
  float x, y, z;
};
inline RbV rbV(float x, float y, float z) {
  RbV r;
  r.x = x, r.y = y, r.z = z;
  return r;
}
inline RbV rbAdd(RbV a, RbV b) { return rbV(a.x + b.x, a.y + b.y, a.z + b.z); }
inline RbV rbSub(RbV a, RbV b) { return rbV(a.x - b.x, a.y - b.y, a.z - b.z); }
inline RbV rbMul(RbV a, float s) { return rbV(a.x * s, a.y * s, a.z * s); }
inline float rbDot(RbV a, RbV b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
inline RbV rbCross(RbV a, RbV b) {
  return rbV(a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z,
             a.x * b.y - a.y * b.x);
}
// 3x3 row-major
inline RbV rbMat(const float* m, RbV v) {
  return rbV(m[0] * v.x + m[1] * v.y + m[2] * v.z,
             m[3] * v.x + m[4] * v.y + m[5] * v.z,
             m[6] * v.x + m[7] * v.y + m[8] * v.z);
}
inline RbV rbMatT(const float* m, RbV v) {
  return rbV(m[0] * v.x + m[3] * v.y + m[6] * v.z,
             m[1] * v.x + m[4] * v.y + m[7] * v.z,
             m[2] * v.x + m[5] * v.y + m[8] * v.z);
}

inline void rbQuatNormalize(float* q) {
  const float l2 = q[0] * q[0] + q[1] * q[1] + q[2] * q[2] + q[3] * q[3];
  const float inv = l2 > 1e-12F ? 1.0F / sqrtf(l2) : 0.0F;
  if (inv == 0.0F) {
    q[0] = 1.0F, q[1] = q[2] = q[3] = 0.0F;
    return;
  }
  for (int k = 0; k < 4; ++k) q[k] *= inv;
}

inline void rbQuatToMat(const float* q, float* m) {
  const float w = q[0], x = q[1], y = q[2], z = q[3];
  m[0] = 1.0F - 2.0F * (y * y + z * z);
  m[1] = 2.0F * (x * y - w * z);
  m[2] = 2.0F * (x * z + w * y);
  m[3] = 2.0F * (x * y + w * z);
  m[4] = 1.0F - 2.0F * (x * x + z * z);
  m[5] = 2.0F * (y * z - w * x);
  m[6] = 2.0F * (x * z - w * y);
  m[7] = 2.0F * (y * z + w * x);
  m[8] = 1.0F - 2.0F * (x * x + y * y);
}

inline void rbMatToQuat(const float* m, float* q) {
  const float tr = m[0] + m[4] + m[8];
  if (tr > 0.0F) {
    const float s = sqrtf(tr + 1.0F) * 2.0F;
    q[0] = 0.25F * s;
    q[1] = (m[7] - m[5]) / s;
    q[2] = (m[2] - m[6]) / s;
    q[3] = (m[3] - m[1]) / s;
  } else if (m[0] > m[4] && m[0] > m[8]) {
    const float s = sqrtf(1.0F + m[0] - m[4] - m[8]) * 2.0F;
    q[0] = (m[7] - m[5]) / s;
    q[1] = 0.25F * s;
    q[2] = (m[1] + m[3]) / s;
    q[3] = (m[2] + m[6]) / s;
  } else if (m[4] > m[8]) {
    const float s = sqrtf(1.0F + m[4] - m[0] - m[8]) * 2.0F;
    q[0] = (m[2] - m[6]) / s;
    q[1] = (m[1] + m[3]) / s;
    q[2] = 0.25F * s;
    q[3] = (m[5] + m[7]) / s;
  } else {
    const float s = sqrtf(1.0F + m[8] - m[0] - m[4]) * 2.0F;
    q[0] = (m[3] - m[1]) / s;
    q[1] = (m[2] + m[6]) / s;
    q[2] = (m[5] + m[7]) / s;
    q[3] = 0.25F * s;
  }
  rbQuatNormalize(q);
}

// The object's Euler angles are Rz * Ry * Rx (rotated()); the matrix comes
// from the very same rotatedBy() the vertex bake uses, so a body the sim has
// just picked up cannot turn by a rounding step.
inline void rbEulerToMat(const float* rotDeg, float* m) {
  const RotTrig t = rotTrigOf(rotDeg);
  const V3 bx = rotatedBy({1.0F, 0.0F, 0.0F}, t);
  const V3 by = rotatedBy({0.0F, 1.0F, 0.0F}, t);
  const V3 bz = rotatedBy({0.0F, 0.0F, 1.0F}, t);
  m[0] = bx.x, m[3] = bx.y, m[6] = bx.z;
  m[1] = by.x, m[4] = by.y, m[7] = by.z;
  m[2] = bz.x, m[5] = bz.y, m[8] = bz.z;
}

inline void rbMatToEuler(const float* m, float* rotDeg) {
  float sb = -m[6];
  if (sb > 1.0F) sb = 1.0F;
  if (sb < -1.0F) sb = -1.0F;
  const float b = asinf(sb);
  float a, c;
  if (sb < 0.9999F && sb > -0.9999F) {
    a = atan2f(m[7], m[8]);
    c = atan2f(m[3], m[0]);
  } else {  // gimbal lock: fold the roll into X
    a = atan2f(-m[5], m[4]);
    c = 0.0F;
  }
  rotDeg[0] = a * (180.0F / PI);
  rotDeg[1] = b * (180.0F / PI);
  rotDeg[2] = c * (180.0F / PI);
}

// q += 0.5 * (0, w) * q, renormalized - w is radians/frame in world space.
inline void rbIntegrate(float* q, RbV w) {
  const float qw = q[0], qx = q[1], qy = q[2], qz = q[3];
  q[0] += 0.5F * (-w.x * qx - w.y * qy - w.z * qz);
  q[1] += 0.5F * (w.x * qw + w.y * qz - w.z * qy);
  q[2] += 0.5F * (w.y * qw + w.z * qx - w.x * qz);
  q[3] += 0.5F * (w.z * qw + w.x * qy - w.y * qx);
  rbQuatNormalize(q);
}

// World inverse inertia R * Ib^-1 * R^T from the body-frame symmetric one.
inline void rbWorldInvI(const float* R, const float* s, float* out) {
  const float ib[9] = {s[0], s[3], s[4], s[3], s[1], s[5], s[4], s[5], s[2]};
  float t[9];
  for (int r = 0; r < 3; ++r)
    for (int c = 0; c < 3; ++c)
      t[r * 3 + c] = R[r * 3] * ib[c] + R[r * 3 + 1] * ib[3 + c] +
                     R[r * 3 + 2] * ib[6 + c];
  for (int r = 0; r < 3; ++r)
    for (int c = 0; c < 3; ++c)
      out[r * 3 + c] = t[r * 3] * R[c * 3] + t[r * 3 + 1] * R[c * 3 + 1] +
                       t[r * 3 + 2] * R[c * 3 + 2];
}

struct RbStep {
  int obj;
  int slot;
  bool asleep;     // a sleeping body taking part as an immovable partner
  bool grounded;   // something below carried it this frame
  bool sphere;
  float sphereR;
  float invMass;
  float bounce, friction;
  RbV x0, x1;      // centre of mass: start of frame, predicted
  float q0[4];
  float R0[9], R1[9];
  float invIw[9];
  RbV v, w;        // velocities being solved
  RbV vp, wp;      // split-impulse pseudo velocities (position only)
  int nv;
  RbV wv0[PHYS_MAX_HULL_VERTS];  // hull corners at the start pose
  RbV wv[PHYS_MAX_HULL_VERTS];   // ... and at the predicted pose
};

struct RbContact {
  short a, b;     // RbStep indices; b = -1 is the world
  RbV n;          // pushes a away from b
  RbV p;          // world point
  float depth;
  float vnPred;   // normal velocity at creation (predicted motion)
  float bounceTarget;
  float mu;
  float kn;
  float jn, jp;
  RbV ft;         // accumulated friction impulse
  RbV ra, rb;
};

struct RbCand {
  RbV n, p;
  float depth;
};

// Up to four points that span a contact patch: the deepest, the one
// farthest from it, the one farthest from that segment, then the one that
// adds the most area. A crate face flat on the ground keeps its four
// corners; a ring of cylinder rim points keeps a stable quadrilateral.
inline int rbReduce(const RbCand* in, int n, RbCand* out) {
  if (n <= 4) {
    for (int i = 0; i < n; ++i) out[i] = in[i];
    return n;
  }
  int pick[4] = {0, -1, -1, -1};
  for (int i = 1; i < n; ++i)
    if (in[i].depth > in[pick[0]].depth) pick[0] = i;
  float best = -1.0F;
  for (int i = 0; i < n; ++i) {
    const RbV d = rbSub(in[i].p, in[pick[0]].p);
    const float l = rbDot(d, d);
    if (l > best) best = l, pick[1] = i;
  }
  best = -1.0F;
  const RbV ab = rbSub(in[pick[1]].p, in[pick[0]].p);
  for (int i = 0; i < n; ++i) {
    const RbV c = rbCross(ab, rbSub(in[i].p, in[pick[0]].p));
    const float l = rbDot(c, c);
    if (l > best) best = l, pick[2] = i;
  }
  best = -1.0F;
  for (int i = 0; i < n; ++i) {
    if (i == pick[0] || i == pick[1] || i == pick[2]) continue;
    float area = 0.0F;
    for (int e = 0; e < 3; ++e) {
      const RbV a = rbSub(in[pick[e]].p, in[i].p);
      const RbV b = rbSub(in[pick[(e + 1) % 3]].p, in[i].p);
      const RbV c = rbCross(a, b);
      area += rbDot(c, c);
    }
    if (area > best) best = area, pick[3] = i;
  }
  int m = 0;
  for (int k = 0; k < 4; ++k) {
    if (pick[k] < 0) continue;
    bool dup = false;
    for (int e = 0; e < k; ++e) dup = dup || pick[e] == pick[k];
    if (!dup) out[m++] = in[pick[k]];
  }
  return m;
}

// The deepest face of a convex body (planes in its own centre-of-mass
// frame) that point `l` is inside; -1 when outside any of them.
inline int rbInsideHull(const float* lp, int np, RbV l, float* depth) {
  int best = -1;
  float bd = 1e30F;
  for (int k = 0; k < np; ++k) {
    const float* pl = lp + k * 4;
    const float d = pl[3] - (pl[0] * l.x + pl[1] * l.y + pl[2] * l.z);
    if (d <= 0.0F) return -1;
    if (d < bd) bd = d, best = k;
  }
  *depth = bd;
  return best;
}

inline constexpr int PHYS_ITERATIONS = 6;        // velocity passes per frame
inline constexpr int PHYS_POS_ITERATIONS = 3;    // split-impulse passes
inline constexpr int PHYS_MAX_CONTACTS = 384;
inline constexpr float PHYS_SLOP = 0.005F;       // units of allowed overlap
inline constexpr float PHYS_BAUMGARTE = 0.5F;    // fraction of overlap fixed per frame
inline constexpr float PHYS_MAX_SPIN = 0.6F;     // radians/frame clamp
inline constexpr float PHYS_REST_W2 = 0.00017F;  // (radians/frame)^2 = "not spinning"

}
using namespace runtime_detail;

// Macro ground variation (docs/terrain-painting.md): deterministic value
// noise over WORLD position - two smoothstepped octaves - multiplied into the
// vertex shade below. Large soft patches of lighter/darker ground at zero
// runtime cost, with an infinite period (breaks even the stochastic
// supertile's second-order repetition). Twin of tintNoise2 in the editor
// viewport (viewport.cpp buildTerrainChunkMesh) - keep the formulas in sync.
inline float tintHash(int ix, int iz) {
  unsigned h = (unsigned)ix * 73856093u ^ (unsigned)iz * 19349663u;
  h ^= h >> 13;
  h *= 0x85EBCA6Bu;
  h ^= h >> 16;
  return (float)(h & 0xFFFFu) / 65535.0F;
}
inline float tintValue(float x, float z, float scale) {
  const float gx = x / scale, gz = z / scale;
  const float fxf = floorf(gx), fzf = floorf(gz);
  const int ix = (int)fxf, iz = (int)fzf;
  float fx = gx - fxf, fz = gz - fzf;
  fx = fx * fx * (3.0F - 2.0F * fx);  // smoothstep = soft round patches
  fz = fz * fz * (3.0F - 2.0F * fz);
  const float a = tintHash(ix, iz), b = tintHash(ix + 1, iz);
  const float c = tintHash(ix, iz + 1), d = tintHash(ix + 1, iz + 1);
  return (a * (1.0F - fx) + b * fx) * (1.0F - fz) +
         (c * (1.0F - fx) + d * fx) * fz;
}
inline float tintNoise2(float x, float z, float scale) {
  return tintValue(x, z, scale) * 0.7F +
         tintValue(x + 191.0F, z - 353.0F, scale * 0.37F) * 0.3F;
}

